/** 월드는 XZ 평면이다. Y 는 높이이며 대부분의 판정에서 무시된다. */
export interface WorldPoint {
  readonly x: number
  readonly z: number
}

/** 원형 영역. 물·용암·빙판·성·바이옴이 전부 이 형태다. */
export interface WorldCircle extends WorldPoint {
  readonly r: number
}

/** 도넛형 수역: 원 안에서 `holes` 에 포함되면 육지로 친다. */
export interface WaterBody extends WorldCircle {
  readonly holes: readonly WorldCircle[]
}

/** 순례길 한 구간. 선분에서 `w` 이내면 길 위로 친다. */
export interface PathSegment {
  readonly ax: number
  readonly az: number
  readonly bx: number
  readonly bz: number
  readonly w: number
}

