/** 창살 높이 38, 중심 y 19. 개방 시 y 가 `19 + 46` 까지 올라간다. */
export const INNER_GATE_BAR_H = 38
export const INNER_GATE_OPEN_RATE = 0.45 // 초당 개방 진행도

/**
 * 봉인선에서 천국 원반을 가로지르는 반폭.
 * 원본 `Math.sqrt(max(1, HEAVEN_WALK² - (z - HEAVEN.z)²))`.
 * `SEAL_Z` 기준 ≈ 109.8 — 물리(원반 반경 112)와 시각이 여기서 맞물린다.
 */
export function heavenChordHalfWidth(z: number): number {
  const dz = z - HEAVEN_CENTER.z
  return Math.sqrt(Math.max(1, HEAVEN_WALK * HEAVEN_WALK - dz * dz))
}

