/**
 * 클라이언트 ↔ 서버 메시지.
 *
 * 전송은 JSON 이다. 스냅샷 크기가 문제가 되면 codec.ts 에 DataView 인코더를 붙이되,
 * **메시지 타입 정의는 여기 한 곳에만 둔다.**
 *
 * 보안 원칙: 클라이언트를 신뢰하지 않는다.
 * - 클라는 "무엇을 하고 싶은지"만 보낸다 (이동 방향, 공격 의사).
 * - 좌표·데미지·보스 HP·진행 게이트는 **전부 서버가 정한다.**
 * - 클라가 보낸 dt 는 상한 클램프에만 쓰고, 시뮬 기준은 서버 틱이다 (speed-hack 차단).
 */

import type { GateSave } from '../progress/gates'

/** 프로토콜 버전. 클라·서버가 다르면 핸드셰이크에서 거부한다. */
export const PROTOCOL_VERSION = 1

/** 룸 정원 — 8직업과 맞춘다. */
export const ROOM_CAPACITY = 8

/** 입력 비트마스크. 키보드/터치/게임패드 어댑터가 이 비트만 채운다. */
export const ACTION = {
  ATTACK: 1 << 0,
  JUMP: 1 << 1,
  SPECIAL: 1 << 2,
  RUN: 1 << 3,
} as const

export type ActionMask = number

export interface InputFrame {
  readonly seq: number
  /** 클라가 이 입력에 쓴 dt(초). 서버는 상한 0.1 로 클램프한다. */
  readonly dt: number
  /** 카메라 상대 이동 입력. 각 축 −1..1 */
  readonly moveX: number
  readonly moveZ: number
  /** 캐릭터가 바라보는 방향(rad). 공격 판정의 전방 기준이 된다. */
  readonly yaw: number
  readonly actions: ActionMask
}

export type ClientMsg =
  | { readonly t: 'join'; readonly protocol: number; readonly roomCode?: string; readonly name: string; readonly save?: unknown }
  | { readonly t: 'input'; readonly frame: InputFrame }
  | { readonly t: 'pickClass'; readonly classId: string }
  | { readonly t: 'learnSkill'; readonly nodeId: string }
  | { readonly t: 'respec' }
  | { readonly t: 'buyWeapon'; readonly weaponId: string }
  | { readonly t: 'equipWeapon'; readonly weaponId: string }
  | { readonly t: 'respawn' }
  | { readonly t: 'chat'; readonly text: string }
  | { readonly t: 'ping'; readonly clientTime: number }
  | { readonly t: 'debug'; readonly action: DebugAction }

/** ALLOW_DEBUG=1 일 때만 처리한다. 꺼져 있으면 조용히 버린다. */
export type DebugAction =
  | { readonly a: 'killBoss'; readonly bossId: string }
  | { readonly a: 'teleport'; readonly x: number; readonly z: number }
  | { readonly a: 'setLevel'; readonly level: number }
  | { readonly a: 'giveGold'; readonly amount: number }

/** 스냅샷에 실리는 플레이어 1명. 다른 사람에게도 보이는 정보만 담는다. */
export interface PlayerSnapshot {
  readonly id: number
  readonly name: string
  readonly classId: string | null
  readonly x: number
  readonly y: number
  readonly z: number
  readonly yaw: number
  readonly hp: number
  readonly maxHp: number
  readonly level: number
  readonly weaponId: string
  /** 애니메이션 상태 비트: 이동/달리기/점프/공격/특수기/사망 */
  readonly anim: number
}

export const ANIM = {
  MOVING: 1 << 0,
  RUNNING: 1 << 1,
  AIRBORNE: 1 << 2,
  ATTACKING: 1 << 3,
  SPECIAL: 1 << 4,
  DEAD: 1 << 5,
  INVULN: 1 << 6,
} as const

export interface MobSnapshot {
  readonly id: number
  readonly type: string
  readonly x: number
  readonly y: number
  readonly z: number
  readonly yaw: number
  readonly hp: number
  readonly maxHp: number
  /** 보스 무적 페이즈 중이면 true — 클라가 "무효" 표시를 낸다 */
  readonly invuln: boolean
}

/** 본인에게만 보내는 상세 상태. 남에게 노출할 이유가 없다. */
export interface SelfSnapshot {
  readonly gold: number
  readonly xp: number
  readonly xpNeed: number
  readonly sp: number
  readonly skills: Readonly<Record<string, number>>
  readonly owned: readonly string[]
  readonly specialCooldown: number
  readonly burnT: number
  readonly slowT: number
  readonly invulnT: number
}

export type ServerMsg =
  | {
      readonly t: 'hello'
      readonly protocol: number
      readonly playerId: number
      readonly roomCode: string
      readonly tickRate: number
      readonly worldSeed: number
      readonly sharedHash: string
    }
  | { readonly t: 'reject'; readonly reason: string }
  | {
      readonly t: 'snapshot'
      readonly tick: number
      readonly ackSeq: number
      readonly players: readonly PlayerSnapshot[]
      readonly mobs: readonly MobSnapshot[]
      readonly self: SelfSnapshot
      readonly gates: GateSave
    }
  | { readonly t: 'event'; readonly ev: GameEvent }
  | { readonly t: 'pong'; readonly clientTime: number; readonly serverTime: number }

export type GameEvent =
  | { readonly k: 'bossKilled'; readonly bossId: string; readonly by: readonly number[] }
  | { readonly k: 'runeLit'; readonly lordId: string; readonly count: 1 | 2 | 3 }
  | { readonly k: 'cutsceneStart' }
  | { readonly k: 'gateOpened' }
  | { readonly k: 'sealBroken' }
  | { readonly k: 'loot'; readonly weaponId: string; readonly to: readonly number[] }
  | { readonly k: 'levelUp'; readonly playerId: number; readonly level: number }
  | { readonly k: 'damage'; readonly targetId: number; readonly amount: number; readonly crit: boolean; readonly isMob: boolean }
  | { readonly k: 'playerDied'; readonly playerId: number }
  | { readonly k: 'mobDied'; readonly mobId: number; readonly x: number; readonly z: number; readonly gold: number }
  | { readonly k: 'shockwave'; readonly x: number; readonly z: number; readonly radius: number; readonly bossId: string }
  /**
   * 영역 타격이 일어난 범위.
   *
   * **서버가 실제로 판정한 값을 그대로 싣는다.** 클라가 반경을 따로 계산하면
   * "보이는 범위" 와 "맞는 범위" 가 갈린다 — 그러면 연출이 거짓말이 된다.
   */
  | {
      readonly k: 'aoe'
      readonly x: number
      readonly z: number
      readonly radius: number
      readonly color: number
      /** burst 즉발 · field 지속 장판 · cone 전방 부채꼴 */
      readonly shape: 'burst' | 'field' | 'cone'
      /** cone 일 때 정면 방향(rad) */
      readonly yaw?: number
      /** cone 일 때 반각(rad). 서버의 `facingDotMin` 을 각도로 바꾼 값이다 */
      readonly halfAngle?: number
      /** field 일 때 지속 시간(초) */
      readonly duration?: number
    }
  | { readonly k: 'joined'; readonly playerId: number; readonly name: string }
  | { readonly k: 'left'; readonly playerId: number }
  | { readonly k: 'chat'; readonly playerId: number; readonly name: string; readonly text: string }
  | { readonly k: 'toast'; readonly text: string }

/** 서버가 받은 원시 데이터를 신뢰하지 않고 형태부터 검사한다. */
export function parseClientMsg(raw: unknown): ClientMsg | null {
  if (typeof raw !== 'object' || raw === null) return null
  const m = raw as Record<string, unknown>
  if (typeof m['t'] !== 'string') return null
  switch (m['t']) {
    case 'join':
      return typeof m['name'] === 'string' && typeof m['protocol'] === 'number'
        ? (raw as ClientMsg)
        : null
    case 'input': {
      const f = m['frame']
      if (typeof f !== 'object' || f === null) return null
      const fr = f as Record<string, unknown>
      const nums = ['seq', 'dt', 'moveX', 'moveZ', 'yaw', 'actions']
      for (const k of nums) {
        const v = fr[k]
        if (typeof v !== 'number' || !Number.isFinite(v)) return null
      }
      return raw as ClientMsg
    }
    case 'pickClass':
    case 'learnSkill':
    case 'buyWeapon':
    case 'equipWeapon':
    case 'chat':
      return raw as ClientMsg
    case 'respec':
    case 'respawn':
    case 'ping':
    case 'debug':
      return raw as ClientMsg
    default:
      return null
  }
}
