/**
 * 불변 벡터 연산.
 *
 * 모든 함수는 새 객체를 반환한다. 입력을 변형하지 않는다.
 * 클라이언트 예측과 서버 판정이 **비트 단위로 같아야** rubber-banding 이 없으므로
 * 여기에는 분기가 갈릴 여지가 있는 최적화를 넣지 않는다.
 */

export interface Vec2 {
  readonly x: number
  readonly y: number
}

export interface Vec3 {
  readonly x: number
  readonly y: number
  readonly z: number
}

export const ZERO2: Vec2 = Object.freeze({ x: 0, y: 0 })
export const ZERO3: Vec3 = Object.freeze({ x: 0, y: 0, z: 0 })

export function vec2(x: number, y: number): Vec2 {
  return { x, y }
}

export function vec3(x: number, y: number, z: number): Vec3 {
  return { x, y, z }
}

export function add3(a: Vec3, b: Vec3): Vec3 {
  return { x: a.x + b.x, y: a.y + b.y, z: a.z + b.z }
}

export function sub3(a: Vec3, b: Vec3): Vec3 {
  return { x: a.x - b.x, y: a.y - b.y, z: a.z - b.z }
}

export function scale3(a: Vec3, s: number): Vec3 {
  return { x: a.x * s, y: a.y * s, z: a.z * s }
}

export function len3(a: Vec3): number {
  return Math.hypot(a.x, a.y, a.z)
}

export function norm3(a: Vec3): Vec3 {
  const l = len3(a)
  return l === 0 ? ZERO3 : scale3(a, 1 / l)
}

export function dot3(a: Vec3, b: Vec3): number {
  return a.x * b.x + a.y * b.y + a.z * b.z
}

/** XZ 평면 거리. 이 게임의 대부분의 판정(어그로·사거리·존)은 높이를 무시한다. */
export function distXZ(a: Vec3, b: Vec3): number {
  return Math.hypot(a.x - b.x, a.z - b.z)
}

/** XZ 평면 거리의 제곱. 반경 비교에서 sqrt 를 피할 때 쓴다. */
export function distXZSq(a: Vec3, b: Vec3): number {
  const dx = a.x - b.x
  const dz = a.z - b.z
  return dx * dx + dz * dz
}

export function len2(a: Vec2): number {
  return Math.hypot(a.x, a.y)
}

export function norm2(a: Vec2): Vec2 {
  const l = len2(a)
  return l === 0 ? ZERO2 : { x: a.x / l, y: a.y / l }
}

export function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t
}

export function lerp3(a: Vec3, b: Vec3, t: number): Vec3 {
  return { x: lerp(a.x, b.x, t), y: lerp(a.y, b.y, t), z: lerp(a.z, b.z, t) }
}

/** 각도 차이를 −π..π 로 정규화한다. 회전 보간이 먼 길로 도는 것을 막는다. */
export function angleDelta(from: number, to: number): number {
  let d = (to - from) % (Math.PI * 2)
  if (d > Math.PI) d -= Math.PI * 2
  if (d < -Math.PI) d += Math.PI * 2
  return d
}

/** 원본의 회전 보간: `diff × min(1, dt×14)` */
export function approachAngle(from: number, to: number, dt: number, rate = 14): number {
  return from + angleDelta(from, to) * Math.min(1, dt * rate)
}
