/**
 * 보스 모델 4종 — 고대 드래곤 · 심연의 리바이어던 · 용암의 군주 · 빙하의 군주.
 *
 * 원본 SSOT: `reference/blocky-rpg.html`
 *   - `buildDragon`     2644–2701
 *   - `buildLeviathan`  2752–2804
 *   - `buildMagmaLord`  2807–2866
 *   - `buildFrostLord`  2869–2929
 *
 * `creatures.ts` 에서 분리한 이유는 **800줄 상한**이다. 등록·후처리·포즈는 전부
 * `creatures.ts` 가 맡고 여기는 조립만 한다. 공용 캐시는 `creature-kit.ts` 에 있다.
 *
 * ## 원본과 달라진 단 하나의 규칙
 * 모든 빌더가 **배율 1** 로 조립한다. 원본은 `t.make(t.scale)` 로 치수에 배율을 구워 넣었고,
 * 그래서 몹 종류마다 지오메트리가 새로 생겼다 (결함 D-8).
 * 배율은 `buildCreature()` 가 `Object3D.scale` 로 준다 — 결과 좌표는 원본과 동일하다.
 * 원본이 `*s` 를 빠뜨린 자리(빙하 군주 왕관)만 예외이며 아래에 따로 표시했다.
 */

import * as THREE from 'three'
import { MOBTYPES } from '@bq/shared'
import {
  SIDES,
  blobMesh,
  castMesh,
  cone,
  coneGeo,
  cylGeo,
  emptyPivot,
  glowMat,
  mesh,
  modelRng,
  octaGeo,
  pivot,
  put,
  rbox,
  rboxCast,
  rboxSolid,
  shapeGeo,
  sphere,
  stdMat,
  tmat,
} from './creature-kit'
import type { CreatureRig } from './creature-kit'

/* ══════════════════════════════════════════════════════════════════
   🐉 고대 드래곤 — 원본 2644–2701
   ══════════════════════════════════════════════════════════════════ */

export function buildDragon(): THREE.Group {
  const g = new THREE.Group()
  const C = 0x5a2a6a
  const C2 = 0x341840
  const SCL = tmat(C, 'scale', 0.68, 0.12)
  const SCL2 = tmat(C2, 'scale', 0.68, 0.12)
  const BELM = tmat(0xb08a4a, 'scale', 0.8)
  const HRNM = tmat(0xd8c9a8, 'bone', 0.6, 0.1)

  const body = blobMesh(1.7, SCL, 0.1, 2.2, 24)
  body.scale.set(1, 0.92, 1.6)
  body.position.y = 3.3
  g.add(body)

  const bel = blobMesh(1.25, BELM, 0.07, 3, 16)
  bel.scale.set(0.82, 0.55, 1.45)
  put(g, bel, 0, 2.65, 0.1)

  // 목 — 뒤로 갈수록 가늘어지는 덩어리 4개
  for (let i = 0; i < 4; i++) {
    put(g, blobMesh(0.8 - i * 0.11, SCL, 0.05, 6, 12), 0, 3.8 + i * 0.5, 1.7 + i * 0.8)
  }

  const head = blobMesh(0.9, SCL2, 0.06, 5, 18)
  head.scale.set(1, 0.85, 1.35)
  put(g, head, 0, 5.7, 5.0)
  put(g, rbox(0.95, 0.3, 1.5, 0.12, SCL2), 0, 5.2, 5.35)
  for (let i = 0; i < 5; i++) {
    put(g, cone(0.09, 0.32, 4, 0xffffff), (i - 2) * 0.19, 5.3, 5.85).rotation.x = Math.PI
  }

  for (const sd of SIDES) {
    const h = castMesh(coneGeo(0.18, 1.3, 6), HRNM)
    h.rotation.x = -0.7
    put(g, h, sd * 0.48, 6.5, 4.6)
    put(g, sphere(0.18, glowMat(0xffd24a, 3.0), 12, 9), sd * 0.54, 5.9, 5.6)
    const j = mesh(coneGeo(0.1, 0.5, 5), HRNM)
    j.rotation.x = Math.PI * 0.6
    put(g, j, sd * 0.6, 5.2, 4.9)
  }

  /* 날개 — 막은 양면 반투명, 뼈대는 뿔과 같은 재질 */
  const wingL = new THREE.Group()
  const wingR = new THREE.Group()
  const memb = stdMat({
    color: C2,
    roughness: 0.6,
    metalness: 0.05,
    opacity: 0.95,
    doubleSide: true,
  })
  const wings: ReadonlyArray<readonly [THREE.Group, number]> = [
    [wingL, -1],
    [wingR, 1],
  ]
  for (const [w, sd] of wings) {
    put(g, w, sd * 1.3, 4.4, 0)
    const m1 = castMesh(
      shapeGeo(
        'dragonWing',
        () => {
          const sh = new THREE.Shape()
          sh.moveTo(0, 0)
          sh.bezierCurveTo(2.0, 1.6, 4.6, 1.1, 5.6, -0.4)
          sh.bezierCurveTo(4.4, -1.0, 3.6, -2.2, 2.6, -1.4)
          sh.bezierCurveTo(1.8, -2.4, 1.0, -1.4, 0, 0)
          return sh
        },
        14,
      ),
      memb,
    )
    m1.rotation.set(-Math.PI / 2, 0, sd < 0 ? Math.PI : 0)
    w.add(m1)
    for (let i = 0; i < 3; i++) {
      const rib = rbox(4.6, 0.11, 0.13, 0.05, HRNM)
      rib.position.set(sd * 2.3, 0.05, -1.2 + i * 1.0)
      rib.rotation.y = sd * (0.12 - i * 0.18)
      w.add(rib)
    }
  }

  // 꼬리 — 덩어리 + 등가시
  for (let i = 0; i < 7; i++) {
    put(g, blobMesh(0.75 - i * 0.09, SCL, 0.04, 7, 10), 0, 3.0 - i * 0.14, -2.3 - i * 0.9)
    put(g, mesh(coneGeo(0.15, 0.45, 5), HRNM), 0, 3.7 - i * 0.16, -2.3 - i * 0.9)
  }
  // 등줄기 가시 5개
  for (let i = 0; i < 5; i++) {
    put(g, castMesh(coneGeo(0.22, 0.8, 5), HRNM), 0, 4.85 - Math.abs(i - 2) * 0.12, 1.4 - i * 0.75)
  }

  // 네 다리 — 허벅지만 그림자를 드리우고 발은 드리우지 않는다 (원본 2694–2697)
  const leg = (x: number, z: number): THREE.Group => {
    const q = pivot(g, x, 2.7)
    q.position.z = z
    const l = rboxCast(0.66, 2.0, 0.76, 0.26, SCL2)
    l.position.y = -1.0
    q.add(l)
    const f = rbox(0.9, 0.32, 1.1, 0.14, HRNM)
    f.position.set(0, -2.05, 0.24)
    q.add(f)
    return q
  }
  const fl = leg(-1.05, 1.2)
  const fr = leg(1.05, 1.2)
  const bl = leg(-1.15, -1.4)
  const br = leg(1.15, -1.4)

  // ⚠️ 원본 2699 는 `head` 를 userData 에 넣지 않았다. 그래서 animMob 의
  //    `if(u.head)` 분기가 항상 거짓이고 드래곤 머리는 공격 예고에 반응하지 않는다.
  //    시각 결함이지만 원본 동작이므로 그대로 둔다 (수정하려면 요건 승인이 필요하다).
  const rig: CreatureRig = {
    kind: 'dragon',
    armL: fl,
    armR: fr,
    legL: bl,
    legR: br,
    fl,
    fr,
    bl,
    br,
    wingL,
    wingR,
    baseScale: 1,
    bob: 0,
  }
  g.userData = rig
  return g
}

/* ══════════════════════════════════════════════════════════════════
   🌊 심연의 리바이어던 — 물결치는 바다뱀. 원본 2752–2804
   ══════════════════════════════════════════════════════════════════ */

/**
 * 머리의 기준 z.
 *
 * ⚠️ 원본 2782 는 머리를 `z = 3.6*s` 에 놓지만, `animMob` 의 serpent 분기(3134)가
 *    `u.head.position.z = (u.headZ||0) - tk*3.0 + pk*6.5` 로 **매 프레임 덮어쓴다.**
 *    `u.headZ` 는 원본 어디에서도 대입되지 않으므로 첫 프레임에 머리가 z=0 —
 *    즉 1번 몸통 마디 속으로 빨려 들어간다. 명백한 누락이라 여기서는 조립값을 리그에 실어
 *    머리가 앞에 붙어 있게 한다. 원본과 다른 유일한 **동작** 차이이며 승인 대상이다.
 */
const LEVIATHAN_HEAD_Z = 3.6

export function buildLeviathan(): THREE.Group {
  const g = new THREE.Group()
  const SK = tmat(0x1d5c6e, 'scale', 0.42, 0.35)
  const SK2 = tmat(0x0f3a48, 'scale', 0.42, 0.35)
  const BEL = tmat(0xa8c4b0, 'scale', 0.55, 0.2)
  const FIN = stdMat({
    color: 0x35a0b8,
    roughness: 0.3,
    metalness: 0.2,
    opacity: 0.9,
    doubleSide: true,
  })

  const segs: THREE.Group[] = []
  for (let i = 0; i < 14; i++) {
    const t = i / 13
    // 목덜미(t=0.25)가 가장 굵고 앞뒤로 가늘어진다.
    const r = 2.0 - Math.abs(t - 0.25) * 1.5
    const seg = new THREE.Group()
    seg.position.set(0, 0, -i * 2.5)

    // 원본의 `Math.max(0.5, r)` / `Math.max(0.3, r*0.6)` 하한은 이 곡선에서 한 번도 걸리지 않는다
    // (최소 r = 0.875). 배율을 빼도 걸리지 않으므로 원문 그대로 옮겨 둔다.
    const bd = blobMesh(Math.max(0.5, r), i < 3 ? SK2 : SK, 0.08, 3, 16)
    bd.scale.set(1, 0.88, 1.15)
    seg.add(bd)
    const be = blobMesh(Math.max(0.3, r * 0.6), BEL, 0.05, 4, 12)
    be.scale.set(0.9, 0.4, 1.1)
    be.position.y = -r * 0.55
    seg.add(be)

    if (i % 2 === 0 && i < 12) {
      const f = mesh(coneGeo(r * 0.5, r * 1.5, 3), FIN)
      f.position.y = r * 0.9
      seg.add(f)
    }
    if (i === 5 || i === 8) {
      for (const sd of SIDES) {
        const pf = mesh(coneGeo(r * 0.5, r * 2.0, 3), FIN)
        pf.position.set(sd * r * 0.9, -r * 0.2, 0)
        pf.rotation.z = sd * 1.25
        pf.scale.set(1, 1, 0.4)
        seg.add(pf)
      }
    }
    g.add(seg)
    segs.push(seg)
  }

  /* 머리 */
  const head = new THREE.Group()
  head.position.set(0, 0, LEVIATHAN_HEAD_Z)
  g.add(head)
  const sk = blobMesh(2.0, SK2, 0.1, 3.5, 20)
  sk.scale.set(0.95, 0.85, 1.5)
  head.add(sk)
  const jaw = rboxCast(2.2, 0.7, 3.4, 0.3, SK2)
  jaw.position.set(0, -1.15, 0.9)
  head.add(jaw)

  const TOOTH = tmat(0xf0f4f0, null, 0.35)
  for (let i = 0; i < 8; i++) {
    const th = mesh(coneGeo(0.16, 0.6, 4), TOOTH)
    th.position.set(((i % 4) - 1.5) * 0.55, -0.72, i < 4 ? 2.2 : 1.3)
    th.rotation.x = Math.PI
    head.add(th)
  }
  for (const sd of SIDES) {
    put(head, sphere(0.34, glowMat(0x8ffff0, 3.2), 14, 10), sd * 1.0, 0.55, 1.7)
    const h = mesh(coneGeo(0.3, 2.2, 5), FIN)
    h.rotation.set(-0.5, 0, sd * 0.5)
    put(head, h, sd * 1.0, 1.5, -0.3)
  }
  put(head, mesh(coneGeo(1.0, 3.0, 3), FIN), 0, 1.9, -0.6)

  const rig: CreatureRig = {
    kind: 'serpent',
    armL: emptyPivot(),
    armR: emptyPivot(),
    legL: emptyPivot(),
    legR: emptyPivot(),
    segs,
    head,
    headZ: LEVIATHAN_HEAD_Z,
    baseScale: 1,
    bob: 0,
  }
  g.userData = rig
  g.add(rig.armR)
  return g
}

/* ══════════════════════════════════════════════════════════════════
   🌋 용암의 군주 — 갈라진 흑요석 껍질 속의 마그마. 원본 2807–2866
   ══════════════════════════════════════════════════════════════════ */

export function buildMagmaLord(): THREE.Group {
  const g = new THREE.Group()
  const rnd = modelRng('magmaLord')
  const OBS = tmat(0x1b1210, 'rock', 0.92, 0.08)
  const OBS2 = tmat(0x2c1d18, 'rock', 0.94)
  const MAG = glowMat(0xff6a1a, 2.6)
  const MAG2 = glowMat(0xffc23a, 3.0)

  const torso = blobMesh(2.4, OBS, 0.16, 2.6, 22)
  torso.scale.set(1.15, 1.0, 0.9)
  torso.position.y = 6.4
  g.add(torso)
  put(g, rboxSolid(3.0, 1.2, 2.2, 0.4, OBS2), 0, 4.6, 0)

  /* 균열 속 마그마 12줄 */
  for (let i = 0; i < 12; i++) {
    const a = rnd() * 6.283
    const yy = 5.2 + rnd() * 2.6
    const c = rboxSolid(0.2, 0.9 + rnd() * 0.9, 0.2, 0.06, MAG)
    c.rotation.z = (rnd() - 0.5) * 1.4
    put(g, c, Math.cos(a) * 2.2, yy, Math.sin(a) * 1.7)
  }
  const core = sphere(0.85, MAG2, 18, 14)
  put(g, core, 0, 6.6, 1.9)

  /* 머리 */
  const head = blobMesh(1.15, OBS2, 0.1, 4, 18)
  head.position.y = 8.8
  g.add(head)
  for (const sd of SIDES) {
    put(g, sphere(0.24, MAG2, 12, 9), sd * 0.42, 8.9, 1.0)
    const hn = mesh(coneGeo(0.34, 2.4, 6), OBS2)
    hn.rotation.set(-0.4, 0, sd * 0.7)
    put(g, hn, sd * 0.85, 9.9, -0.2)
  }
  put(g, rboxSolid(1.3, 0.4, 1.0, 0.14, MAG), 0, 8.2, 0.85)

  /* 등의 분화구 6기 */
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * 3.14 - 1.57
    const x = Math.sin(a) * 1.7
    put(g, mesh(cylGeo(0.4, 0.62, 1.3, 7), OBS2), x, 8.0 - Math.abs(a) * 0.6, -1.9)
    put(g, mesh(cylGeo(0.34, 0.34, 0.14, 7), MAG2), x, 8.66 - Math.abs(a) * 0.6, -1.9)
  }

  /* 팔 — 거대한 주먹 */
  const armL = pivot(g, -2.9, 7.6)
  const armR = pivot(g, 2.9, 7.6)
  const elbows: THREE.Group[] = []
  for (const arm of [armL, armR]) {
    const up = rboxSolid(1.5, 2.6, 1.5, 0.5, OBS)
    up.position.y = -1.3
    arm.add(up)
    const el = new THREE.Group()
    el.position.y = -2.6
    arm.add(el)
    const fo = rboxSolid(1.35, 2.5, 1.35, 0.45, OBS2)
    fo.position.y = -1.25
    el.add(fo)
    const fist = blobMesh(1.15, OBS, 0.1, 4, 14)
    fist.position.y = -2.9
    el.add(fist)
    const kn = rboxSolid(1.4, 0.4, 1.2, 0.14, MAG)
    kn.position.set(0, -2.9, 0.9)
    el.add(kn)
    elbows.push(el)
  }

  /* 다리 */
  const legL = pivot(g, -1.35, 4.3)
  const legR = pivot(g, 1.35, 4.3)
  const knees: THREE.Group[] = []
  for (const leg of [legL, legR]) {
    const th = rboxSolid(1.5, 2.4, 1.6, 0.5, OBS)
    th.position.y = -1.2
    leg.add(th)
    const knee = new THREE.Group()
    knee.position.y = -2.4
    leg.add(knee)
    const sh = rboxSolid(1.35, 2.1, 1.5, 0.45, OBS2)
    sh.position.y = -1.05
    knee.add(sh)
    const ft = rboxSolid(1.7, 0.7, 2.4, 0.24, OBS)
    ft.position.set(0, -2.2, 0.4)
    knee.add(ft)
    knees.push(knee)
  }

  const rig: CreatureRig = {
    kind: 'titan',
    armL,
    armR,
    legL,
    legR,
    core,
    head,
    baseScale: 1,
    bob: 0,
    ...pivotParts(elbows, knees),
  }
  g.userData = rig
  return g
}

/* ══════════════════════════════════════════════════════════════════
   ❄️ 빙하의 군주 — 반투명 얼음 거인. 원본 2869–2929
   ══════════════════════════════════════════════════════════════════ */

/**
 * ⚠️ 원본 2897 의 왕관 뿔만 높이에 `*s` 가 빠져 있다 —
 *    `new THREE.ConeGeometry(0.22*s, 1.5 + (i%2)*0.8, 5)`.
 *    즉 왕관 높이는 배율과 무관한 **절대값**이었다. 단위 모델 + `Object3D.scale` 방식에서
 *    같은 결과를 내려면 고정 배율(빙하의 군주는 1.4)로 미리 나눠 둬야 한다.
 *    이 모델은 `frost` 전용이라 배율이 하나뿐이므로 이 보정이 성립한다.
 *    다른 몹이 이 모델을 쓰게 되면 왕관 비율이 원본과 달라진다 — 그때 다시 판단해야 한다.
 */
const FROST_SCALE = MOBTYPES.frost.scale

export function buildFrostLord(): THREE.Group {
  const g = new THREE.Group()
  const rnd = modelRng('frostLord')
  const ICE = stdMat({
    color: 0x9fd4ec,
    roughness: 0.1,
    metalness: 0.08,
    opacity: 0.8,
    envMapIntensity: 2.4,
  })
  const ICE2 = stdMat({
    color: 0x6fa8c8,
    roughness: 0.16,
    metalness: 0.06,
    opacity: 0.88,
    envMapIntensity: 2.0,
  })
  const RIME = tmat(0xeaf6fc, 'bone', 0.5)

  const torso = blobMesh(2.3, ICE, 0.14, 2.8, 22)
  torso.scale.set(1.1, 1.05, 0.85)
  torso.position.y = 6.6
  g.add(torso)
  put(g, rboxSolid(3.1, 1.1, 2.1, 0.38, ICE2), 0, 4.8, 0)

  const heart = mesh(octaGeo(0.8), glowMat(0x9fe8ff, 2.8))
  put(g, heart, 0, 6.8, 1.7)

  /* 어깨·등의 결정 9개 */
  for (let i = 0; i < 9; i++) {
    const a = rnd() * 6.283
    const h = 1.6 + rnd() * 3.4
    const c = mesh(coneGeo(0.4, h, 5), ICE)
    c.rotation.set((rnd() - 0.5) * 0.7, rnd() * 3, (rnd() - 0.5) * 0.7)
    put(g, c, Math.cos(a) * 2.0, 7.4 + rnd() * 1.6, Math.sin(a) * 1.5 - 0.6)
  }

  /* 머리 + 얼음 왕관 */
  const head = blobMesh(1.1, ICE2, 0.09, 4, 18)
  head.position.y = 9.0
  g.add(head)
  for (let i = 0; i < 7; i++) {
    const a = (i / 7) * 6.283
    const c = mesh(coneGeo(0.22, (1.5 + (i % 2) * 0.8) / FROST_SCALE, 5), ICE)
    put(g, c, Math.cos(a) * 0.85, 10.1, Math.sin(a) * 0.85)
  }
  for (const sd of SIDES) {
    put(g, sphere(0.22, glowMat(0xdff6ff, 3.4), 12, 9), sd * 0.4, 9.1, 0.95)
  }
  put(g, rboxSolid(1.2, 0.35, 0.9, 0.12, RIME), 0, 8.45, 0.8)

  /* 팔 */
  const armL = pivot(g, -2.95, 7.8)
  const armR = pivot(g, 2.95, 7.8)
  const elbows: THREE.Group[] = []
  const arms: ReadonlyArray<readonly [THREE.Group, number]> = [
    [armL, -1],
    [armR, 1],
  ]
  for (const [arm, sd] of arms) {
    const up = rboxSolid(1.4, 2.6, 1.4, 0.48, ICE)
    up.position.y = -1.3
    arm.add(up)
    const el = new THREE.Group()
    el.position.y = -2.6
    arm.add(el)
    const fo = rboxSolid(1.25, 2.4, 1.25, 0.44, ICE2)
    fo.position.y = -1.2
    el.add(fo)
    const fist = blobMesh(1.05, ICE, 0.09, 4, 14)
    fist.position.y = -2.8
    el.add(fist)
    for (let i = 0; i < 3; i++) {
      const sp = mesh(coneGeo(0.2, 1.1, 5), ICE)
      sp.position.set(sd * 0.7, -1.2 - i * 0.7, -0.7)
      sp.rotation.z = sd * 1.1
      el.add(sp)
    }
    elbows.push(el)
  }

  /* 다리 */
  const legL = pivot(g, -1.35, 4.5)
  const legR = pivot(g, 1.35, 4.5)
  const knees: THREE.Group[] = []
  for (const leg of [legL, legR]) {
    const th = rboxSolid(1.45, 2.5, 1.5, 0.48, ICE)
    th.position.y = -1.25
    leg.add(th)
    const knee = new THREE.Group()
    knee.position.y = -2.5
    leg.add(knee)
    const sh = rboxSolid(1.3, 2.2, 1.4, 0.44, ICE2)
    sh.position.y = -1.1
    knee.add(sh)
    const ft = rboxSolid(1.6, 0.7, 2.3, 0.22, RIME)
    ft.position.set(0, -2.3, 0.4)
    knee.add(ft)
    knees.push(knee)
  }

  const rig: CreatureRig = {
    kind: 'titan',
    armL,
    armR,
    legL,
    legR,
    core: heart,
    head,
    baseScale: 1,
    bob: 0,
    ...pivotParts(elbows, knees),
  }
  g.userData = rig
  return g
}

/* ══════════════════════════════════════════════════════════════════
   보조
   ══════════════════════════════════════════════════════════════════ */

/**
 * 타이탄 팔꿈치·무릎 피벗을 리그 필드로 바꾼다.
 *
 * 원본은 `legL.userData.k` / `armL.userData.el` 처럼 자식 객체의 `userData` 에 숨겨 두었다.
 * `Object3D.userData` 는 `clone()` 때 JSON 직렬화를 거쳐 객체 참조가 깨지므로,
 * 재구현에서는 리그 최상단에 올려 타입으로 드러낸다 (동작은 동일하다).
 *
 * `exactOptionalPropertyTypes` 아래에서는 `undefined` 를 대입할 수 없으므로
 * 있는 키만 담은 객체를 만들어 펼친다.
 */
type TitanPivots = Partial<Pick<CreatureRig, 'elbowL' | 'elbowR' | 'kneeL' | 'kneeR'>>

function pivotParts(
  elbows: readonly THREE.Object3D[],
  knees: readonly THREE.Object3D[],
): TitanPivots {
  const out: TitanPivots = {}
  const [eL, eR] = elbows
  const [kL, kR] = knees
  if (eL) out.elbowL = eL
  if (eR) out.elbowR = eR
  if (kL) out.kneeL = kL
  if (kR) out.kneeR = kR
  return out
}
