/**
 * 원격 엔티티 보간.
 *
 * 서버는 20 Hz 로 스냅샷을 보내고 화면은 60 fps 로 그린다. 그대로 그리면 뚝뚝 끊긴다.
 * **서버 시각보다 100 ms(2틱) 뒤**를 렌더해서 항상 스냅샷 두 개 사이를 보간한다.
 * 지연을 감수하는 대신 끊김과 외삽 오차가 사라진다 — 협동 게임에서는 이쪽이 맞다.
 */

const INTERP_DELAY_MS = 100
const MAX_BUFFER = 12

export interface Transform {
  x: number
  y: number
  z: number
  yaw: number
}

interface Sample<T> {
  readonly t: number
  readonly value: T
}

export class Interpolator<T extends Transform> {
  private buf: Sample<T>[] = []

  push(value: T, serverTimeMs: number): void {
    this.buf.push({ t: serverTimeMs, value })
    if (this.buf.length > MAX_BUFFER) this.buf.shift()
  }

  /** 렌더 시각(now)에 해당하는 보간값. 표본이 부족하면 최신값을 그대로 준다. */
  sample(nowMs: number): T | null {
    const target = nowMs - INTERP_DELAY_MS
    const buf = this.buf
    if (buf.length === 0) return null
    const last = buf[buf.length - 1]
    if (!last) return null
    if (buf.length === 1 || target >= last.t) return last.value

    for (let i = buf.length - 1; i > 0; i--) {
      const b = buf[i]
      const a = buf[i - 1]
      if (!a || !b) continue
      if (a.t <= target && target <= b.t) {
        const span = b.t - a.t
        const t = span <= 0 ? 1 : (target - a.t) / span
        return blend(a.value, b.value, t)
      }
    }
    return buf[0]?.value ?? null
  }

  clear(): void {
    this.buf.length = 0
  }
}

function blend<T extends Transform>(a: T, b: T, t: number): T {
  return {
    ...b,
    x: a.x + (b.x - a.x) * t,
    y: a.y + (b.y - a.y) * t,
    z: a.z + (b.z - a.z) * t,
    yaw: a.yaw + shortestAngle(a.yaw, b.yaw) * t,
  }
}

/** 각도는 −π..π 로 정규화해서 보간한다. 안 하면 캐릭터가 먼 길로 한 바퀴 돈다. */
function shortestAngle(from: number, to: number): number {
  let d = (to - from) % (Math.PI * 2)
  if (d > Math.PI) d -= Math.PI * 2
  if (d < -Math.PI) d += Math.PI * 2
  return d
}

/** 여러 엔티티의 보간기를 id 로 관리한다. 사라진 엔티티는 정리한다. */
export class InterpSet<T extends Transform> {
  private map = new Map<number, Interpolator<T>>()

  push(id: number, value: T, serverTimeMs: number): void {
    let it = this.map.get(id)
    if (!it) {
      it = new Interpolator<T>()
      this.map.set(id, it)
    }
    it.push(value, serverTimeMs)
  }

  sample(id: number, nowMs: number): T | null {
    return this.map.get(id)?.sample(nowMs) ?? null
  }

  /** 스냅샷에 없는 id 를 버린다. 안 하면 나간 플레이어의 보간기가 남는다. */
  retain(ids: ReadonlySet<number>): void {
    for (const id of this.map.keys()) {
      if (!ids.has(id)) this.map.delete(id)
    }
  }

  has(id: number): boolean {
    return this.map.has(id)
  }

  clear(): void {
    this.map.clear()
  }
}
