/**
 * 게임패드 어댑터 (FR-8.7 / docs/04 §3.3).
 *
 * 폴링 방식이다 — 브라우저가 게임패드 이벤트를 주지 않으므로 매 프레임 `poll()` 을 부른다.
 * 연결이 감지되면 화면 하단 터치 버튼을 숨기는 것은 UI 쪽 책임이다.
 */

import type { InputHub } from './state'

const BTN = {
  A: 0, // 점프
  B: 1, // 특수기
  X: 2, // 공격
  Y: 3, // 스킬 트리
  LB: 4, // 달리기
  LT: 6, // 카메라 당기기
  RT: 7, // 카메라 밀기
  START: 9, // 메뉴
  L3: 10, // 달리기 (스틱 누름)
} as const

export class GamepadAdapter {
  private prev = new Map<number, boolean>()
  connected = false

  constructor(
    private readonly hub: InputHub,
    private readonly deadzone = 0.18,
  ) {}

  attach(): () => void {
    const onConnect = (): void => {
      this.connected = true
      this.hub.markDevice('gamepad')
    }
    const onDisconnect = (): void => {
      this.connected = navigator.getGamepads().some((g) => g !== null)
    }
    window.addEventListener('gamepadconnected', onConnect)
    window.addEventListener('gamepaddisconnected', onDisconnect)
    return () => {
      window.removeEventListener('gamepadconnected', onConnect)
      window.removeEventListener('gamepaddisconnected', onDisconnect)
    }
  }

  poll(): void {
    const pads = navigator.getGamepads?.() ?? []
    const pad = pads.find((p) => p !== null)
    if (!pad) {
      this.hub.raw.padMove.x = 0
      this.hub.raw.padMove.z = 0
      return
    }

    const lx = dz(pad.axes[0] ?? 0, this.deadzone)
    const ly = dz(pad.axes[1] ?? 0, this.deadzone)
    const rx = dz(pad.axes[2] ?? 0, this.deadzone)
    const ry = dz(pad.axes[3] ?? 0, this.deadzone)

    if (lx !== 0 || ly !== 0 || rx !== 0 || ry !== 0) this.hub.markDevice('gamepad')

    this.hub.raw.padMove.x = lx
    this.hub.raw.padMove.z = ly

    // 오른쪽 스틱은 픽셀 델타처럼 취급한다 (마우스와 같은 경로를 타게 하기 위해)
    this.hub.raw.look.dx += rx * 14
    this.hub.raw.look.dy += ry * 14

    this.hub.raw.attackHeld = pressed(pad, BTN.X)
    this.hub.raw.runHeld = pressed(pad, BTN.LB) || pressed(pad, BTN.L3)

    if (this.edge(pad, BTN.A)) this.hub.raw.jumpEdge = true
    if (this.edge(pad, BTN.B)) this.hub.raw.specialEdge = true
    if (this.edge(pad, BTN.Y)) this.hub.pushUi('tree')
    if (this.edge(pad, BTN.START)) this.hub.pushUi('menu')

    const lt = pad.buttons[BTN.LT]?.value ?? 0
    const rt = pad.buttons[BTN.RT]?.value ?? 0
    if (lt > 0.3) this.hub.raw.zoom -= lt * 0.4
    if (rt > 0.3) this.hub.raw.zoom += rt * 0.4
  }

  private edge(pad: Gamepad, idx: number): boolean {
    const now = pressed(pad, idx)
    const was = this.prev.get(idx) ?? false
    this.prev.set(idx, now)
    return now && !was
  }
}

function pressed(pad: Gamepad, idx: number): boolean {
  return pad.buttons[idx]?.pressed ?? false
}

function dz(v: number, d: number): number {
  return Math.abs(v) < d ? 0 : v
}
