/**
 * 마을 건물 — 원본 `reference/blocky-rpg.html` 1637–1651(민가) · 1817–1853(무기점).
 *
 * 광장 원반과 도로는 지형(`world`) 담당이라 여기 없다.
 * 상점 상호작용 판정 기준점은 건물 중심이 아니라 **정문 앞**(`SHOP.z + SHOP_INTERACT_Z_OFFSET`)이다 —
 * 그 판정은 UI 계층이 `SHOP_INTERACT_R` 로 한다.
 */

import * as THREE from 'three'
import { SHOP, SHOP_COLLIDER_R, SHOP_KEEPER_POS, HOUSES, HOUSE_COLLIDER_R } from '@bq/shared'
import { LM, add, box, cone } from './kit'
import type { Collider } from './kit'

/** 민가 3채의 벽/지붕 색. `HOUSES` 와 **같은 순서**다 (원본 1649–1651). */
const HOUSE_COLORS = [
  { wall: 0xd9c9a8, roof: 0xc0552f },
  { wall: 0xcbd9e0, roof: 0x3f6ea8 },
  { wall: 0xe0d3b8, roof: 0x7a4aa0 },
] as const

export interface VillageMeshes {
  group: THREE.Group
  colliders: Collider[]
  /**
   * 상인 NPC 가 설 자리. 캐릭터 리그(`makeChar`)는 다른 모듈이 만들므로
   * 여기서는 위치·방향만 잡은 빈 노드를 준다. 만든 캐릭터를 여기에 `add` 하면 된다.
   */
  keeperAnchor: THREE.Object3D
}

/** 민가 한 채. 원본 `house(x,z,rot,c1,c2)`. */
function buildHouse(x: number, z: number, rot: number, wall: number, roof: number): THREE.Group {
  const g = new THREE.Group()
  const body = box(7, 4.5, 6, wall)
  body.position.y = 2.25
  const rf = new THREE.Mesh(cone(6, 3, 4), LM(roof))
  rf.position.y = 6
  rf.rotation.y = Math.PI / 4
  const door = box(1.6, 2.6, 0.3, 0x5b3d22)
  door.position.set(0, 1.3, 3.05)
  for (const m of [body, rf, door]) add(g, m, true, true)
  g.position.set(x, 0, z)
  g.rotation.y = rot
  return g
}

/** 무기점 건물 — 차양 · 간판(칼/도끼 픽토그램) · 진열대. 원본 1819–1845. */
function buildShop(): THREE.Group {
  const g = new THREE.Group()
  const wall = box(9, 5, 7, 0xd8c9a8)
  wall.position.y = 2.5
  const roof = new THREE.Mesh(cone(7.4, 3.2, 4), LM(0x7a3f2a))
  roof.position.y = 6.6
  roof.rotation.y = Math.PI / 4
  const door = box(2.2, 3.2, 0.3, 0x5b3d22)
  door.position.set(0, 1.6, 3.55)
  for (const m of [wall, roof, door]) add(g, m, true, true)

  /* 차양 — 줄무늬. `i % 2` 는 음수 i 에서 -0/-1 이 되는데 그 진리값까지 원본과 같다 */
  for (let i = -4; i <= 4; i++) {
    const st = box(0.9, 0.25, 2.4, i % 2 ? 0xe8e2d6 : 0xc0442e)
    st.position.set(i * 0.95, 4.5, 4.4)
    st.rotation.x = -0.25
    add(g, st, true)
  }

  /* 간판 — 왼쪽에 칼, 오른쪽에 도끼 */
  const sign = box(5, 1.5, 0.3, 0x3a2a1c)
  sign.position.set(0, 5.5, 3.7)
  add(g, sign, true)
  const bladeL = box(0.25, 1.0, 0.12, 0xdfe6ee)
  bladeL.position.set(-1.2, 5.55, 3.9)
  g.add(bladeL)
  const hiltL = box(0.8, 0.16, 0.14, 0x8a6a35)
  hiltL.position.set(-1.2, 5.05, 3.9)
  g.add(hiltL)
  const axeHead = box(0.9, 0.3, 0.12, 0xdfe6ee)
  axeHead.position.set(1.2, 5.85, 3.9)
  g.add(axeHead)
  const axeHaft = box(0.16, 1.1, 0.12, 0x8a6a35)
  axeHaft.position.set(1.2, 5.4, 3.9)
  g.add(axeHaft)

  /* 진열대 */
  const rack = box(3.4, 0.3, 1.2, 0x6b4526)
  rack.position.set(-5.2, 1.6, 3.2)
  add(g, rack, true)
  for (const i of [-1, 0, 1] as const) {
    const blade = box(0.16, 2.0, 0.1, 0xc9d2dc)
    blade.position.set(-5.2 + i * 1.1, 2.6, 3.2)
    add(g, blade, true)
  }

  g.position.set(SHOP.x, 0, SHOP.z)
  return g
}

/** 무기점 1채 + 민가 3채 + 상인 NPC 자리. */
export function buildVillage(): VillageMeshes {
  const group = new THREE.Group()
  const colliders: Collider[] = []

  group.add(buildShop())
  colliders.push({ x: SHOP.x, z: SHOP.z, r: SHOP_COLLIDER_R })

  HOUSES.forEach((h, i) => {
    const c = HOUSE_COLORS[i]
    if (!c) return
    group.add(buildHouse(h.x, h.z, h.rot, c.wall, c.roof))
    colliders.push({ x: h.x, z: h.z, r: HOUSE_COLLIDER_R })
  })

  /* 상인 NPC 자리 — 가게를 등지고 남쪽(플레이어 쪽)을 본다 */
  const keeperAnchor = new THREE.Object3D()
  keeperAnchor.name = 'shopKeeperAnchor'
  keeperAnchor.position.set(SHOP_KEEPER_POS.x, 0, SHOP_KEEPER_POS.z)
  keeperAnchor.rotation.y = Math.PI
  group.add(keeperAnchor)

  return { group, colliders, keeperAnchor }
}
