/**
 * 오디오.
 *
 * 효과음은 원본과 같이 WebAudio 오실레이터로 즉석 합성한다 (에셋 0개).
 * BGM 은 인라인 base64 대신 `public/audio/*.mp3` 를 fetch 해서 디코드한다 (FR-9.6 / T-4).
 * 822 KB 를 초기 번들에서 들어낸 대신, 첫 보스 조우 직전에 미리 받아 둔다.
 */

export type BgmTrack = 'boss' | 'creator'

/**
 * 하위 경로에 배포될 수 있으므로 `BASE_URL` 을 붙인다.
 * 절대 경로(`/audio/...`)로 두면 `/minchan_rpg/` 아래에서 404 가 난다.
 */
const BASE = import.meta.env.BASE_URL

const BGM_URL: Readonly<Record<BgmTrack, string>> = {
  boss: `${BASE}audio/bgm-boss.mp3`,
  creator: `${BASE}audio/bgm-creator.mp3`,
}

export class Audio {
  private ctx: AudioContext | null = null
  private master: GainNode | null = null
  private bgmGain: GainNode | null = null
  private source: AudioBufferSourceNode | null = null
  private buffers = new Map<BgmTrack, AudioBuffer>()
  private loading = new Map<BgmTrack, Promise<AudioBuffer | null>>()
  private current: BgmTrack | null = null

  bgmEnabled = true
  /** 0 ~ 100 (원본 기본값 55) */
  volume = 55

  /**
   * 브라우저는 사용자 제스처 전에는 오디오를 시작하지 않는다.
   * 첫 입력에서 부른다.
   */
  unlock(): void {
    if (this.ctx) {
      void this.ctx.resume()
      return
    }
    const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
    if (!Ctor) return
    this.ctx = new Ctor()
    this.master = this.ctx.createGain()
    this.master.gain.value = 0.5
    this.master.connect(this.ctx.destination)
    this.bgmGain = this.ctx.createGain()
    this.bgmGain.gain.value = this.volume / 100
    this.bgmGain.connect(this.master)
  }

  setVolume(v: number): void {
    this.volume = Math.max(0, Math.min(100, v))
    if (this.bgmGain) this.bgmGain.gain.value = this.volume / 100
  }

  /** 원본 `blip()` — 짧은 오실레이터 한 방. 타격·획득·UI 전부 이걸로 낸다. */
  blip(freq: number, dur = 0.08, type: OscillatorType = 'square', vol = 0.25): void {
    const ctx = this.ctx
    const master = this.master
    if (!ctx || !master || ctx.state !== 'running') return
    const osc = ctx.createOscillator()
    const gain = ctx.createGain()
    osc.type = type
    osc.frequency.value = freq
    gain.gain.setValueAtTime(vol, ctx.currentTime)
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + dur)
    osc.connect(gain)
    gain.connect(master)
    osc.start()
    osc.stop(ctx.currentTime + dur)
  }

  /** 보스 BGM 을 쓰기 전에 미리 받아 둔다. 실패해도 게임은 계속된다. */
  async preload(track: BgmTrack): Promise<AudioBuffer | null> {
    const cached = this.buffers.get(track)
    if (cached) return cached
    const inFlight = this.loading.get(track)
    if (inFlight) return inFlight

    const p = (async (): Promise<AudioBuffer | null> => {
      try {
        const res = await fetch(BGM_URL[track])
        if (!res.ok) return null
        const bytes = await res.arrayBuffer()
        this.unlock()
        const ctx = this.ctx
        if (!ctx) return null
        const buf = await ctx.decodeAudioData(bytes)
        this.buffers.set(track, buf)
        return buf
      } catch {
        return null
      }
    })()

    this.loading.set(track, p)
    return p
  }

  /**
   * `<audio loop>` 는 루프 이음매에 공백이 생긴다. 원본과 같이
   * `AudioBufferSourceNode.loop` 를 쓴다.
   */
  async playBgm(track: BgmTrack): Promise<void> {
    if (!this.bgmEnabled) return
    if (this.current === track) return
    const buf = await this.preload(track)
    const ctx = this.ctx
    const gain = this.bgmGain
    if (!buf || !ctx || !gain) return
    this.stopBgm()
    const src = ctx.createBufferSource()
    src.buffer = buf
    src.loop = true
    src.connect(gain)
    src.start()
    this.source = src
    this.current = track
  }

  stopBgm(): void {
    if (this.source) {
      try {
        this.source.stop()
      } catch {
        /* 이미 정지된 노드 */
      }
      this.source.disconnect()
      this.source = null
    }
    this.current = null
  }

  get playing(): BgmTrack | null {
    return this.current
  }
}

/** 자주 쓰는 효과음 프리셋 — 원본의 blip 호출을 이름으로 정리했다. */
export const SFX = {
  hit: (a: Audio) => a.blip(220, 0.07, 'square', 0.22),
  crit: (a: Audio) => a.blip(520, 0.11, 'sawtooth', 0.28),
  hurt: (a: Audio) => a.blip(120, 0.14, 'sawtooth', 0.3),
  coin: (a: Audio) => a.blip(880, 0.06, 'triangle', 0.18),
  levelUp: (a: Audio) => {
    a.blip(523, 0.09, 'triangle', 0.24)
    setTimeout(() => a.blip(784, 0.14, 'triangle', 0.24), 90)
  },
  /** 허공을 가르는 소리. 맞았을 때가 아니라 **휘두를 때** 난다. */
  swing: (a: Audio) => a.blip(300, 0.06, 'triangle', 0.12),
  jump: (a: Audio) => a.blip(420, 0.05, 'sine', 0.15),
  special: (a: Audio) => a.blip(180, 0.22, 'sawtooth', 0.3),
  ui: (a: Audio) => a.blip(660, 0.04, 'sine', 0.14),
  gate: (a: Audio) => a.blip(90, 0.6, 'sawtooth', 0.32),
} as const
