/**
 * HUD — 항상 떠 있는 것들.
 *
 * DOM 을 매 프레임 건드리면 60fps 가 무너진다. **값이 바뀐 것만** 갱신한다.
 */

import type { SelfSnapshot } from '@bq/shared'
import { CLASSES } from '@bq/shared'
import type { ClassId } from '@bq/shared'

export interface HudModel {
  readonly level: number
  readonly hp: number
  readonly maxHp: number
  readonly xp: number
  readonly xpNeed: number
  readonly gold: number
  readonly classId: ClassId | null
  readonly sp: number
  readonly burnT: number
  readonly slowT: number
  readonly invulnT: number
  readonly buffT: number
}

/** 원본에는 없던 상태이상 표시 (FR-2.11). 무엇에 당하고 있는지 보여야 대처할 수 있다. */
const STATUS_ICONS: readonly { key: keyof HudModel; icon: string; label: string }[] = [
  { key: 'burnT', icon: '🔥', label: '화상' },
  { key: 'slowT', icon: '🕸', label: '둔화' },
  { key: 'invulnT', icon: '✨', label: '무적' },
  { key: 'buffT', icon: '💨', label: '가속' },
]

export class Hud {
  private readonly lv: HTMLElement
  private readonly cls: HTMLElement
  private readonly hpFill: HTMLElement
  private readonly hpText: HTMLElement
  private readonly xpFill: HTMLElement
  private readonly xpText: HTMLElement
  private readonly gold: HTMLElement
  private readonly spDot: HTMLElement
  private readonly status: HTMLElement
  private readonly objective: HTMLElement
  private readonly toasts: HTMLElement
  private readonly help: HTMLElement
  private readonly net: HTMLElement

  private prev: Partial<HudModel> = {}
  private prevStatus = ''

  constructor(root: ParentNode = document) {
    this.lv = must(root, '#lvBadge')
    this.cls = must(root, '#clsBadge')
    this.hpFill = must(root, '#hpFill')
    this.hpText = must(root, '#hpText')
    this.xpFill = must(root, '#xpFill')
    this.xpText = must(root, '#xpText')
    this.gold = must(root, '#goldBadge')
    this.spDot = must(root, '#spDot')
    this.status = must(root, '#statusIcons')
    this.objective = must(root, '#objective')
    this.toasts = must(root, '#toasts')
    this.help = must(root, '#help')
    this.net = must(root, '#netBadge')
  }

  update(m: HudModel): void {
    if (m.level !== this.prev.level) this.lv.textContent = `Lv ${m.level}`

    if (m.hp !== this.prev.hp || m.maxHp !== this.prev.maxHp) {
      const r = m.maxHp > 0 ? Math.max(0, Math.min(1, m.hp / m.maxHp)) : 0
      this.hpFill.style.transform = `scaleX(${r})`
      this.hpText.textContent = `${Math.max(0, Math.ceil(m.hp))} / ${Math.round(m.maxHp)}`
    }

    if (m.xp !== this.prev.xp || m.xpNeed !== this.prev.xpNeed) {
      const r = m.xpNeed > 0 ? Math.max(0, Math.min(1, m.xp / m.xpNeed)) : 0
      this.xpFill.style.transform = `scaleX(${r})`
      this.xpText.textContent = `${Math.floor(m.xp)} / ${m.xpNeed}`
    }

    if (m.gold !== this.prev.gold) {
      this.gold.textContent = `${m.gold.toLocaleString('ko-KR')} G`
    }

    if (m.classId !== this.prev.classId) {
      if (m.classId) {
        const c = CLASSES[m.classId]
        this.cls.textContent = `${c.icon} ${c.name}`
        this.cls.classList.remove('hidden')
      } else {
        this.cls.classList.add('hidden')
      }
    }

    if (m.sp !== this.prev.sp) {
      this.spDot.classList.toggle('hidden', m.sp <= 0)
    }

    const statusKey = STATUS_ICONS.map((s) => (Number(m[s.key]) > 0 ? '1' : '0')).join('')
    if (statusKey !== this.prevStatus) {
      this.prevStatus = statusKey
      this.status.replaceChildren(
        ...STATUS_ICONS.filter((s) => Number(m[s.key]) > 0).map((s) => {
          const el = document.createElement('span')
          el.textContent = s.icon
          el.title = s.label
          return el
        }),
      )
    }

    this.prev = m
  }

  /** 다음에 뭘 할지 (FR-7.10). 원본에는 목표 표시가 아예 없었다. */
  setObjective(text: string): void {
    if (this.objective.textContent !== text) this.objective.textContent = text
  }

  /**
   * 조작 안내 (D-5 수정 — 원본은 ≤520px 에서 통째로 숨겼다).
   * 줄 단위로 받아 DOM 으로 짓는다. 룸 코드처럼 서버에서 온 문자열이 섞이므로
   * `innerHTML` 을 쓰지 않는다.
   */
  setHelp(lines: readonly string[]): void {
    this.help.replaceChildren(
      ...lines.map((line) => {
        const el = document.createElement('div')
        el.textContent = line
        return el
      }),
    )
  }

  setNet(label: string, code?: string): void {
    this.net.replaceChildren()
    this.net.append(document.createTextNode(label))
    if (code) {
      const b = document.createElement('b')
      b.textContent = ` ${code}`
      this.net.appendChild(b)
    }
  }

  toast(text: string, ms = 2200): void {
    const el = document.createElement('div')
    el.className = 'toast'
    el.textContent = text
    this.toasts.appendChild(el)
    setTimeout(() => {
      el.style.opacity = '0'
      el.style.transition = 'opacity .3s'
      setTimeout(() => el.remove(), 320)
    }, ms)
  }
}

export function hudModelFrom(
  self: SelfSnapshot,
  me: { level: number; hp: number; maxHp: number; classId: string | null },
  buffT = 0,
): HudModel {
  return {
    level: me.level,
    hp: me.hp,
    maxHp: me.maxHp,
    xp: self.xp,
    xpNeed: self.xpNeed,
    gold: self.gold,
    classId: (me.classId as ClassId | null) ?? null,
    sp: self.sp,
    burnT: self.burnT,
    slowT: self.slowT,
    invulnT: self.invulnT,
    buffT,
  }
}

/**
 * 진행 상태로 "다음 목표" 문구를 만든다.
 *
 * 원본은 다음에 뭘 해야 하는지 알려 주지 않았다 — 아이가 맵을 헤매다 그만둔다.
 */
export function objectiveFor(g: {
  lords: number
  heavenOpen: boolean
  gabrielKilled: boolean
  creatorKilled: boolean
  level: number
  hasClass: boolean
}): string {
  if (g.creatorKilled) return '🏆 조물주를 쓰러뜨렸다'
  if (g.gabrielKilled) return '조물주에게 간다 — 봉인 너머 북쪽 끝'
  if (g.heavenOpen) return '천국으로 — 대천사 가브리엘을 찾아라'
  if (g.lords >= 3) return '문이 열린다…'
  if (!g.hasClass && g.level >= 5) return '직업을 고르자'
  if (g.level < 5) return `Lv 5 까지 사냥하기 (${g.level}/5)`
  return `세 군주를 무찌르고 문을 열자 (${g.lords}/3)`
}

function must(root: ParentNode, sel: string): HTMLElement {
  const el = root.querySelector<HTMLElement>(sel)
  if (!el) throw new Error(`HUD 요소를 찾을 수 없다: ${sel}`)
  return el
}
