/**
 * 전체화면 패널 스택.
 *
 * ## 이 파일이 고치는 결함
 * - **D-3**: 원본에 `ESC` 바인딩이 아예 없었다. 스킬트리·상점·저장·직업창을 키보드로 닫을 수 없었고,
 *   일시정지 수단도 없었다 (`P.paused` 는 패널이 열린 부수효과였을 뿐이다).
 * - **FR-8.6**: 안드로이드 뒤로가기로 최상단 패널만 닫힌다. `popstate` 로 처리한다.
 *
 * ## 규칙 (docs/04 §3.1)
 * 모든 UI 는 **두 경로로 닫힌다** — 화면의 닫기 버튼 + `ESC`(또는 뒤로가기).
 * 패널이 하나라도 열려 있으면 게임은 일시정지 상태다.
 */

export interface PanelSpec {
  readonly id: string
  readonly title: string
  /** 본문을 채운다. 반환한 정리 함수는 패널이 닫힐 때 불린다. */
  readonly render: (body: HTMLElement, close: () => void) => (() => void) | void
  /** 우하단 버튼들 */
  readonly footer?: (foot: HTMLElement, close: () => void) => void
  /** ESC 로 닫을 수 없는 패널 (예: Lv5 직업 선택 강제) */
  readonly modal?: boolean
}

interface OpenPanel {
  readonly spec: PanelSpec
  readonly el: HTMLElement
  readonly cleanup: (() => void) | void
}

export class PanelStack {
  private readonly stack: OpenPanel[] = []
  private historyDepth = 0

  /** 패널이 열리거나 닫힐 때마다 불린다. 게임 루프가 일시정지를 여기에 맞춘다. */
  onChange: ((open: boolean) => void) | null = null

  constructor(private readonly host: HTMLElement) {
    // 안드로이드 뒤로가기 / 브라우저 뒤로가기 → 최상단 패널만 닫는다.
    window.addEventListener('popstate', () => {
      if (this.historyDepth > 0) this.historyDepth--
      this.closeTop({ fromHistory: true })
    })
  }

  get open(): boolean {
    return this.stack.length > 0
  }

  get topId(): string | null {
    return this.stack[this.stack.length - 1]?.spec.id ?? null
  }

  has(id: string): boolean {
    return this.stack.some((p) => p.spec.id === id)
  }

  /** 이미 열려 있으면 닫는다 (토글). 아니면 연다. */
  toggle(spec: PanelSpec): void {
    if (this.topId === spec.id) this.closeTop()
    else this.push(spec)
  }

  push(spec: PanelSpec): void {
    if (this.has(spec.id)) return

    const el = document.createElement('div')
    el.className = 'panel'
    el.dataset['panel'] = spec.id
    el.setAttribute('role', 'dialog')
    el.setAttribute('aria-modal', 'true')
    el.setAttribute('aria-label', spec.title)

    const head = document.createElement('div')
    head.className = 'panel-head'
    const title = document.createElement('div')
    title.className = 'panel-title'
    title.textContent = spec.title
    head.appendChild(title)

    const close = (): void => this.close(spec.id)

    if (!spec.modal) {
      const x = document.createElement('button')
      x.className = 'icon-btn'
      x.textContent = '✕'
      x.setAttribute('aria-label', '닫기')
      x.addEventListener('click', close)
      head.appendChild(x)
    }

    const body = document.createElement('div')
    body.className = 'panel-body'
    const foot = document.createElement('div')
    foot.className = 'panel-foot'

    el.append(head, body, foot)
    this.host.appendChild(el)

    const cleanup = spec.render(body, close)
    spec.footer?.(foot, close)

    this.stack.push({ spec, el, cleanup })

    // 뒤로가기로 닫을 수 있도록 히스토리에 항목을 하나 쌓는다.
    history.pushState({ panel: spec.id }, '')
    this.historyDepth++

    this.onChange?.(true)
  }

  /** ESC / 뒤로가기가 부른다. modal 패널은 닫히지 않는다. */
  closeTop(opts: { fromHistory?: boolean } = {}): boolean {
    const top = this.stack[this.stack.length - 1]
    if (!top) return false
    if (top.spec.modal) return false
    this.remove(this.stack.length - 1, opts.fromHistory === true)
    return true
  }

  close(id: string): void {
    const idx = this.stack.findIndex((p) => p.spec.id === id)
    if (idx < 0) return
    this.remove(idx, false)
  }

  closeAll(): void {
    while (this.stack.length > 0) this.remove(this.stack.length - 1, false)
  }

  /** modal 패널을 강제로 닫는다 (직업을 실제로 골랐을 때 등). */
  resolveModal(id: string): void {
    const idx = this.stack.findIndex((p) => p.spec.id === id)
    if (idx < 0) return
    this.remove(idx, false)
  }

  private remove(idx: number, fromHistory: boolean): void {
    const panel = this.stack[idx]
    if (!panel) return
    this.stack.splice(idx, 1)
    panel.cleanup?.()
    panel.el.remove()

    // 히스토리에서 온 게 아니면 우리가 쌓은 항목을 되돌린다.
    if (!fromHistory && this.historyDepth > 0) {
      this.historyDepth--
      history.back()
    }

    this.onChange?.(this.stack.length > 0)
  }
}

/* ────────────────────────── 조립 헬퍼 ────────────────────────── */

export function button(
  label: string,
  onClick: () => void,
  variant: 'default' | 'primary' | 'danger' = 'default',
): HTMLButtonElement {
  const b = document.createElement('button')
  b.className = variant === 'default' ? 'btn' : `btn btn-${variant}`
  b.textContent = label
  b.addEventListener('click', onClick)
  return b
}

export interface CardOptions {
  readonly title: string
  readonly desc?: string
  readonly stats?: string
  readonly price?: string
  readonly selected?: boolean
  readonly disabled?: boolean
  readonly onClick?: () => void
}

export function card(o: CardOptions): HTMLElement {
  const el = document.createElement('button')
  el.className = 'card' + (o.selected ? ' selected' : '')
  el.type = 'button'
  if (o.disabled) el.disabled = true

  const h = document.createElement('h4')
  h.textContent = o.title
  el.appendChild(h)

  if (o.desc) {
    const p = document.createElement('p')
    p.textContent = o.desc
    el.appendChild(p)
  }
  if (o.stats) {
    const s = document.createElement('div')
    s.className = 'stats'
    s.textContent = o.stats
    el.appendChild(s)
  }
  if (o.price) {
    const s = document.createElement('div')
    s.className = 'price'
    s.textContent = o.price
    el.appendChild(s)
  }
  if (o.onClick) el.addEventListener('click', o.onClick)
  return el
}

export function grid(children: readonly HTMLElement[]): HTMLElement {
  const g = document.createElement('div')
  g.className = 'card-grid'
  g.append(...children)
  return g
}
