/**
 * 전투 계산의 입출력 타입 — `formulas.ts` 가 쓰는 데이터 모양만 모은 파일.
 *
 * 원본 `reference/blocky-rpg.html` 의 `P`(2161) · `CLASSES`(2173) · `WEAPONS`(4566) 중
 * **전투 계산에 실제로 쓰이는 필드만** 추렸다. 렌더/색상/설명 문구는 여기 없다.
 *
 * 결정론적 코어다. three.js / DOM / Node API 를 import 하지 않는다.
 */

import type { SkillId } from '../skills/tree'

/** 투자된 스킬 랭크. 원본의 `SK = { nodeId: rank }` 에 대응한다. */
export type SkillRanks = Readonly<Partial<Record<SkillId, number>>>

/** 원본 `CLASSES[id]` 중 전투 계산에 실제로 쓰이는 필드만 추린 것. */
export interface ClassMods {
  readonly dmgMul: number
  readonly cdMul: number
  readonly spdMul: number
  readonly jumpMul: number
  readonly goldMul: number
  readonly xpMul: number
  /** 최대 HP 가산 (검사 +50, 궁수 −5 …) */
  readonly hp: number
  /** 특수기 기본 쿨타임(초) */
  readonly spCd: number
  readonly ranged?: boolean
  readonly water?: boolean
  /** 네크로맨서 처치 시 해골 소환 확률 */
  readonly raise?: number
}

/** 직업 미선택 상태. 원본 `let CLS = {...}` 초기값과 같다. */
export const NO_CLASS: ClassMods = {
  dmgMul: 1,
  cdMul: 1,
  spdMul: 1,
  jumpMul: 1,
  goldMul: 1,
  xpMul: 1,
  hp: 0,
  spCd: 0,
} as const

/** 원본 `WEAPONS[]` 항목 중 recalc 가 읽는 필드. */
export interface WeaponMods {
  readonly dmg?: number
  readonly crit?: number
  /** 쿨타임 승수 가산. 음수면 공속 증가 (`cdB *= 1 + cd`) */
  readonly cd?: number
  readonly gold?: number
  readonly reach?: number
  readonly fire?: boolean
}

export const BARE_WEAPON: WeaponMods = {} as const

/** recalc 가 읽는 플레이어 상태의 최소 집합. */
export interface PlayerCore {
  readonly lv: number
}

/** 전투 중 변하는 플레이어 상태. 파생 스탯은 여기 넣지 않는다. */
export interface PlayerState extends PlayerCore {
  readonly hp: number
  readonly xp: number
  readonly need: number
  readonly sp: number
  readonly gold: number
  readonly dead: boolean
  /** 남은 무적 시간(초) */
  readonly invul: number
}

export interface RecalcCtx {
  readonly skills: SkillRanks
  /** 직업 미선택이면 `NO_CLASS` */
  readonly cls: ClassMods
  readonly weapon: WeaponMods
}

/**
 * 파생 스탯. **저장하지 않는다.** 레벨/스킬/직업/무기가 바뀔 때마다 `recalc()` 로 다시 만든다.
 * 원본은 이 값들을 `P` 에 되써서 저장 슬롯과 파생값이 섞였다 (D-계열 결함의 뿌리).
 */
export interface DerivedStats {
  readonly maxHp: number
  readonly dmg: number
  /** 크리티컬 확률 0..1 */
  readonly crit: number
  /** 크리티컬 배율 */
  readonly critDmg: number
  /** 준 피해 흡혈 비율 */
  readonly vamp: number
  /** 초당 HP 재생 */
  readonly hpReg: number
  /** 골드 배율 */
  readonly goldB: number
  /** 경험치 배율 */
  readonly xpB: number
  /** 회피 확률 (최대 0.5) */
  readonly evade: number
  /** 이동속도 배율 */
  readonly spdB: number
  /** 받는 피해 승수. 1 이 기본, 낮을수록 튼튼하다 */
  readonly guard: number
  /** 공격 쿨타임 승수. 낮을수록 빠르다 */
  readonly cdB: number
  /** 특수기 쿨타임 승수 */
  readonly spCdB: number
  /** 점프력 배율 */
  readonly jumpB: number
  /** 피해 반사 비율 (원본은 계산만 하고 소비처가 없다 — 아래 §미연결 참조) */
  readonly reflect: number
  /** 무기 사거리 가산 */
  readonly reach: number
  /** 화염 무기 여부 */
  readonly fire: boolean
  /** 정점(apex) 배율. 디버그·툴팁용으로 노출한다 */
  readonly apexMul: number
}
