/**
 * 부트스트랩 — 시작 화면, 게임 생성, 패널 배선.
 *
 * "아이가 URL 하나를 열어서 폰에서 조물주까지 간다" 가 목표다 (GOAL.md).
 * 그래서 시작 화면은 **이름 하나만 묻고** 바로 들어간다. 계정도, 로그인도 없다.
 */

import './ui/styles.css'
import { Game } from './game'
import type { GameRefs } from './game'
import {
  classPanel,
  deathPanel,
  pausePanel,
  settingsPanel,
  shopPanel,
  skillPanel,
} from './ui/game-panels'
import type { PanelActions, PlayerView } from './ui/game-panels'
import { button } from './ui/panels'
import { fetchRooms, renderRoomList } from './ui/room-list'
import {
  clearCharacter,
  inviteUrl,
  loadCharacter,
  recallName,
  newRoomCode,
  recallRoom,
  rememberName,
  roomFromUrl,
  saveCharacter,
} from './storage'
import type { CharacterSave, ClassId, WeaponId } from '@bq/shared'
import { ANIM, SAVE_VERSION } from '@bq/shared'

/**
 * 서버 주소. 빌드 시 `VITE_SERVER_URL` 로 주입한다 (배포 체크리스트 3번).
 *
 * 주소에 **방 코드가 경로로 들어간다** (`/room/ABCD`). Durable Object 가
 * 이름으로 인스턴스를 찾기 때문이다 — 같은 코드는 반드시 같은 방으로 간다.
 * 로컬 Node 서버는 경로를 무시하므로 같은 주소 형식이 양쪽 모두에서 통한다.
 *
 * 주입값이 없고 로컬도 아니면 **빈 문자열**을 돌려준다 — 그러면 게임이
 * 처음부터 혼자 하기(루프백)로 시작한다. 정적 호스팅에 서버 없이 올린 경우다.
 */
function serverBase(): string {
  const injected = import.meta.env['VITE_SERVER_URL']
  if (typeof injected === 'string' && injected) return injected.replace(/\/+$/, '')
  const local = location.hostname === 'localhost' || location.hostname === '127.0.0.1'
  return local ? `ws://${location.hostname}:8787` : ''
}

function serverUrl(roomCode: string): string {
  const base = serverBase()
  return base ? `${base}/room/${roomCode}` : ''
}

function el<T extends HTMLElement>(sel: string): T {
  const found = document.querySelector<T>(sel)
  if (!found) throw new Error(`요소를 찾을 수 없다: ${sel}`)
  return found
}

function refs(): GameRefs {
  return {
    canvas: el<HTMLCanvasElement>('#view'),
    overlay: el('#worldOverlay'),
    panels: el('#panels'),
    cutscene: el('#cutscene'),
    bossbar: el('#bossbar'),
    minimap: el<HTMLCanvasElement>('#minimap'),
    touch: el('#touch'),
    joyZone: el('#joyZone'),
    joy: el('#joy'),
    knob: el('#joyKnob'),
    btnAttack: el('#btnAttack'),
    btnJump: el('#btnJump'),
    btnSpecial: el('#btnSpecial'),
  }
}

/* ────────────────────────── 시작 화면 ────────────────────────── */

function boot(): void {
  // 시작 화면 그림. 하위 경로 배포(`/minchan_rpg/`)에서도 맞도록 base 를 붙인다.
  // 파일이 없으면 배경만 안 그려지고 나머지는 그대로 동작한다.
  document.documentElement.style.setProperty(
    '--title-img',
    `url("${import.meta.env.BASE_URL}title.png")`,
  )

  const bootEl = el('#boot')
  const fill = el('#bootFill')
  const msg = el('#bootMsg')

  const invited = roomFromUrl()
  const savedName = recallName()

  const form = document.createElement('div')
  form.className = 'boot-form'
  form.style.cssText = 'display:flex;flex-direction:column;gap:12px;align-items:center;width:min(320px,80vw)'

  const nameInput = document.createElement('input')
  nameInput.type = 'text'
  nameInput.maxLength = 16
  nameInput.placeholder = '이름'
  nameInput.value = savedName
  nameInput.style.cssText =
    'width:100%;min-height:48px;padding:12px 16px;border-radius:12px;border:1px solid rgba(150,200,255,.3);background:rgba(18,28,46,.9);color:#eaf4ff;font-size:16px;text-align:center'

  const codeInput = document.createElement('input')
  codeInput.type = 'text'
  codeInput.maxLength = 8
  codeInput.placeholder = '초대 코드 (없으면 비워두기)'
  codeInput.value = invited ?? ''
  codeInput.style.cssText = nameInput.style.cssText + ';letter-spacing:.18em;text-transform:uppercase'

  const go = button(
    invited ? '친구 방에 들어가기' : '시작하기',
    () => {
      const name = nameInput.value.trim() || '모험가'
      rememberName(name)
      const code = codeInput.value.trim().toUpperCase() || recallRoom() || undefined
      form.remove()
      msg.textContent = '세계를 짓는 중…'
      fill.style.width = '35%'
      startGame(name, code, bootEl, fill, msg)
    },
    'primary',
  )
  go.style.width = '100%'

  form.append(nameInput, codeInput, go)
  bootEl.appendChild(form)

  // 열린 방 목록. 코드를 받아 적는 것보다 눌러서 들어가는 게 빠르다.
  // 못 가져와도 입장 화면은 그대로 동작한다 (서버가 없을 수도 있다).
  const listHost = document.createElement('div')
  listHost.className = 'boot-rooms'
  bootEl.appendChild(listHost)
  void fetchRooms(serverBase()).then((rooms) => {
    renderRoomList(listHost, rooms, {
      onPick: (picked) => {
        codeInput.value = picked
        go.click()
      },
    })
  })
  msg.textContent = invited ? '초대받은 방이 있다' : '이름을 정하자'
  fill.style.width = '10%'
  nameInput.focus()

  nameInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') go.click()
  })
  codeInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') go.click()
  })
}

function startGame(
  name: string,
  roomCode: string | undefined,
  bootEl: HTMLElement,
  fill: HTMLElement,
  msg: HTMLElement,
): void {
  // 방 코드를 여기서 확정한다. 초대받았으면 그 코드, 아니면 직전 방, 그것도 없으면 새로 만든다.
  const code = roomCode ?? recallRoom() ?? newRoomCode()

  const saved = loadCharacter()

  // 접속 시점에 서버로 보낼 저장 데이터.
  // 첫 접속에는 지난 판을, 재접속에는 **지금까지의 진행**을 싣는다
  // (서버가 재시작되면 룸이 사라지고 재접속이 새 방을 만들기 때문이다).
  let live: Game | null = null
  const saveProvider = (): unknown => (live ? snapshotSave(live) : saved) ?? undefined

  const game = new Game(refs(), {
    serverUrl: serverUrl(code),
    name,
    saveProvider,
    roomCode: code,
    // 초대 링크로 들어온 사람은 혼자 하기로 넘어가지 않는다 —
    // 친구를 만나러 왔는데 조용히 솔로가 되면 "왜 안 보이지" 가 된다.
    soloFallback: roomCode === undefined,
  })
  live = game
  if (saved) game.cutscene.seenIds.forEach(() => undefined)
  saved?.seenCutscenes.forEach((id) => game.cutscene.markSeen(id))

  game.onReady = () => {
    fill.style.width = '100%'
    msg.textContent = '준비 완료'
    setTimeout(() => bootEl.classList.add('done'), 240)
    // 첫 판이면 오프닝을 보여준다. 두 번째부터는 markSeen 이 막는다.
    if (!saved) void game.cutscene.play('opening')
  }

  // 개발 편의: 브라우저 콘솔에서 상태를 들여다볼 수 있게 한다. 배포 빌드에서는 사라진다.
  if (import.meta.env.DEV) {
    ;(window as unknown as { __bq: Game }).__bq = game
  }

  wirePanels(game)
  wireAutosave(game)
  wireHudButtons(game)
}

/* ────────────────────────── 패널 배선 ────────────────────────── */

function wirePanels(game: Game): void {
  const view = (): PlayerView => {
    const me = game.me
    const self = game.selfState
    return {
      level: me?.level ?? 1,
      gold: self?.gold ?? 0,
      sp: self?.sp ?? 0,
      classId: (me?.classId as ClassId | null) ?? null,
      weaponId: me?.weaponId ?? 'stick',
      owned: self?.owned ?? ['stick'],
      skills: self?.skills ?? {},
    }
  }

  const act: PanelActions = {
    respawn: () => game.net.send({ t: 'respawn' }),
    pickClass: (id) => game.net.send({ t: 'pickClass', classId: id }),
    learnSkill: (nodeId) => game.net.send({ t: 'learnSkill', nodeId }),
    respec: () => game.net.send({ t: 'respec' }),
    buyWeapon: (id) => game.net.send({ t: 'buyWeapon', weaponId: id }),
    equipWeapon: (id) => game.net.send({ t: 'equipWeapon', weaponId: id }),
    toggleFullscreen: () => {
      if (document.fullscreenElement) void document.exitFullscreen()
      else void document.documentElement.requestFullscreen().catch(() => undefined)
    },
    leaveRoom: () => {
      clearCharacter()
      location.href = location.pathname
    },
    copyRoomCode: () => {
      const url = inviteUrl(game.net.roomCode)
      void navigator.clipboard?.writeText(url).then(
        () => game.hud.toast('초대 링크를 복사했다'),
        () => game.hud.toast(url, 6000),
      )
    },
  }

  const openSettings = (): void =>
    game.panels.push(
      settingsPanel(game.input.settings, game.audio, () => undefined, act),
    )

  game.openTree = () => game.panels.toggle(skillPanel(view, act))
  game.openShop = () => game.panels.toggle(shopPanel(view, act))
  game.openPause = () => game.panels.toggle(pausePanel(game.net.roomCode, openSettings, act))

  // Lv 5 도달 시 직업 선택을 강제로 연다 (FR-1.4). 이 창만 ESC 로 닫히지 않는다.
  let forcedShown = false
  /** 마지막으로 살아 있을 때의 골드. 사망 창에 "얼마 잃었는지" 를 보여주는 데 쓴다. */
  let goldWhileAlive = 0

  game.onSnapshot = (s) => {
    const me = s.players.find((p) => p.id === game.net.playerId)
    if (!me) return

    if (!forcedShown && me.level >= 5 && me.classId === null) {
      forcedShown = true
      game.panels.push(classPanel(view, act, true))
    }
    if (me.classId !== null) game.panels.resolveModal('class')

    /*
     * 사망 창은 **이벤트가 아니라 스냅샷으로** 여닫는다 (FR-2.6).
     *
     * `playerDied` 이벤트로 열면, 바로 뒤따라온 스냅샷이 "살아 있다" 고 말하는 순간
     * 창이 닫혀 버린다. 두 신호가 경쟁하면 깜빡인다.
     * 스냅샷은 서버가 확정한 상태라 이걸 하나만 보면 경쟁이 없고,
     * 이벤트를 놓쳐도(재접속 등) 스스로 복구된다.
     */
    const dead = (me.anim & ANIM.DEAD) !== 0
    if (!dead) {
      goldWhileAlive = s.self.gold
      game.panels.resolveModal('dead')
    } else if (!game.panels.has('dead')) {
      game.panels.push(deathPanel(Math.max(0, goldWhileAlive - s.self.gold), act))
    }
  }

  ;(el('#btnTree') as HTMLButtonElement).addEventListener('click', () => game.openTree?.())
  ;(el('#btnPause') as HTMLButtonElement).addEventListener('click', () => game.openPause?.())
  ;(el('#btnSettings') as HTMLButtonElement).addEventListener('click', openSettings)
}

function wireHudButtons(game: Game): void {
  const shopBtn = el<HTMLButtonElement>('#btnShop')
  shopBtn.addEventListener('click', () => game.openShop?.())

  // 상점 근처에서만 버튼을 띄운다 (원본 동작).
  setInterval(() => {
    const me = game.me
    if (!me) return
    const near = Math.hypot(me.x - 17, me.z - 14) < 8
    shopBtn.classList.toggle('hidden', !near)
  }, 250)
}

/* ────────────────────────── 자동 저장 ────────────────────────── */

/**
 * 30초마다 · 페이지를 떠날 때 저장한다 (FR-6.2).
 * **D-9 수정**: 저장이 실패하면 조용히 넘어가지 않고 한 번 알린다 (NFR-10).
 */
/**
 * 지금 상태를 저장 데이터로 만든다. 서버 스냅샷이 아직 없으면 null.
 * 자동 저장과 접속 핸드셰이크가 **같은 것**을 쓴다 — 둘이 갈리면
 * "저장은 됐는데 복원되는 값은 다른" 상태가 된다.
 */
function snapshotSave(game: Game): CharacterSave | null {
  const me = game.me
  const self = game.selfState
  if (!me || !self) return null
  return {
    v: SAVE_VERSION,
    name: me.name,
    lv: me.level,
    xp: self.xp,
    gold: self.gold,
    sp: self.sp,
    cls: (me.classId as ClassId | null) ?? null,
    weapon: me.weaponId as WeaponId,
    owned: self.owned as WeaponId[],
    skills: self.skills,
    pt: Math.round(game.elapsed),
    gates: game.gateState,
    seenCutscenes: game.cutscene.seenIds,
  }
}

function wireAutosave(game: Game): void {
  let warned = false

  const save = (): void => {
    const data = snapshotSave(game)
    if (!data) return
    const result = saveCharacter(data)
    if (!result.ok && !warned) {
      warned = true
      game.hud.toast('저장할 수 없습니다 — 진행이 남지 않아요')
    }
  }

  setInterval(save, 30_000)
  window.addEventListener('beforeunload', save)
  window.addEventListener('pagehide', save)
}

/* ────────────────────────── 진입점 ────────────────────────── */

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', boot, { once: true })
} else {
  boot()
}
