/**
 * 보스 성 3채 — 원본 `reference/blocky-rpg.html` 1357–1453, 호출부 1654–1662.
 *
 * 성벽은 충돌체라 **정문으로만** 들어갈 수 있고, 잡몹은 성 안으로 진입하지 못한다.
 * 정문은 성에서 바이옴 중심을 바라본다 (`castleGateAngle`).
 */

import * as THREE from 'three'
import {
  CASTLES,
  CASTLE_R,
  CASTLE_H,
  CASTLE_WALL_SEGMENTS,
  CASTLE_GATE_HALF_ANGLE,
  CASTLE_WALL_COLLIDER_R,
  CASTLE_TOWER_COLLIDER_R,
  CASTLE_PILLAR_COLLIDER_R,
  CASTLE_TOWER_COUNT,
  CASTLE_TOWER_ANGLE_OFFSET,
  CASTLE_CLEAR_INSET,
  CASTLE_BRAZIER_R_FACTOR,
  castleGateAngle,
} from '@bq/shared'
import type { BossSiteId, WorldCircle } from '@bq/shared'
import { rboxGeo, TM, GLOW } from '../artkit'
import { TAU, LM, add, circle, cone, cyl, ring, sphere } from './kit'
import type { Collider } from './kit'

/** 성 색 팔레트. 원본 `buildCastle` 호출부(1654–1662)의 `opt` 를 그대로 옮겼다. */
const PALETTE: Readonly<
  Record<BossSiteId, { stone: number; stone2: number; trim: number; floor: number; accent: number }>
> = {
  sea: { stone: 0x4d6470, stone2: 0x3c515c, trim: 0x6d8794, floor: 0x35474f, accent: 0x4fd8e8 },
  volc: { stone: 0x4a3730, stone2: 0x38271f, trim: 0x6b4a3a, floor: 0x3a2620, accent: 0xff7a2a },
  ice: { stone: 0x8fa8bb, stone2: 0x7189a0, trim: 0xb6cfe0, floor: 0x6d8598, accent: 0x9fe8ff },
}

/** 화롯불 충돌 반경. shared 에 없는 값이라 여기 둔다 (원본 1449). */
const BRAZIER_COLLIDER_R = 1.1

function siteOf(id: BossSiteId): (typeof CASTLES)[number] {
  const site = CASTLES.find((c) => c.id === id)
  if (!site) throw new Error(`알 수 없는 성 id: ${id}`)
  return site
}

/**
 * 성을 짓기 전에 걷어내야 할 기존 충돌체 영역.
 *
 * 원본은 `buildCastle` 안에서 전역 `colliders` 를 직접 `splice` 했다 (1369–1372).
 * 빌더가 전역을 만지지 않도록 **영역만 알려주고 실제 제거는 월드 조립기가 한다.**
 * 이 단계를 빼먹으면 나무·바위가 성 안에 남아 보스전을 막는다.
 */
export function castleClearZone(id: BossSiteId): WorldCircle {
  const site = siteOf(id)
  return { x: site.x, z: site.z, r: CASTLE_R - CASTLE_CLEAR_INSET }
}

/** 보스 성 한 채. 안뜰 · 제단 · 성벽 · 탑 6기 · 정문 · 화롯불 4기. */
export function buildCastle(id: BossSiteId): { group: THREE.Group; colliders: Collider[] } {
  const site = siteOf(id)
  const pal = PALETTE[id]

  const group = new THREE.Group()
  const colliders: Collider[] = []
  const cx = site.x
  const cz = site.z
  const R = CASTLE_R
  const H = CASTLE_H[id]
  const gateA = castleGateAngle(site, site.biome)
  const gw = CASTLE_GATE_HALF_ANGLE

  const STONE = TM(pal.stone, 'rock', 0.92)
  const STONE2 = TM(pal.stone2, 'rock', 0.94)
  const TRIMC = TM(pal.trim, 'rock', 0.85)
  const ACC = GLOW(pal.accent, 1.6)

  /* 안뜰 바닥 */
  const yard = new THREE.Mesh(circle(R - 1.5, 56), LM(pal.floor))
  yard.rotation.x = -Math.PI / 2
  yard.position.set(cx, 0.06, cz)
  add(group, yard, false, true)

  /* 중앙 제단 — 보스가 서는 자리 */
  for (let i = 0; i < 3; i++) {
    const st = new THREE.Mesh(cyl(9 - i * 2.2, 9.6 - i * 2.2, 0.5, 40), STONE2)
    st.position.set(cx, 0.25 + i * 0.5, cz)
    add(group, st, false, true)
  }
  const rune = new THREE.Mesh(ring(3.4, 4.4, 40), ACC)
  rune.rotation.x = -Math.PI / 2
  rune.position.set(cx, 1.82, cz)
  add(group, rune)

  /* 성벽 — 정문 각도 구간만 비운다 */
  const segW = (TAU / CASTLE_WALL_SEGMENTS) * R * 1.16
  for (let i = 0; i < CASTLE_WALL_SEGMENTS; i++) {
    const a = (i / CASTLE_WALL_SEGMENTS) * TAU
    let da = a - gateA
    while (da > Math.PI) da -= TAU
    while (da < -Math.PI) da += TAU
    if (Math.abs(da) < gw) continue // 정문 구멍
    const wx = cx + Math.cos(a) * R
    const wz = cz + Math.sin(a) * R
    const seg = new THREE.Mesh(rboxGeo(segW, H, 3.2, 0.25, 0), STONE)
    seg.position.set(wx, H / 2, wz)
    seg.rotation.y = -a
    add(group, seg, true, true)
    if (i % 2 === 0) {
      const cr = new THREE.Mesh(rboxGeo(segW * 0.55, 2.2, 3.4, 0.2, 0), TRIMC)
      cr.position.set(wx, H + 1.1, wz)
      cr.rotation.y = -a
      add(group, cr, true)
    }
    colliders.push({ x: wx, z: wz, r: CASTLE_WALL_COLLIDER_R })
  }

  /* 탑 6기 */
  for (let i = 0; i < CASTLE_TOWER_COUNT; i++) {
    const a = (i / CASTLE_TOWER_COUNT) * TAU + CASTLE_TOWER_ANGLE_OFFSET
    const tx = cx + Math.cos(a) * R
    const tz = cz + Math.sin(a) * R
    const tw = new THREE.Mesh(cyl(4.2, 5.0, H + 7, 16), STONE2)
    tw.position.set(tx, (H + 7) / 2, tz)
    add(group, tw, true, true)
    const rim = new THREE.Mesh(cyl(5.0, 4.6, 1.6, 16), TRIMC)
    rim.position.set(tx, H + 7.4, tz)
    add(group, rim, true)
    for (let k = 0; k < 8; k++) {
      const b2 = (k / 8) * TAU
      const mr = new THREE.Mesh(rboxGeo(1.5, 1.9, 1.2, 0.15, 0), TRIMC)
      mr.position.set(tx + Math.cos(b2) * 4.5, H + 9.0, tz + Math.sin(b2) * 4.5)
      mr.rotation.y = -b2
      add(group, mr)
    }
    const spire = new THREE.Mesh(cone(5.2, 8.5, 16), STONE)
    spire.position.set(tx, H + 13.6, tz)
    add(group, spire, true)
    const orb = new THREE.Mesh(sphere(0.85, 12, 10), ACC)
    orb.position.set(tx, H + 18.4, tz)
    add(group, orb)
    colliders.push({ x: tx, z: tz, r: CASTLE_TOWER_COLLIDER_R })
  }

  /* 정문 — 좌우 문기둥과 상인방 */
  for (const sd of [-1, 1] as const) {
    const pa = gateA + sd * gw * 1.05
    const px = cx + Math.cos(pa) * R
    const pz = cz + Math.sin(pa) * R
    const pil = new THREE.Mesh(cyl(2.6, 3.1, H + 5, 14), TRIMC)
    pil.position.set(px, (H + 5) / 2, pz)
    add(group, pil, true)
    const fin = new THREE.Mesh(cone(3.0, 5.0, 14), STONE)
    fin.position.set(px, H + 7.5, pz)
    add(group, fin, true)
    colliders.push({ x: px, z: pz, r: CASTLE_PILLAR_COLLIDER_R })
  }
  const lintel = new THREE.Mesh(rboxGeo(R * gw * 2.6, 3.0, 4.0, 0.3, 0), STONE)
  lintel.position.set(cx + Math.cos(gateA) * R, H + 1.5, cz + Math.sin(gateA) * R)
  lintel.rotation.y = -gateA
  add(group, lintel, true)

  /* 안뜰 화롯불 4기 */
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU + 0.78
    const bx = cx + Math.cos(a) * (R * CASTLE_BRAZIER_R_FACTOR)
    const bz = cz + Math.sin(a) * (R * CASTLE_BRAZIER_R_FACTOR)
    const col = new THREE.Mesh(cyl(0.7, 1.0, 4.2, 10), STONE2)
    col.position.set(bx, 2.1, bz)
    add(group, col, true)
    const bowl = new THREE.Mesh(cyl(1.5, 0.8, 1.1, 12), TRIMC)
    bowl.position.set(bx, 4.6, bz)
    add(group, bowl, true)
    const fire = new THREE.Mesh(sphere(1.05, 10, 8), ACC)
    fire.position.set(bx, 5.3, bz)
    add(group, fire)
    const lt = new THREE.PointLight(pal.accent, 1.1, 26)
    lt.position.set(bx, 6.0, bz)
    group.add(lt)
    colliders.push({ x: bx, z: bz, r: BRAZIER_COLLIDER_R })
  }

  return { group, colliders }
}
