/**
 * 키보드 어댑터.
 *
 * D-3 수정: 원본에는 ESC 바인딩이 아예 없었다. 여기서 `menu` 커맨드로 잇는다.
 * docs/04 §3.2 확정안: `E` 는 상점 상호작용 전용이고, 공격 대체키는 `F`/`J` 다.
 */

import type { InputHub, UiCommand } from './state'

type Binding = { readonly move?: { x?: number; z?: number }; readonly ui?: UiCommand }

/** 기본 키맵. 리매핑(FR-8.8)은 이 표를 갈아끼우는 것으로 구현한다. */
export const DEFAULT_KEYMAP: Readonly<Record<string, Binding>> = {
  KeyW: { move: { z: -1 } },
  ArrowUp: { move: { z: -1 } },
  KeyS: { move: { z: 1 } },
  ArrowDown: { move: { z: 1 } },
  KeyA: { move: { x: -1 } },
  ArrowLeft: { move: { x: -1 } },
  KeyD: { move: { x: 1 } },
  ArrowRight: { move: { x: 1 } },
  KeyT: { ui: 'tree' },
  KeyE: { ui: 'shop' },
  KeyM: { ui: 'map' },
  KeyC: { ui: 'cameraReset' },
  Tab: { ui: 'autoAttack' },
  Escape: { ui: 'menu' },
}

const ATTACK_KEYS = new Set(['KeyF', 'KeyJ'])
const SPECIAL_KEYS = new Set(['KeyQ', 'KeyR'])
const JUMP_KEYS = new Set(['Space'])
const RUN_KEYS = new Set(['ShiftLeft', 'ShiftRight'])

/** 브라우저 기본 동작(스크롤·포커스 이동)을 막아야 하는 키 */
const SWALLOW = new Set([
  'Space',
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
  'Tab',
])

export function attachKeyboard(hub: InputHub, target: Window = window): () => void {
  const held = new Set<string>()

  const recomputeMove = (): void => {
    let x = 0
    let z = 0
    for (const code of held) {
      const b = DEFAULT_KEYMAP[code]
      if (b?.move) {
        x += b.move.x ?? 0
        z += b.move.z ?? 0
      }
    }
    hub.raw.keyMove.x = x
    hub.raw.keyMove.z = z
  }

  const onDown = (e: KeyboardEvent): void => {
    if (e.repeat) return
    hub.markDevice('keyboard')
    if (SWALLOW.has(e.code)) e.preventDefault()

    held.add(e.code)

    if (ATTACK_KEYS.has(e.code)) hub.raw.attackHeld = true
    if (SPECIAL_KEYS.has(e.code)) hub.raw.specialEdge = true
    if (JUMP_KEYS.has(e.code)) hub.raw.jumpEdge = true
    if (RUN_KEYS.has(e.code)) hub.raw.runHeld = true

    const b = DEFAULT_KEYMAP[e.code]
    if (b?.ui) hub.pushUi(b.ui)
    if (b?.move) recomputeMove()
  }

  const onUp = (e: KeyboardEvent): void => {
    held.delete(e.code)
    if (ATTACK_KEYS.has(e.code)) hub.raw.attackHeld = false
    if (RUN_KEYS.has(e.code)) hub.raw.runHeld = false
    if (DEFAULT_KEYMAP[e.code]?.move) recomputeMove()
  }

  /** 탭 전환·창 최소화로 키가 눌린 채 남는 것을 막는다. */
  const onBlur = (): void => {
    held.clear()
    hub.raw.keyMove.x = 0
    hub.raw.keyMove.z = 0
    hub.raw.attackHeld = false
    hub.raw.runHeld = false
  }

  target.addEventListener('keydown', onDown as EventListener)
  target.addEventListener('keyup', onUp as EventListener)
  target.addEventListener('blur', onBlur)

  return () => {
    target.removeEventListener('keydown', onDown as EventListener)
    target.removeEventListener('keyup', onUp as EventListener)
    target.removeEventListener('blur', onBlur)
  }
}
