/**
 * 스프링 체인 — 망토·끈·너덜거리는 옷자락의 2차 모션.
 * 원본 `reference/blocky-rpg.html` 2134–2157 (`SPRINGS` / `addSpring` / `springsUpdate`).
 *
 * 캐릭터 리그(`makeHero`)가 4164·4175·4195·4264·4271 에서 `addSpring` 을 부른다.
 * 이 파일은 그 갱신 루프만 담당한다 — 리그 조립은 캐릭터 모듈의 몫이다.
 */

import * as THREE from 'three'

export type SpringAxis = 'x' | 'y' | 'z'

export interface SpringHandle {
  readonly object: THREE.Object3D
  readonly axis: SpringAxis
  readonly stiffness: number
  readonly damping: number
  readonly limit: number
  /** 스프링을 걸 때의 각도. 결과는 `base + angle` 이다. */
  readonly base: number
  velocity: number
  angle: number
  readonly prev: THREE.Vector3
}

const _world = new THREE.Vector3()

/** 원본 2151 의 구동 계수 — 몸 기준 전후 속도를 각도로 바꾸는 비율. */
const DRIVE_SCALE = 0.035

/**
 * 원본은 전역 배열 하나였다. 그래서 직업을 바꿀 때 이전 리그의 스프링을 부모를 거슬러
 * 올라가며 직접 골라내야 했다(4338–4341). 여기서는 `removeUnder(root)` 로 캡슐화한다.
 * 부모에서 떨어진 오브젝트는 `update` 가 알아서 걷어낸다 (원본 2147 과 동일).
 */
export class SpringSystem {
  private readonly springs: SpringHandle[] = []

  /** 원본 `addSpring(obj, axis, stiff, damp, limit)` — 기본값도 원본 그대로다. */
  add(
    object: THREE.Object3D,
    axis: SpringAxis = 'x',
    stiffness = 90,
    damping = 11,
    limit = 0.6,
  ): SpringHandle {
    const s: SpringHandle = {
      object,
      axis,
      stiffness,
      damping,
      limit,
      base: object.rotation[axis],
      velocity: 0,
      angle: 0,
      prev: new THREE.Vector3(),
    }
    object.getWorldPosition(s.prev)
    this.springs.push(s)
    return s
  }

  /** `root` 아래에 매달린 스프링을 전부 뗀다. 원본 4338–4341 의 직업 교체 정리. */
  removeUnder(root: THREE.Object3D): void {
    for (let i = this.springs.length - 1; i >= 0; i--) {
      const s = this.springs[i]
      if (!s) continue
      let q: THREE.Object3D | null = s.object
      let owned = false
      while (q) {
        if (q === root) {
          owned = true
          break
        }
        q = q.parent
      }
      if (owned) this.springs.splice(i, 1)
    }
  }

  clear(): void {
    this.springs.length = 0
  }

  get size(): number {
    return this.springs.length
  }

  /**
   * 원본 `springsUpdate` (2143–2157).
   *
   * @param dt  **히트스톱이 적용된** dt. 원본 5659 가 `springsUpdate(dt)` 로 부른다 —
   *            궤적·파티클(rawDt)과 달리 스프링은 히트스톱에 같이 멈춘다.
   * @param yaw 플레이어의 `rotation.y`. 월드 속도를 몸 기준 전후 성분으로 되돌린다.
   */
  update(dt: number, yaw: number): void {
    if (dt <= 0) return
    const sy = Math.sin(yaw)
    const cy = Math.cos(yaw)
    for (let i = this.springs.length - 1; i >= 0; i--) {
      const s = this.springs[i]
      if (!s) continue
      if (!s.object.parent) {
        this.springs.splice(i, 1)
        continue
      }
      s.object.getWorldPosition(_world)
      const dx = (_world.x - s.prev.x) / dt
      const dz = (_world.z - s.prev.z) / dt
      s.prev.copy(_world)
      const drive = -(dx * sy + dz * cy) * DRIVE_SCALE
      s.velocity += (drive - s.angle) * s.stiffness * dt - s.velocity * s.damping * dt
      s.angle += s.velocity * dt
      s.angle = Math.max(-s.limit, Math.min(s.limit, s.angle))
      s.object.rotation[s.axis] = s.base + s.angle
    }
  }
}
