/**
 * 세 바이옴의 지형 메시 — 🌊 침몰한 바다 · 🌋 재의 화산 · ❄️ 얼어붙은 설원.
 *
 * 원본 `reference/blocky-rpg.html` 1481–1612 의 이관본이다.
 * 좌표·개수·반경은 전부 `@bq/shared` 의 월드 상수에서 온다 (T-5).
 * 난수는 호출자가 넘긴 시드 RNG 하나만 쓴다 — 멀티에서 모두가 같은 지형을 봐야 한다.
 *
 * ⚠️ **난수 소비 순서를 바꾸면 지형이 통째로 달라진다.** 원본 코드의 표현식 순서를
 * 그대로 유지했다. 리팩터링 시 `rng()` 호출 순서를 재배치하지 말 것.
 */

import * as THREE from 'three'
import {
  BIOME_PROPS,
  BOSS_ARENA_DISC_R,
  BOSS_SITE,
  ICEFIELD,
  LAVAPOOL_BOSS,
  LAVAPOOL_SPAWN,
  SEA,
  SEA_BOSS_PLATFORM,
  SEA_ISLET_COUNT,
  SEA_ISLET_R_RANGE,
  VOLC,
  range,
  seaIsletPosition,
} from '@bq/shared'
import type { Rng } from '@bq/shared'
import { TM } from './artkit'
import {
  basic,
  boxMesh,
  coneMesh,
  cylinderGeo,
  disc,
  flatCircle,
  iceMaterial,
  lambert,
} from './terrain-parts'
import type { Circle } from './terrain-parts'

/* ═══════════ 원본 리터럴 (좌표가 아닌 순수 룩앤필 값) ═══════════ */

const SEA_COLOR = {
  /** 모래톱 원판 — `SEA.r + 3` */
  sandbarMargin: 3,
  sandbar: 0xbfae82,
  /** 큰 섬(보스 발판)과 작은 징검섬의 색이 다르다 */
  bigIslet: 0x6a7f5a,
  smallIslet: 0x8a8461,
  isletRock: 0x7d7a6a,
  water: 0x1f6fa8,
  waterOpacity: 0.76,
  reed: 0x5f7a3c,
  column: 0x9aa08c,
} as const

/** 이 반경을 넘으면 '큰 섬' 취급 — 색이 바뀌고 잔돌이 놓이지 않는다. 원본 `is.r>10`. */
const SEA_ISLET_BIG_R = 10

const VOLC_COLOR = {
  /** 화산재 원판 — `VOLC.r + 4` */
  ashMargin: 4,
  ash: 0x2e2622,
  /** 안쪽 그을음 원판 — `VOLC.r * 0.55` */
  sootFactor: 0.55,
  soot: 0x241c19,
  lava: 0xff6a22,
  lavaGlow: 0xff3a00,
  lavaGlowOpacity: 0.28,
  /** 발광 테두리는 웅덩이보다 35% 넓다 */
  lavaGlowScale: 1.35,
  spire: 0x241a16,
  calderaFloor: 0x1a1210,
  calderaSpire: 0x2a1d18,
  bossLava: 0xff7a2a,
} as const

const ICE_COLOR = {
  /** 눈 원판 — `ICEFIELD.r + 4` */
  snowMargin: 4,
  snow: 0xdfeaf2,
  /** 안쪽 빙판 원판 — `ICEFIELD.r * 0.7` */
  glazeFactor: 0.7,
  glaze: 0xbcd8e8,
  treeTrunk: 0x5a5148,
  treeLeafLow: 0xdce9f2,
  treeLeafHigh: 0xeef6fb,
  throneFloor: 0x8fc4dc,
} as const

/* ═══════════ 🌊 침몰한 바다 ═══════════ */

export interface SeaResult {
  readonly group: THREE.Group
  readonly colliders: readonly Circle[]
  /** 물 판정에서 육지로 치는 구멍 — 보스 발판 1 + 징검섬 9. 반경만 RNG 다. */
  readonly islets: readonly Circle[]
}

/**
 * 원본 1482–1526.
 *
 * 징검섬의 **위치는 결정론적**(sin/cos)이고 반경만 난수다 — 원본 그대로다.
 * 위치 계산은 `seaIsletPosition()` 이 정본이다.
 */
export function buildSea(rng: Rng): SeaResult {
  const group = new THREE.Group()
  group.name = 'sea'
  const colliders: Circle[] = []

  // 모래톱
  group.add(disc(SEA.x, SEA.z, SEA.r + SEA_COLOR.sandbarMargin, SEA_COLOR.sandbar))

  // 보스 발판 + 징검섬 9개 — 간고등어가 아니어도 건너갈 수 있게
  const islets: Circle[] = [SEA_BOSS_PLATFORM]
  for (let i = 0; i < SEA_ISLET_COUNT; i++) {
    const p = seaIsletPosition(i)
    islets.push({ x: p.x, z: p.z, r: range(rng, SEA_ISLET_R_RANGE.min, SEA_ISLET_R_RANGE.max) })
  }

  for (const is of islets) {
    const big = is.r > SEA_ISLET_BIG_R
    const m = new THREE.Mesh(
      cylinderGeo(is.r, is.r + 1.4, 1.6, 22),
      lambert(big ? SEA_COLOR.bigIslet : SEA_COLOR.smallIslet),
    )
    m.position.set(is.x, -0.78, is.z)
    m.receiveShadow = true
    m.castShadow = true
    group.add(m)
    if (big) continue
    // 작은 섬에는 잔돌 3개. 충돌체는 없다.
    for (let k = 0; k < 3; k++) {
      const a = rng() * 6.28
      const rr = rng() * is.r * 0.6
      const rk = boxMesh(1.2, 0.9, 1.1, SEA_COLOR.isletRock)
      rk.position.set(is.x + Math.cos(a) * rr, 0.4, is.z + Math.sin(a) * rr)
      rk.castShadow = true
      rk.receiveShadow = true
      group.add(rk)
    }
  }

  // 수면 — 애니메이션이 이름으로 찾는다 (원본은 `window.__sea` 전역이었다)
  const water = flatCircle(
    SEA.x,
    SEA.z,
    SEA.r,
    lambert(SEA_COLOR.water, SEA_COLOR.waterOpacity),
    0.35,
    64,
  )
  water.name = 'seaWater'
  group.add(water)

  // 갈대 70 — 충돌체 없음
  const reeds = BIOME_PROPS.seaReeds
  for (let i = 0; i < reeds.count; i++) {
    const a = rng() * 6.283
    const r = SEA.r * range(rng, reeds.rFactorMin, reeds.rFactorMax)
    const rd = boxMesh(0.14, 2.4 + rng() * 1.6, 0.14, SEA_COLOR.reed)
    rd.position.set(SEA.x + Math.cos(a) * r, 1.4, SEA.z + Math.sin(a) * r)
    rd.rotation.z = (rng() - 0.5) * 0.4
    rd.castShadow = true
    group.add(rd)
  }

  // 보스 발판 위 부서진 기둥 5
  const col = BIOME_PROPS.seaBrokenColumns
  for (let i = 0; i < col.count; i++) {
    const a = (i / col.count) * 6.283
    const c = boxMesh(1.6, 4 + rng() * 3, 1.6, SEA_COLOR.column)
    c.position.set(
      SEA_BOSS_PLATFORM.x + Math.cos(a) * col.ringR,
      2.2,
      SEA_BOSS_PLATFORM.z + Math.sin(a) * col.ringR,
    )
    c.rotation.y = rng()
    c.castShadow = true
    c.receiveShadow = true
    group.add(c)
    colliders.push({ x: c.position.x, z: c.position.z, r: col.colliderR })
  }

  return { group, colliders, islets }
}

/* ═══════════ 🌋 재의 화산 ═══════════ */

export interface VolcanoResult {
  readonly group: THREE.Group
  readonly colliders: readonly Circle[]
  /** 용암 판정 영역 — 절차 생성 9개 + 보스 발판 1개. */
  readonly lavaPools: readonly Circle[]
}

/** 원본 `inLava(p)` 의 부분집합 — 첨탑이 웅덩이 위에 서지 않게 하는 데만 쓴다. */
function inAnyPool(x: number, z: number, pools: readonly Circle[]): boolean {
  for (const l of pools) {
    if (Math.hypot(x - l.x, z - l.z) < l.r) return true
  }
  return false
}

/** 원본 1529–1571. */
export function buildVolcano(rng: Rng): VolcanoResult {
  const group = new THREE.Group()
  group.name = 'volcano'
  const colliders: Circle[] = []
  const lavaPools: Circle[] = []

  group.add(disc(VOLC.x, VOLC.z, VOLC.r + VOLC_COLOR.ashMargin, VOLC_COLOR.ash))
  group.add(disc(VOLC.x, VOLC.z, VOLC.r * VOLC_COLOR.sootFactor, VOLC_COLOR.soot, 0.04))

  // 용암 웅덩이 9 — 좌표가 RNG 라 상수로 옮길 수 없다 (constants §4 `LAVAPOOL_SPAWN`)
  const spawn = LAVAPOOL_SPAWN
  for (let i = 0; i < spawn.count; i++) {
    const a = rng() * 6.283
    const r = rng() * spawn.center.r * spawn.radialFactor
    const x = spawn.center.x + Math.cos(a) * r
    const z = spawn.center.z + Math.sin(a) * r
    const rad = range(rng, spawn.radiusMin, spawn.radiusMax)
    lavaPools.push({ x, z, r: rad })
    group.add(flatCircle(x, z, rad, basic(VOLC_COLOR.lava), 0.06, 20))
    group.add(
      flatCircle(
        x,
        z,
        rad * VOLC_COLOR.lavaGlowScale,
        basic(VOLC_COLOR.lavaGlow, VOLC_COLOR.lavaGlowOpacity),
        0.05,
        20,
      ),
    )
  }

  // 현무암 첨탑 40 — 용암 위에는 서지 않는다 (원본은 `continue` 로 그 회차를 통째로 버린다)
  const spires = BIOME_PROPS.volcSpires
  const spireMat = TM(VOLC_COLOR.spire, 'rock', 0.96)
  for (let i = 0; i < spires.count; i++) {
    const a = rng() * 6.283
    const r = rng() * VOLC.r
    const x = VOLC.x + Math.cos(a) * r
    const z = VOLC.z + Math.sin(a) * r
    if (inAnyPool(x, z, lavaPools)) continue
    const h = 3 + rng() * 9
    const sp = coneMesh(1.2 + rng() * 1.4, h, 5, spireMat)
    sp.position.set(x, h / 2, z)
    sp.rotation.y = rng() * 3
    sp.castShadow = true
    sp.receiveShadow = true
    group.add(sp)
    colliders.push({ x, z, r: spires.colliderR })
  }

  // 보스 자리 — 칼데라 테두리
  const bp = BOSS_SITE.volc
  group.add(disc(bp.x, bp.z, BOSS_ARENA_DISC_R, VOLC_COLOR.calderaFloor, 0.05, 32))
  const arena = BIOME_PROPS.volcArenaSpires
  const arenaMat = TM(VOLC_COLOR.calderaSpire, 'rock', 0.95)
  for (let i = 0; i < arena.count; i++) {
    const a = (i / arena.count) * 6.283
    const c = coneMesh(2.2, 8 + rng() * 5, 5, arenaMat)
    c.position.set(bp.x + Math.cos(a) * arena.ringR, 4.5, bp.z + Math.sin(a) * arena.ringR)
    c.castShadow = true
    group.add(c)
    colliders.push({ x: c.position.x, z: c.position.z, r: arena.colliderR })
  }

  // 보스 발판은 통째로 용암이다 — 유일하게 고정된 웅덩이
  lavaPools.push(LAVAPOOL_BOSS)
  group.add(
    flatCircle(
      LAVAPOOL_BOSS.x,
      LAVAPOOL_BOSS.z,
      LAVAPOOL_BOSS.r,
      basic(VOLC_COLOR.bossLava),
      0.07,
      24,
    ),
  )

  return { group, colliders, lavaPools }
}

/* ═══════════ ❄️ 얼어붙은 설원 ═══════════ */

export interface IcefieldResult {
  readonly group: THREE.Group
  readonly colliders: readonly Circle[]
}

/** 원본 1591–1601 의 얼어붙은 나무. 몸통 + 눈 덮인 잎 2단, 배율 없음. */
function frozenTree(x: number, z: number): THREE.Group {
  const g = new THREE.Group()
  const trunk = boxMesh(1.0, 4.0, 1.0, ICE_COLOR.treeTrunk)
  trunk.position.y = 2
  const leaf1 = boxMesh(4.0, 2.0, 4.0, ICE_COLOR.treeLeafLow)
  leaf1.position.y = 4.6
  const leaf2 = boxMesh(2.6, 1.6, 2.6, ICE_COLOR.treeLeafHigh)
  leaf2.position.y = 6.0
  for (const m of [trunk, leaf1, leaf2]) {
    m.castShadow = true
    m.receiveShadow = true
    g.add(m)
  }
  g.position.set(x, 0, z)
  return g
}

/** 원본 1574–1612. 빙판 판정(`onIce`)은 `ICEFIELD` 원 전체다 — 메시와 무관하다. */
export function buildIcefield(rng: Rng): IcefieldResult {
  const group = new THREE.Group()
  group.name = 'icefield'
  const colliders: Circle[] = []
  const ICE = iceMaterial()

  group.add(disc(ICEFIELD.x, ICEFIELD.z, ICEFIELD.r + ICE_COLOR.snowMargin, ICE_COLOR.snow))
  group.add(
    disc(ICEFIELD.x, ICEFIELD.z, ICEFIELD.r * ICE_COLOR.glazeFactor, ICE_COLOR.glaze, 0.04),
  )

  // 얼음 가시 44
  const spikes = BIOME_PROPS.iceSpikes
  for (let i = 0; i < spikes.count; i++) {
    const a = rng() * 6.283
    const r = rng() * ICEFIELD.r
    const x = ICEFIELD.x + Math.cos(a) * r
    const z = ICEFIELD.z + Math.sin(a) * r
    const h = 3 + rng() * 10
    const sp = coneMesh(0.9 + rng() * 1.3, h, 5, ICE)
    sp.position.set(x, h / 2 - 0.4, z)
    sp.rotation.set((rng() - 0.5) * 0.3, rng() * 3, (rng() - 0.5) * 0.3)
    sp.castShadow = true
    group.add(sp)
    colliders.push({ x, z, r: spikes.colliderR })
  }

  // 얼어붙은 나무 22
  const trees = BIOME_PROPS.iceTrees
  for (let i = 0; i < trees.count; i++) {
    const a = rng() * 6.283
    const r = ICEFIELD.r * range(rng, trees.rFactorMin, trees.rFactorMax)
    const x = ICEFIELD.x + Math.cos(a) * r
    const z = ICEFIELD.z + Math.sin(a) * r
    group.add(frozenTree(x, z))
    colliders.push({ x, z, r: trees.colliderR })
  }

  // 보스 자리 — 빙하 왕좌
  const bp = BOSS_SITE.ice
  group.add(disc(bp.x, bp.z, BOSS_ARENA_DISC_R, ICE_COLOR.throneFloor, 0.05, 32))
  const arena = BIOME_PROPS.iceArenaSpires
  for (let i = 0; i < arena.count; i++) {
    const a = (i / arena.count) * 6.283
    const c = coneMesh(2.0, 11 + rng() * 6, 5, ICE)
    c.position.set(bp.x + Math.cos(a) * arena.ringR, 5.5, bp.z + Math.sin(a) * arena.ringR)
    c.castShadow = true
    group.add(c)
    colliders.push({ x: c.position.x, z: c.position.z, r: arena.colliderR })
  }

  return { group, colliders }
}
