/**
 * 룸 — 월드 인스턴스 하나.
 *
 * 진행 게이트는 **룸이 소유한다.** 개인 진행이 아니다.
 * 늦게 합류한 플레이어도 룸이 이미 천국을 열었으면 바로 통과한다.
 *
 * 20 Hz 고정 틱으로 돈다. 렌더는 클라가 60 fps 로 하고, 그 사이는 보간이 메운다.
 *
 * ## 스킬 배선 원칙 (FR-2.12 / D-2)
 *
 * 72노드의 효과는 `resolveSkillEffects()` 가 이미 `SkillModifiers` 값으로 만들어 놓았고
 * (플레이어마다 `p.mods` 에 캐시된다), 이 파일은 그 값을 **전투 사건에 꽂는 일만** 한다.
 * 노드 id(`rk('cleave')` 같은 것)를 여기서 읽지 않는다 — 그렇게 하는 순간
 * "트리에는 있는데 계산에는 없는" 노드가 다시 생긴다.
 *
 * 새 상태가 필요한 효과(몹 디버프 · 소환수)는 `MobState` 를 늘리지 않고 룸이 따로 든다.
 * `MobState` 는 shared 의 결정론적 타입이라 클라 예측 · 스냅샷 · 몹 AI 가 같이 흔들린다.
 *
 * @see packages/shared/src/skills/effects.ts §4 런타임 배선 대기 목록
 */

import {
  AOI_RADIUS,
  BOSS_PHASE_GATES,
  CASTLES,
  COIN,
  COMBO,
  HEAVEN_LEASH,
  MOBTYPES,
  ROOM_CAPACITY,
  RESPAWN_POS,
  TICK_S,
  ZONES,
  autoAimRange,
  bossSkillOf,
  classModsOf,
  buildSpecial,
  deserializeGates,
  distXZ,
  isInFront,
  meleeReach,
  mobDef,
  mulberry32,
  onBossKilled,
  randomPointInZone,
  regionOf,
  respawnSeconds,
  rollCoinDrop,
  rollDamage,
  rollRaiseSkeleton,
  sameRegionGroup,
  spawnPositions,
  stepGates,
  stepMob,
  INITIAL_GATES,
  NO_CLASS,
} from '@bq/shared'
import type {
  ClassMods,
  GameEvent,
  GateBossId,
  GateState,
  InputFrame,
  MobArchetype,
  MobEvent,
  MobId,
  MobState,
  Rng,
  ServerMsg,
  Vec3,
  Zone,
} from '@bq/shared'

import {
  applyInput,
  createPlayer,
  currentSpecialCooldown,
  grantWeapon,
  grantXp,
  hurtPlayer,
  respawnPlayer,
  stepPhysics,
} from './player'
import type { PlayerState, TerrainQuery } from './player'
import { flatTerrain } from './terrain'
import { MobDebuffs } from './mob-debuffs'
import { Minions } from './minions'
import type { Minion, MinionTarget } from './minions'
import { attackMul, combatContextOf, countNearbyEnemies, mobAttackMul } from './skill-runtime'
import { applySpecialCast } from './special-cast'
import { buildSnapshot } from './snapshot'
import { stepFields } from './fields'
import type { FieldState } from './fields'
import { stepCoins, stepProjectiles } from './world-objects'
import type { Coin, Projectile } from './world-objects'

/** 보스 HP 인원 스케일링. 선형(×8)보다 완만하게 — 솔로 난이도를 보존한다. */
const BOSS_HP_SCALE_PER_EXTRA = 0.6

/** 룸이 빈 뒤 파기까지의 유예. 재접속·새로고침을 견딘다. */
export const EMPTY_ROOM_GRACE_MS = 60_000

/** 전리품 지급 기준 — 보스 최대 HP 의 이 비율만큼 기여해야 받는다. */
const LOOT_CONTRIBUTION = 0.05

/** 3연타 마무리 피해 배수 (원본 doAttack 5184). */
const COMBO_FINISHER_MUL = 1.55

/**
 * 피해의 성격.
 *
 * · `direct`   — 플레이어가 직접 낸 타격. 크리 롤 · 흡혈 · 🆕 저주 부착을 받는다.
 * · `indirect` — 지속 피해와 소환수 타격. 원본이 이쪽에 크리도 흡혈도 붙이지 않는다
 *                (해골 6328 은 그냥 `tg.hp -= bd` 다). 저주도 붙이지 않는다 —
 *                중독이 매 틱 저주를 새로 걸면 저주가 영원히 안 풀린다.
 */
type HitKind = 'direct' | 'indirect'

export class Room {
  readonly code: string
  readonly seed: number
  gates: GateState = INITIAL_GATES
  tick = 0
  emptySince: number | null = null

  readonly players = new Map<number, PlayerState>()
  readonly mobs: MobState[] = []
  readonly coins: Coin[] = []
  readonly projectiles: Projectile[] = []
  readonly fields: FieldState[] = []

  /** 🆕 venom · curse · plague — 몹에 붙는 디버프. `MobState` 를 늘리지 않으려고 룸이 든다. */
  readonly debuffs = new MobDebuffs()
  /** rite · 🆕 harvest · 🆕 necroX — 해골 무리. 몹이 아니므로 `mobs` 와 섞지 않는다. */
  readonly minions = new Minions()

  private readonly rng: Rng
  private readonly terrain: TerrainQuery
  private readonly archetypes = new Map<string, MobArchetype>()
  private readonly mobZone = new Map<string, Zone>()
  private readonly mobMaxHp = new Map<string, number>()
  /** id → 몹. 디버프·소환수 타격이 id 로 되돌아오므로 선형 탐색을 피한다. */
  private readonly mobIndex = new Map<string, MobState>()
  /** 보스별 기여 누적: mobId → (playerId → 누적 피해) */
  private readonly contribution = new Map<string, Map<number, number>>()
  private nextEntityId = 1
  private pending: GameEvent[] = []

  constructor(code: string, seed: number) {
    this.code = code
    this.seed = seed
    this.rng = mulberry32(seed)
    this.terrain = flatTerrain()
    this.buildArchetypes()
    this.spawnAll()
  }

  /** 스냅샷 조립이 읽는 소환수 목록. */
  get minionList(): readonly Minion[] {
    return this.minions.all
  }

  /* ────────────────────────── 스폰 ────────────────────────── */

  private buildArchetypes(): void {
    for (const id of Object.keys(MOBTYPES) as MobId[]) {
      const d = mobDef(id)
      this.archetypes.set(id, {
        id,
        name: d.name,
        speed: d.speed,
        aggro: d.aggro ?? 0,
        reach: d.reach,
        cd: d.cd,
        dmg: d.dmg,
        scale: d.scale,
        ranged: d.ranged === true,
        ghost: d.ghost === true,
        boss: d.boss === true,
        world: d.world === true,
        slow: d.slow === true,
        burn: d.burn === true,
        hop: d.hop === true,
        fly: d.fly ?? 0,
        regen: d.regen ?? 0,
      })
    }
  }

  private spawnAll(): void {
    for (const zone of ZONES) {
      for (const point of spawnPositions(zone, this.rng)) {
        this.spawnMob(zone, point.x, point.z)
      }
    }
  }

  private spawnMob(zone: Zone, x: number, z: number): MobState {
    const def = mobDef(zone.type)
    const id = `m${this.nextEntityId++}`
    const hp = this.scaledHp(zone.type)
    const mob: MobState = {
      id,
      type: zone.type,
      pos: { x, y: def.fly ?? 0, z },
      yaw: 0,
      hp,
      maxHp: hp,
      dead: false,
      dieT: 0,
      hitT: 99,
      cd: 0,
      walk: 0,
      roll: 0,
      atkT: 0,
      atkD: 0,
      home: { x, y: 0, z },
      zone: { x: zone.x, z: zone.z, r: zone.r, type: zone.type },
      wander: this.rng() * Math.PI * 2,
      wt: this.rng() * 3,
      bob: this.rng() * Math.PI * 2,
      boss: def.boss === true ? { phase: 0, cast: 0, skCd: 9, pulse: 0, invuln: false } : null,
    }
    this.mobs.push(mob)
    this.mobZone.set(id, zone)
    this.mobMaxHp.set(id, hp)
    this.mobIndex.set(id, mob)
    return mob
  }

  /**
   * 인원수에 따라 보스 HP 를 키운다. 8인이 그대로 때리면 8배 빨리 죽어 연출이 무너진다.
   * 잡몹은 손대지 않는다 — 사냥 리듬은 인원과 무관해야 한다.
   */
  private scaledHp(type: MobId): number {
    const def = mobDef(type)
    if (!def.boss) return def.hp
    const n = Math.max(1, this.players.size)
    return Math.round(def.hp * (1 + BOSS_HP_SCALE_PER_EXTRA * (n - 1)))
  }

  /* ────────────────────────── 접속 ────────────────────────── */

  get full(): boolean {
    return this.players.size >= ROOM_CAPACITY
  }

  join(name: string): PlayerState {
    const id = this.nextEntityId++
    const p = createPlayer(id, name, RESPAWN_POS)
    this.players.set(id, p)
    this.emptySince = null
    this.emit({ k: 'joined', playerId: id, name: p.name })
    return p
  }

  leave(playerId: number): void {
    const p = this.players.get(playerId)
    if (!p) return
    this.players.delete(playerId)
    // 주인이 없는 해골은 남길 이유가 없다 — 피해를 귀속시킬 대상이 사라진다.
    this.minions.removeOwner(playerId)
    this.emit({ k: 'left', playerId })
    if (this.players.size === 0) this.emptySince = Date.now()
  }

  input(playerId: number, frame: InputFrame): void {
    const p = this.players.get(playerId)
    if (!p) return
    p.lastInputAt = Date.now()
    applyInput(p, frame, TICK_S, this.gates, this.terrain)
  }

  /* ────────────────────────── 틱 ────────────────────────── */

  step(): readonly GameEvent[] {
    this.tick++
    const dt = TICK_S

    this.stepPlayers(dt)
    this.stepMobs(dt)
    this.stepMinions(dt)
    this.stepProjectiles(dt)
    this.stepFields(dt)
    this.stepDebuffs(dt)
    this.stepCoins(dt)
    this.stepGateState()

    const out = this.pending
    this.pending = []
    return out
  }

  private stepPlayers(dt: number): void {
    for (const p of this.players.values()) {
      const before = p.dead
      const ev = stepPhysics(p, dt, this.terrain)
      if (ev.burned > 0) {
        this.emit({ k: 'damage', targetId: p.id, amount: ev.burned, crit: false, isMob: false })
      }
      if (!before && p.dead) this.emit({ k: 'playerDied', playerId: p.id })

      if (p.dead) continue

      // 🆕 splash(파도치기) · 🆕 bounce(통통) — 착지 충격이 곧 광역 피해다.
      if (ev.landed > 0) this.landingAoe(p)

      if (p.wantsAttack && p.attackCd <= 0) this.playerAttack(p)
      // 🆕 bossX(종말) — 충전분이 있으면 쿨이 남아 있어도 시전한다.
      if (p.wantsSpecial && p.classId && (p.specialCd <= 0 || p.specialCharged)) {
        this.playerSpecial(p)
      }
    }
  }

  /**
   * 근접 공격 — 전방 부채꼴 안의 적 **전원**을 때린다 (원본 동작).
   *
   * 여기서 살아나는 노드: 🆕 mop(사거리) · 🆕 cleave(후방) · 🆕 swordX(콤보 배수 · 마무리 폭발) ·
   * 🆕 kite(공격 직후 이속) · rage · 🆕 wrath · 🆕 sprint · 🆕 flock · 🆕 snipe · cure · 🆕 fishX.
   */
  private playerAttack(p: PlayerState): void {
    // ⚠️ 콤보 단계를 **먼저** 올리고 마무리를 판정한다 (원본 5150–5153 `P.combo=…; fin = P.combo===2`).
    //    거꾸로 하면 마무리가 3타가 아니라 4타에 터진다. swordX("3연타 마무리")가 그 오차 위에
    //    얹히면 설명 텍스트가 거짓이 된다.
    p.comboStep = p.comboT > 0 ? (((p.comboStep + 1) % COMBO.LENGTH) as 0 | 1 | 2) : 0
    const finisher = p.comboStep === COMBO.FINISHER_INDEX
    p.comboT = COMBO.WINDOW
    p.attackCd = (finisher ? COMBO.CD_FINISHER : COMBO.CD_NORMAL) * p.stats.cdB
    p.sinceAttack = 0 // 🆕 kite(견제) 창이 여기서 열린다

    // FR-2.2 자동 조준 — 사거리 안에 적이 있으면 **공격 순간 그쪽을 바라본다**.
    // 이게 없으면 전방 부채꼴(±81°) 판정에 걸려 자동 공격이 거의 빗나간다.
    this.autoAim(p)

    const forward = { x: Math.sin(p.yaw), z: Math.cos(p.yaw) }
    const cls = this.classOf(p)
    const base = p.stats.dmg * cls.dmgMul * (finisher ? COMBO_FINISHER_MUL : 1)

    const at: Vec3 = { x: p.x, y: 0, z: p.z }
    const nearby = countNearbyEnemies(p, this.mobs)
    const inWater = this.terrain.surfaceAt(p.x, p.z, p.classId === 'fish').water

    /** 마무리 폭발의 중심 — 정면으로 맞은 적 중 **가장 가까운** 하나. */
    let epicenter: Vec3 | null = null
    let epicenterD = Infinity

    for (const m of this.mobs) {
      if (m.dead) continue
      const def = mobDef(m.type as MobId)
      // 🆕 mop(물걸레질) — 근접 사거리 가산. 랭크 0 이면 attackRangeFlat 이 0 이다.
      const reach = meleeReach(p.stats.reach + p.mods.attackRangeFlat, def.scale)
      const d = distXZ(at, m.pos)
      if (d > reach || d === 0) continue

      // isInFront 는 **정규화된** 방향을 받는다. 정규화를 빠뜨리면 먼 적일수록 잘 맞는다.
      const front = isInFront(forward, { x: (m.pos.x - p.x) / d, z: (m.pos.z - p.z) / d })
      // 🆕 cleave(참격) — 전방 판정에서 탈락한 적에게 비율 피해.
      //    "뒤쪽" 은 전방 부채꼴(dot ≥ 0.15)의 **여집합**으로 읽었다. 원문이 각도를 말하지 않고,
      //    더 좁게(dot < 0) 잡으면 옆구리(dot 0~0.15)가 아무 피해도 못 받는 구멍이 생긴다.
      const share = front ? 1 : p.mods.rearSplashPct
      if (share <= 0) continue

      const ctx = combatContextOf(p, { targetDistance: d, nearbyEnemyCount: nearby, inWater })
      this.damageMob(m, base * attackMul(p, cls, ctx) * share, p)

      if (front && d < epicenterD) {
        epicenterD = d
        epicenter = m.pos
      }
    }

    if (finisher && p.mods.comboFinisherExplosion && epicenter) {
      this.comboExplosion(p, epicenter)
    }
  }

  /**
   * 가장 가까운 적 쪽으로 몸을 돌린다 (원본 `doAttack` 의 자동 조준).
   *
   * 조준 사거리는 근접 사거리보다 **넓다** (4.4 vs 3.6 기준) — 살짝 빗나간 위치에서도
   * 몸이 먼저 돌아가고, 그 다음 프레임에 맞는다. 이 여유가 조작을 관대하게 만든다.
   *
   * 🆕 mop(물걸레질)의 사거리 가산은 조준에도 같이 붙인다. 때릴 수 있는데 안 돌아보면
   * 늘어난 사거리가 실전에서 무의미해진다.
   *
   * ⚠️ 서버가 yaw 를 덮어쓴다. 클라이언트는 다음 스냅샷에서 이 값을 받아 아바타를 돌린다.
   */
  private autoAim(p: PlayerState): void {
    let best: MobState | null = null
    let bestD = Infinity
    for (const m of this.mobs) {
      if (m.dead) continue
      const def = mobDef(m.type as MobId)
      const range = autoAimRange(p.stats.reach + p.mods.attackRangeFlat, def.scale)
      const d = distXZ({ x: p.x, y: 0, z: p.z }, m.pos)
      if (d > range || d < 1e-6) continue
      if (d < bestD) {
        bestD = d
        best = m
      }
    }
    if (best) p.yaw = Math.atan2(best.pos.x - p.x, best.pos.z - p.z)
  }

  /**
   * 🆕 swordX(검성) — 3연타 마무리가 명중한 지점에서 광역이 한 번 터진다.
   *
   * 이 노드는 반경도 배수도 주지 않는다. 새 수치를 짓지 않기 위해 **검사 특수기(회전 베기)의
   * aoe 를 그대로 재사용한다** (`shared/skills/effects.ts` §3 swordX).
   * 콤보 배수는 다시 곱하지 않는다 — 마무리 타격이 이미 받았다.
   */
  private comboExplosion(p: PlayerState, at: Vec3): void {
    if (!p.classId) return
    for (const e of buildSpecial(p.classId, p.skills).effects) {
      if (e.kind !== 'aoe') continue
      this.aoeDamage(p, at, e.radius, p.stats.dmg * e.damageMul)
      return
    }
  }

  /** 🆕 splash · 🆕 bounce — 착지 광역. 피해는 배수가 아니라 고정값이다. */
  private landingAoe(p: PlayerState): void {
    const aoe = p.mods.landingAoe
    if (aoe === null) return
    this.aoeDamage(p, { x: p.x, y: 0, z: p.z }, aoe.radius, aoe.damage)
  }

  /**
   * 원형 광역 피해. 특수기 · 마무리 폭발 · 착지 광역이 전부 이걸 쓴다.
   *
   * ⚠️ 원본 `aoe()`(4457)는 반경에 몹 scale 을 더한다. 여기서는 기존 특수기 판정과 같게
   *    **더하지 않는다** — 세 경로가 서로 다른 판정을 쓰는 편이 더 나쁘다.
   *    (몹 scale 반영은 별건으로 올린다.)
   */
  /** 색을 주지 않는 경로(마무리 폭발·착지 광역)의 기본색. 흰색이면 지형에 묻힌다. */
  private static readonly AOE_DEFAULT_COLOR = 0xffd27f

  private aoeDamage(
    by: PlayerState,
    center: Vec3,
    radius: number,
    damage: number,
    color = Room.AOE_DEFAULT_COLOR,
  ): void {
    // 세 경로(특수기·마무리 폭발·착지)가 전부 여기를 지난다. 연출도 여기 한 곳에만 둔다 —
    // 호출부마다 따로 그리면 언젠가 하나가 빠지고, 그 기술만 "안 보이는 공격" 이 된다.
    this.emit({ k: 'aoe', x: center.x, z: center.z, radius, color, shape: 'burst' })
    for (const m of this.mobs) {
      if (m.dead) continue
      if (distXZ(center, m.pos) > radius) continue
      this.damageMob(m, damage, by)
    }
  }

  /** 특수기 적용은 `room/special-cast.ts` 가 한다 — 룸은 필요한 손발만 빌려준다. */
  private playerSpecial(p: PlayerState): void {
    applySpecialCast(p, {
      mobs: this.mobs,
      aoeDamage: (by, center, radius, damage, color) =>
        this.aoeDamage(by, center, radius, damage, color),
      damageMob: (m, base, by) => this.damageMob(m, base, by),
      spawnProjectile: (pr) => this.projectiles.push({ id: this.nextEntityId++, ...pr }),
      summon: (owner, at, count) =>
        this.minions.summon(owner, at, count, () => this.nextEntityId++),
      addField: (owner, f) => {
        this.fields.push({
          id: this.nextEntityId++,
          x: f.x,
          z: f.z,
          radius: f.radius,
          damagePerTick: f.damagePerTick,
          tickInterval: f.tickInterval,
          ownerId: owner.id,
          left: f.duration,
          // 첫 타격을 깔자마자 준다. 5초 장판이 0.5초 뒤에야 반응하면 "안 맞았다" 로 보인다.
          nextTick: 0,
        })
      },
      showArea: (a) => this.emit({ k: 'aoe', ...a }),
      toast: (text) => this.emit({ k: 'toast', text }),
    })
  }

  private stepFields(dt: number): void {
    stepFields(this.fields, dt, {
      players: this.players,
      mobs: this.mobs,
      damageMob: (m, base, by) => this.damageMob(m, base, by),
    })
  }

  private stepMobs(dt: number): void {
    for (const m of this.mobs) {
      const def = mobDef(m.type as MobId)
      const arch = this.archetypes.get(m.type)
      if (!arch) continue

      if (m.dead) {
        // 리스폰
        const next: MobState = { ...m, dieT: m.dieT + dt }
        Object.assign(m, next)
        if (m.dieT >= respawnSeconds(def)) {
          const zone = this.mobZone.get(m.id)
          if (zone) {
            const pt = randomPointInZone(zone, this.rng)
            const hp = this.scaledHp(m.type as MobId)
            Object.assign(m, {
              pos: { x: pt.x, y: def.fly ?? 0, z: pt.z },
              home: { x: pt.x, y: 0, z: pt.z },
              hp,
              maxHp: hp,
              dead: false,
              dieT: 0,
              roll: 0,
              boss: def.boss ? { phase: 0, cast: 0, skCd: 9, pulse: 0, invuln: false } : null,
            })
            this.mobMaxHp.set(m.id, hp)
            this.contribution.delete(m.id)
            // 부활한 몹이 중독·저주를 물고 나오면 안 된다.
            this.debuffs.clear(m.id)
          }
        }
        continue
      }

      const target = this.nearestPlayer(m)
      if (!target) continue

      const fearer = [...this.players.values()].find((p) => p.classId === 'boss' && !p.dead)
      const fromX = m.pos.x
      const fromZ = m.pos.z
      const result = stepMob(
        m,
        arch,
        {
          target: { pos: { x: target.x, y: target.y, z: target.z }, dead: target.dead },
          fear: fearer !== undefined && !arch.boss,
          dreadRank: fearer?.skills.dread ?? 0,
          castles: CASTLES.map((c) => ({ x: c.x, z: c.z, r: c.r })),
          rng: this.rng,
          elapsed: this.tick * TICK_S,
        },
        dt,
      )
      Object.assign(m, result.mob)
      this.applyCurseSlow(m, fromX, fromZ)

      for (const ev of result.events) this.handleMobEvent(m, ev, target)
    }
  }

  /**
   * 🆕 curse(저주)의 둔화 — `stepMob` 이 낸 이동량을 감속 비율만큼 되돌린다.
   *
   * ⚠️ `dread`(공포)는 `stepMob` 이 `ctx.dreadRank` 로 **이미** 처리했다. 저주는 여기서만,
   *    dread 는 저기서만 건다. 둘 다 `enemySlowPct` 한 필드에 합쳐져 있어서 같은 경로로
   *    넣으면 보스 직업의 dread 가 두 번 곱해진다.
   */
  private applyCurseSlow(m: MobState, fromX: number, fromZ: number): void {
    const slow = this.debuffs.slowOf(m.id)
    if (slow <= 0) return
    Object.assign(m, {
      pos: {
        x: fromX + (m.pos.x - fromX) * (1 - slow),
        y: m.pos.y,
        z: fromZ + (m.pos.z - fromZ) * (1 - slow),
      },
    })
  }

  private handleMobEvent(m: MobState, ev: MobEvent, target: PlayerState): void {
    // 🆕 herb(허브 향) — 몹이 파슬리의 오라 안에 있으면 공격력이 깎인다.
    const auraMul = mobAttackMul(this.players.values(), m.pos)

    switch (ev.kind) {
      case 'melee': {
        // 근접 강타는 사거리 안의 **모든** 플레이어가 아니라 대상 1명에게만 간다 (원본 동작).
        this.hitPlayer(target, ev.damage * auraMul, ev.slow, ev.burn)
        break
      }
      case 'projectile': {
        this.projectiles.push({
          id: this.nextEntityId++,
          x: ev.origin.x,
          y: ev.origin.y,
          z: ev.origin.z,
          dx: ev.dir.x,
          dz: ev.dir.z,
          speed: ev.speed,
          life: ev.life,
          // 오라는 **발사 시점**에 반영한다. 날아가는 동안 세기가 변하면 클라 연출과 어긋난다.
          damage: ev.damage * auraMul,
          burn: ev.burn,
          owner: -1,
          pierceLeft: 0,
          hit: new Set<string>(),
        })
        break
      }
      case 'shockwave': {
        // 충격파는 링 반경과의 차이로 판정한다 — 범위 안 전원이 한 번씩 맞는다.
        this.emit({ k: 'shockwave', x: ev.x, z: ev.z, radius: ev.maxRadius, bossId: m.type })
        for (const p of this.players.values()) {
          if (p.dead) continue
          const d = distXZ({ x: p.x, y: 0, z: p.z }, { x: ev.x, y: 0, z: ev.z })
          if (d <= ev.maxRadius) this.hitPlayer(p, ev.damage * auraMul, false, false)
        }
        break
      }
      case 'boss-phase-start': {
        // D-1 수정: bossSkillOf 는 미등록 보스에도 폴백을 돌려준다.
        // 가브리엘·조물주는 원본에서 이 지점에 아예 도달하지 못했다.
        const sk = bossSkillOf(m.type)
        const name = sk.name ?? `${mobDef(m.type as MobId).name} — 힘을 모은다`
        this.emit({ k: 'toast', text: name })
        break
      }
      default:
        break
    }
  }

  /** rite · 🆕 harvest · 🆕 necroX 로 불러낸 해골을 한 틱 굴린다. */
  private stepMinions(dt: number): void {
    if (this.minions.all.length === 0) return
    const targets: MinionTarget[] = this.mobs.map((m) => ({
      id: m.id,
      pos: m.pos,
      dead: m.dead,
      invuln: m.boss?.invuln === true,
    }))
    for (const hit of this.minions.step(dt, this.players, targets)) {
      const owner = this.players.get(hit.ownerId)
      const mob = this.mobIndex.get(hit.mobId)
      if (!owner || !mob || mob.dead) continue
      this.damageMob(mob, hit.amount, owner, 'indirect')
    }
  }

  /** 🆕 venom(맹독시)의 중독 틱. 주인이 방을 나갔으면 귀속 대상이 없으므로 건너뛴다. */
  private stepDebuffs(dt: number): void {
    for (const t of this.debuffs.step(dt)) {
      const mob = this.mobIndex.get(t.mobId)
      const owner = this.players.get(t.ownerId)
      if (!mob || mob.dead || !owner) continue
      this.damageMob(mob, t.amount, owner, 'indirect')
    }
  }

  /**
   * 투사체 1틱. 이동·명중 판정은 `room/world-objects.ts` 가 하고,
   * **피해·처치·기여도** 는 룸이 받는다 (게이트와 전리품이 거기 물려 있다).
   */
  private stepProjectiles(dt: number): void {
    stepProjectiles(this.projectiles, dt, {
      players: this.players,
      mobs: this.mobs,
      hitPlayer: (p, raw, slow, burn) => this.hitPlayer(p, raw, slow, burn),
      damageMob: (m, base, by) => this.damageMob(m, base, by),
      // 🆕 venom(맹독시) — "화살에" 라고 못박은 노드라 근접에는 붙이지 않는다.
      onArrowHit: (m, shooter) => {
        if (shooter.mods.poisonDps > 0) {
          this.debuffs.applyPoison(m.id, shooter.mods.poisonDps, shooter.id)
        }
      },
      onBlocked: () =>
        this.emit({ k: 'damage', targetId: 0, amount: 0, crit: false, isMob: true }),
    })
  }

  private stepCoins(dt: number): void {
    stepCoins(this.coins, dt, this.players)
  }

  private stepGateState(): void {
    const before = this.gates
    this.gates = stepGates(this.gates, this.tick)
    if (!before.heavenOpen && this.gates.heavenOpen) this.emit({ k: 'gateOpened' })
    if (before.cutscene.kind === 'none' && this.gates.cutscene.kind === 'playing') {
      this.emit({ k: 'cutsceneStart' })
    }
  }

  /* ────────────────────────── 전투 판정 ────────────────────────── */

  private classOf(p: PlayerState): ClassMods {
    return p.classId ? classModsOf(p.classId) : NO_CLASS
  }

  private damageMob(m: MobState, base: number, by: PlayerState, kind: HitKind = 'direct'): void {
    if (m.boss?.invuln) {
      // 무적 중 피해는 "무효" 로 표시하고 들어가지 않는다 (FR-3.6).
      this.emit({ k: 'damage', targetId: 0, amount: 0, crit: false, isMob: true })
      return
    }

    // 🆕 curse(저주) — 몹에 방어력 필드가 없어 "방어 −n%" 를 "받는 피해 +n%" 로 읽었다.
    //    근거는 `room/mob-debuffs.ts` 의 `Curse.damageTakenPct` 주석.
    const amped = base * this.debuffs.damageTakenMul(m.id)

    // 지속 피해·소환수 타격에는 크리를 굴리지 않는다 (원본 6329 는 그냥 `hp -= bd` 다).
    const roll =
      kind === 'direct'
        ? rollDamage(amped, by.stats, this.rng)
        : { damage: Math.max(1, Math.round(amped)), crit: false }

    const dealt = Math.min(m.hp, roll.damage)
    Object.assign(m, { hp: m.hp - roll.damage, hitT: 0 })

    this.emit({ k: 'damage', targetId: 0, amount: roll.damage, crit: roll.crit, isMob: true })

    // 흡혈은 직접 타격에만 붙는다 (원본 doAttack 5194).
    if (kind === 'direct' && by.stats.vamp > 0) {
      by.hp = Math.min(by.stats.maxHp, by.hp + dealt * by.stats.vamp)
    }

    if (kind === 'direct') this.applyOnHitDebuffs(m, by)

    // 보스 기여도 누적 — 전리품 분배 기준이다.
    const def = mobDef(m.type as MobId)
    if (def.boss) {
      let table = this.contribution.get(m.id)
      if (!table) {
        table = new Map()
        this.contribution.set(m.id, table)
      }
      table.set(by.id, (table.get(by.id) ?? 0) + dealt)
    }

    if (m.hp <= 0) this.killMob(m, by)
  }

  /**
   * 🆕 curse(저주) 부착 · 🆕 plague(역병) 전염.
   *
   * `enemyDefenseReductionPct` 는 **curse 만** 기여하는 필드다. `dread`(보스 직업)는 여기
   * 들어오지 않으므로, dread 가 저주로 둔갑해 이중 계상되는 일이 구조적으로 없다.
   * 그래서 이 분기 안에서는 `enemySlowPct` 전량을 저주의 둔화로 써도 안전하다.
   */
  private applyOnHitDebuffs(m: MobState, by: PlayerState): void {
    if (by.mods.enemyDefenseReductionPct <= 0) return
    this.debuffs.applyCurse(
      m.id,
      by.mods.enemyDefenseReductionPct,
      by.mods.enemySlowPct,
      by.mods.curseSpreadRadius > 0
        ? { radius: by.mods.curseSpreadRadius, from: m.pos, mobs: this.mobs }
        : null,
    )
  }

  /**
   * 처치 처리.
   *
   * ── 난수 소비 순서 (원본 killMob 5210–5212 기준) ──
   *   ① 골드량 ② 산포X ③ 산포Z   ← `rollCoinDrop`
   *   ④ 🆕 bonus(성과급) 2배 판정  ← 금액이 정해진 **직후**여야 한다
   *   ⑤ rite(강령술) 소환 판정
   *   ⑥ 🆕 harvest(영혼 수확) 즉시 소환 판정
   * 확률이 0 이면 난수를 **뽑지 않는다.** 스킬을 안 찍은 플레이어가 수열을 흔들면
   * 같은 시드의 두 방이 갈라진다.
   */
  private killMob(m: MobState, by: PlayerState): void {
    Object.assign(m, { hp: 0, dead: true, dieT: 0 })
    this.debuffs.clear(m.id)
    const def = mobDef(m.type as MobId)

    const drop = rollCoinDrop(def.gold, this.rng)
    let amount = drop.amount
    // 🆕 bonus(성과급) — 처치 시 8%/r 확률로 골드 2배.
    if (by.mods.goldDoubleChanceOnKill > 0 && this.rng() < by.mods.goldDoubleChanceOnKill) {
      amount *= 2
    }
    this.coins.push({
      id: this.nextEntityId++,
      x: m.pos.x + drop.offsetX,
      z: m.pos.z + drop.offsetZ,
      amount,
      life: COIN.LIFETIME,
    })
    this.emit({ k: 'mobDied', mobId: 0, x: m.pos.x, z: m.pos.z, gold: amount })

    // 처치 회복 — feast(포식)와 🆕 harvest(영혼 수확)가 같은 필드로 합쳐져 있다.
    if (by.mods.healOnKillFlat > 0 && !by.dead) {
      by.hp = Math.min(by.stats.maxHp, by.hp + by.mods.healOnKillFlat)
    }
    this.rollKillSummons(m.pos, by)

    // XP 는 처치자에게. 협동에서는 근처 전원에게 주는 편이 자연스러워 AoI 안 전원에게 준다.
    for (const p of this.players.values()) {
      if (p.dead) continue
      if (distXZ({ x: p.x, y: 0, z: p.z }, m.pos) > AOI_RADIUS) continue
      const r = grantXp(p, def.xp)
      for (const lv of r.leveled) this.emit({ k: 'levelUp', playerId: p.id, level: lv })
    }

    if (!def.boss) return

    // ── 보스 ──
    const unlock = def.unlock
    const table = this.contribution.get(m.id)
    const threshold = (this.mobMaxHp.get(m.id) ?? def.hp) * LOOT_CONTRIBUTION
    const earners: number[] = []
    for (const p of this.players.values()) {
      const dealt = table?.get(p.id) ?? 0
      if (dealt < threshold && p.id !== by.id) continue
      earners.push(p.id)
      if (unlock && grantWeapon(p, unlock)) {
        /* 지급됨 */
      }
    }
    if (unlock) this.emit({ k: 'loot', weaponId: unlock, to: earners })
    this.emit({ k: 'bossKilled', bossId: m.type, by: earners })

    // 진행 게이트
    const gateId = m.type as GateBossId
    const before = this.gates
    this.gates = onBossKilled(this.gates, gateId, this.tick)
    if (this.gates !== before) {
      if (this.gates.lordsKilled.length !== before.lordsKilled.length) {
        this.emit({
          k: 'runeLit',
          lordId: m.type,
          count: this.gates.lordsKilled.length as 1 | 2 | 3,
        })
      }
      if (!before.innerOpen && this.gates.innerOpen) this.emit({ k: 'sealBroken' })
    }
  }

  /**
   * 처치 소환 판정 2종.
   *
   * · rite(강령술) — 네크로 전용. `CLS.raise + rite×0.15` (원본 5212).
   *   `rollRaiseSkeleton` 은 raise 가 0 이면 난수를 뽑지 않고 false 를 준다.
   * · 🆕 harvest(영혼 수확) — "해골 즉시 소환 10%/r". rite 와 **별개의** 판정이다.
   *   같은 처치에서 둘 다 터지면 두 체가 나온다 (상한을 넘으면 조용히 무시된다 — 원본 4445).
   */
  private rollKillSummons(at: Vec3, by: PlayerState): void {
    const spot = { x: at.x, z: at.z }
    if (rollRaiseSkeleton(this.classOf(by), by.skills, this.rng)) {
      this.minions.summon(by, spot, 1, () => this.nextEntityId++)
    }
    if (by.mods.summonOnKillChancePct > 0 && this.rng() < by.mods.summonOnKillChancePct) {
      this.minions.summon(by, spot, 1, () => this.nextEntityId++)
    }
  }

  private hitPlayer(p: PlayerState, raw: number, slow: boolean, burn: boolean): void {
    const before = p.dead
    // 🆕 bulwark(불굴)는 `hurtPlayer` 안에서 guard 에 곱으로 얹힌다.
    const r = hurtPlayer(p, raw, this.rng)
    if (r.applied > 0) {
      this.emit({ k: 'damage', targetId: p.id, amount: r.applied, crit: false, isMob: false })
      if (slow) p.slowT = Math.max(p.slowT, 2.5)
      if (burn) p.burnT = Math.max(p.burnT, 3)
    }
    if (!before && r.died) this.emit({ k: 'playerDied', playerId: p.id })
  }

  /** 몹이 노릴 대상 — 가장 가까운 생존 플레이어. 아무도 없으면 null. */
  private nearestPlayer(m: MobState): PlayerState | null {
    let best: PlayerState | null = null
    let bestD = Infinity
    for (const p of this.players.values()) {
      if (p.dead) continue
      if (!sameRegionGroup(regionOf({ x: p.x, z: p.z }), regionOf({ x: m.pos.x, z: m.pos.z }))) continue
      const d = distXZ({ x: p.x, y: 0, z: p.z }, m.pos)
      if (d < bestD) {
        bestD = d
        best = p
      }
    }
    return best
  }

  respawn(playerId: number): void {
    const p = this.players.get(playerId)
    if (p?.dead) respawnPlayer(p)
  }

  private emit(ev: GameEvent): void {
    this.pending.push(ev)
  }

  /* ────────────────────────── 스냅샷 ────────────────────────── */

  /**
   * 한 플레이어에게 보낼 스냅샷.
   * 조립은 `room/snapshot.ts` 가 한다 — 이 파일은 판정만 산다.
   */
  snapshotFor(playerId: number): Extract<ServerMsg, { t: 'snapshot' }> | null {
    return buildSnapshot(this, playerId)
  }

  /** 저장된 진행 상태를 복원한다 (룸 재생성 시). */
  restoreGates(save: Parameters<typeof deserializeGates>[0]): void {
    this.gates = deserializeGates(save)
  }
}

/* 위 클래스가 참조만 하고 값으로는 안 쓰는 상수들 — import 목록에서 지우면
   "왜 이 파일이 그 상수를 모르는가" 를 다시 조사하게 된다. 의도적으로 남긴다. */
void BOSS_PHASE_GATES
void HEAVEN_LEASH
