/** 몹 이동·전투 상수. 전부 원본 그대로다. */
export const MOB_AI = {
  /** 배회 방향 재추첨 주기: 1.5 + rng×2.5 초 */
  wanderMinT: 1.5,
  wanderSpanT: 2.5,
  /** 재추첨 직후 1.2초는 서 있는다 (wt > 1.2 인 동안만 이동) */
  wanderMoveAboveT: 1.2,
  wanderSpeedMul: 0.32,
  /** 공포(fear): 최종보스 직업 앞에서 일반몹이 도주하는 속도 배율 */
  fearSpeedMul: 1.15,
  /** 스킬 `dread`(공포) 랭크당 적 이동속도 감소 */
  dreadSlowPerRank: 0.12,
  /** 근접 몹이 붙으려는 거리: reach + 0.9 */
  meleeRangePad: 0.9,
  /** 원거리 몹이 붙으려는 거리: reach × 0.6 */
  rangedRangeMul: 0.6,
  faceTurnRate: 8,
  wanderTurnRate: 4,
  fearWalkRate: 14,
  walkRate: 10,
  walkSpeedRef: 4.5,
  collideRadiusMul: 0.8,
  /** 잡몹을 성 밖으로 밀 때의 여유: scale × 1.5 */
  castlePushMul: 1.5,
  meleeSwingDur: 0.62,
  worldSwingDur: 0.95,
  rangedSwingDur: 0.7,
  /** 근접 피해 난수 폭: dmg × (0.85 + rng×0.3) */
  damageVarianceMin: 0.85,
  damageVarianceSpan: 0.3,
  /* 아래 4개는 entities/mobs 원장의 값을 그대로 참조한다 — 같은 수치를 두 번 적지 않는다. */
  slowDuration: SLOW_DURATION_S,
  burnDuration: BURN_DURATION_S,
  /** 피격 후 이 시간이 지나야 regen 이 돈다 */
  regenAfterHitT: 3,
  respawnDelayMob: RESPAWN_S_MOB,
  respawnDelayBoss: RESPAWN_S_BOSS,
  deathSinkFly: 2.2,
  deathSinkGround: 0.6,
  deathSinkMin: -3.5,
  deathRollRate: 6,
  projectileSpeedBoss: 26,
  projectileSpeedMob: 20,
  projectileLife: 3.2,
} as const

/** 천국 보스 봉인: home.z 가 이 값보다 작으면 홈 반경 34 안에 묶인다 */
export const HEAVEN_HOME_Z = -252
export const HEAVEN_LEASH = 34
/** 보스는 자기 성 안(r − 5)을 벗어나지 못한다 */
export const CASTLE_BOSS_INSET = 5
/** 보스 홈이 어느 성에 속하는지 볼 때 쓰는 여유 */
export const CASTLE_HOME_PAD = 6


/* ══════════════ 순수 헬퍼 ══════════════ */

/** 원본 findCastleAt(x, z, pad) — 겹치는 첫 성을 돌려준다. */
export function findCastleAt(
  castles: readonly CastleRef[],
  x: number,
  z: number,
  pad = 0,
): CastleRef | null {
  for (const c of castles) {
    if (Math.hypot(x - c.x, z - c.z) < c.r + pad) return c
  }
  return null
}

/**
 * 공격 진행도 곡선. −0.4(예고: 뒤로 당김) → 1(강타) → 0(회복).
 * 원본 atkCurve(3043). 회피 타이밍의 근거이므로 코어에 둔다.
 */
export function atkCurve(atkT: number, atkD: number): number {
  if (atkT <= 0) return 0
  const dur = atkD || MOB_AI.meleeSwingDur
  const q = 1 - atkT / dur
  if (q < 0.42) return -0.4 * Math.sin((q / 0.42) * 1.5708)
  if (q < 0.62) return -0.4 + 1.4 * Math.pow((q - 0.42) / 0.2, 0.5)
  return 1.0 - Math.pow((q - 0.62) / 0.38, 1.5)
}

/* ══════════════ 몹 1틱 ══════════════ */

/**
 * 원본 tick() 의 mobs.forEach 본문(6149–6256).
 * 입력 MobState 를 변형하지 않고 새 상태를 돌려준다.
 */
export function stepMob(
  mob: MobState,
  arch: MobArchetype,
  ctx: MobStepCtx,
  dt: number,
): MobStepResult {
  const ph = arch.fly

  /* ── 사망 · 리스폰 ── */
  if (mob.dead) {
    const dieT = mob.dieT + dt
    const roll = Math.min(Math.PI / 2, mob.roll + dt * MOB_AI.deathRollRate)
    const sink = ph ? MOB_AI.deathSinkFly : MOB_AI.deathSinkGround
    const y = Math.max(MOB_AI.deathSinkMin, mob.pos.y - dt * sink)
    const limit = arch.boss ? MOB_AI.respawnDelayBoss : MOB_AI.respawnDelayMob
    if (dieT > limit) {
      const a = ctx.rng() * Math.PI * 2
      const r = ctx.rng() * mob.zone.r
      const pos: Vec3 = {
        x: mob.zone.x + Math.cos(a) * r,
        y: ph,
        z: mob.zone.z + Math.sin(a) * r,
      }
      return {
        mob: {
          ...mob,
          pos,
          yaw: 0,
          roll: 0,
          hp: mob.maxHp,
          dead: false,
          dieT: 0,
          cd: 0,
          // 원본은 리스폰 시 phase 를 초기화하지 않는다 (killMob 5206 · 리스폰 6155 둘 다 손대지 않는다).
          // 결과: 한 번 잡은 월드보스는 재전투에서 무적 페이즈가 두 번 다시 발동하지 않는다.
          // 아래 메모 5번 참조. 승인 나면 `initialBossState()` 로 바꾸면 된다.
          boss: mob.boss,
        },
        events: [{ kind: 'respawn', mobId: mob.id, pos }],
      }
    }
    return { mob: { ...mob, dieT, roll, pos: { ...mob.pos, y } }, events: [] }
  }

  const events: MobEvent[] = []
  let cd = mob.cd - dt
  const hitT = mob.hitT + dt
  let hp = mob.hp
  if (arch.regen && hitT > MOB_AI.regenAfterHitT) {
    hp = Math.min(mob.maxHp, hp + arch.regen * dt)
  }

  let x = mob.pos.x
  let z = mob.pos.z
  let yaw = mob.yaw
  let atkT = mob.atkT
  let atkD = mob.atkD
  let wander = mob.wander
  let wt = mob.wt
  /** 보행 애니메이션 강도 (0 정지 · 0.6 배회 · 1 추격) */
  let mv = 0

  const dx = ctx.target.pos.x - x
  const dz = ctx.target.pos.z - z
  const dist = Math.hypot(dx, dz)

  const applyCollide = (px: number, pz: number, y: number): { x: number; z: number } => {
    if (arch.ghost || !ctx.collide) return { x: px, z: pz }
    const c = ctx.collide({ x: px, y, z: pz }, MOB_AI.collideRadiusMul * arch.scale)
    return { x: c.x, z: c.z }
  }

  if (!ctx.target.dead && dist < arch.aggro) {
    /* ── 공포: 최종보스 직업 앞에서 일반몹은 도주한다 ── */
    if (ctx.fear && !arch.boss) {
      const step = arch.speed * MOB_AI.fearSpeedMul * dt
      const nx = x - (dx / dist) * step
      const nz = z - (dz / dist) * step
      const c = applyCollide(nx, nz, mob.pos.y)
      x = c.x
      z = c.z
      yaw = Math.atan2(-dx, -dz)
      const walk = mob.walk + dt * MOB_AI.fearWalkRate
      const y =
        ph +
        (arch.hop
          ? Math.abs(Math.sin(ctx.elapsed * 4 + walk)) * 0.18
          : ph
            ? Math.sin(ctx.elapsed * 2 + mob.bob) * 0.25
            : 0)
      // 원본은 이 지점에서 forEach 를 return 한다 — 성 경계 보정과 bossTick 을 건너뛴다.
      // 관찰: 도주 중인 잡몹은 성 안으로 들어갈 수 있다. 원본 동작을 그대로 유지했다.
      return {
        mob: {
          ...mob,
          pos: { x, y, z },
          yaw,
          hp,
          hitT,
          cd,
          walk,
          atkT: atkT > 0 ? atkT - dt : atkT,
        },
        events,
      }
    }

    /* ── 추격 ── */
    yaw = yaw + angleDelta(yaw, Math.atan2(dx, dz)) * Math.min(1, dt * MOB_AI.faceTurnRate)

    const wantRange = arch.ranged
      ? arch.reach * MOB_AI.rangedRangeMul
      : arch.reach + MOB_AI.meleeRangePad

    if (dist > wantRange) {
      const step = arch.speed * (1 - ctx.dreadRank * MOB_AI.dreadSlowPerRank) * dt
      const c = applyCollide(x + (dx / dist) * step, z + (dz / dist) * step, mob.pos.y)
      x = c.x
      z = c.z
      mv = 1
    } else if (arch.ranged && dist < arch.reach && cd <= 0) {
      cd = arch.cd
      atkT = atkD = MOB_AI.rangedSwingDur
      events.push({ kind: 'swing', mobId: mob.id, duration: MOB_AI.rangedSwingDur })
      events.push({
        kind: 'projectile',
        mobId: mob.id,
        origin: { x, y: (arch.boss ? 5.4 : 3.4) * arch.scale + ph, z },
        dir: { x: dx / dist, y: 0, z: dz / dist },
        damage: arch.dmg,
        burn: arch.burn,
        speed: arch.boss ? MOB_AI.projectileSpeedBoss : MOB_AI.projectileSpeedMob,
        life: MOB_AI.projectileLife,
      })
    } else if (!arch.ranged && cd <= 0) {
      cd = arch.cd
      const dur = arch.world ? MOB_AI.worldSwingDur : MOB_AI.meleeSwingDur
      atkT = atkD = dur
      events.push({ kind: 'swing', mobId: mob.id, duration: dur })
      const variance = MOB_AI.damageVarianceMin + ctx.rng() * MOB_AI.damageVarianceSpan
      events.push({
        kind: 'melee',
        mobId: mob.id,
        damage: Math.round(arch.dmg * variance),
        slow: arch.slow,
        burn: arch.burn,
      })
    }
  } else {
    /* ── 배회 ── */
    wt -= dt
    if (wt <= 0) {
      wt = MOB_AI.wanderMinT + ctx.rng() * MOB_AI.wanderSpanT
      wander = ctx.rng() * Math.PI * 2
    }
    const hx = mob.home.x - x
    const hz = mob.home.z - z
    // 홈 반경(zone.r) 밖으로 나가면 홈 방향으로 되돌아온다
    if (Math.hypot(hx, hz) > mob.zone.r) wander = Math.atan2(hx, hz)
    if (wt > MOB_AI.wanderMoveAboveT) {
      const step = arch.speed * MOB_AI.wanderSpeedMul * dt
      const c = applyCollide(x + Math.sin(wander) * step, z + Math.cos(wander) * step, mob.pos.y)
      x = c.x
      z = c.z
      yaw = yaw + (wander - yaw) * Math.min(1, dt * MOB_AI.wanderTurnRate)
      mv = 0.6
    }
  }

  /* ── 성 경계 ── */
  if (arch.world) {
    // 천국 보스 — 봉인 너머로 넘어가지 않게 홈 반경 34 로 묶는다
    if (mob.home.z < HEAVEN_HOME_Z) {
      const ox = x - mob.home.x
      const oz = z - mob.home.z
      const dd = Math.hypot(ox, oz)
      if (dd > HEAVEN_LEASH) {
        x = mob.home.x + (ox / dd) * HEAVEN_LEASH
        z = mob.home.z + (oz / dd) * HEAVEN_LEASH
      }
    }
    // 보스는 자기 성 안(r − 5)에 갇힌다
    const home = findCastleAt(ctx.castles, mob.home.x, mob.home.z, CASTLE_HOME_PAD)
    if (home) {
      const d2 = Math.hypot(x - home.x, z - home.z)
      const lim = home.r - CASTLE_BOSS_INSET
      if (d2 > lim) {
        const a2 = Math.atan2(z - home.z, x - home.x)
        x = home.x + Math.cos(a2) * lim
        z = home.z + Math.sin(a2) * lim
      }
    }
  } else {
    // 잡몹은 성 밖으로 밀린다
    const pad = MOB_AI.castlePushMul * arch.scale
    const ct = findCastleAt(ctx.castles, x, z, pad)
    if (ct) {
      const a2 = Math.atan2(z - ct.z, x - ct.x)
      x = ct.x + Math.cos(a2) * (ct.r + pad)
      z = ct.z + Math.sin(a2) * (ct.r + pad)
    }
  }

  const walk = mob.walk + dt * MOB_AI.walkRate * mv * (arch.speed / MOB_AI.walkSpeedRef)
  if (atkT > 0) atkT -= dt

  // 상하 흔들림 (hop / fly). atkT 가 도는 동안은 공격 모션이 y 를 잡는다.
  let y = mob.pos.y
  if (arch.hop && atkT <= 0) y = Math.abs(Math.sin(ctx.elapsed * 4 + walk)) * 0.18 * (mv || 0.3)
  else if (ph && atkT <= 0) y = ph + Math.sin(ctx.elapsed * 1.8 + mob.bob) * 0.3

  const moved: MobState = {
    ...mob,
    pos: { x, y, z },
    yaw,
    hp,
    hitT,
    cd,
    walk,
    atkT,
    atkD,
    wander,
    wt,
  }

  /* ── 월드보스 페이즈 ── */
  if (arch.world) {
    const d = Math.hypot(x - ctx.target.pos.x, z - ctx.target.pos.z)
    const r = stepBossPhase(moved, arch, dt, d, ctx.rng)
    return { mob: r.mob, events: [...events, ...r.events] }
  }

  return { mob: moved, events }
}

/** 몹이 지금 무적인지 (방벽 페이즈). 피해 판정 앞에서 확인한다. */
export function isMobInvulnerable(mob: MobState): boolean {
  return mob.boss?.invuln === true
}

/* ══════════════ 원본 대조 메모 ══════════════
 *
 * 1. docs/02-GAME-SPEC.md §7.4 / §7.5 와 원본 수치는 **전부 일치**한다.
 *    (어그로/배회/공포/성 경계/리스폰, 페이즈 4.2초·0.9초·30·0.55·34·0.9·9~13초·24·0.6·46·2.2)
 *
 * 2. docs 에 없는 원본 사실 두 가지 — 원장(02-GAME-SPEC §7.4)에 추가 필요:
 *    (a) 추격 이동속도에 스킬 `dread`(공포) 랭크당 −12% 가 곱해진다 (원본 6190).
 *        docs §7.4 의 추격 항목에는 이 계수가 빠져 있다.
 *    (b) 공격 모션 길이가 상황별로 다르다 — 근접 0.62 / 월드보스 근접 0.95 / 원거리 0.7 /
 *        페이즈 충격파 0.8. docs 는 이 값을 다루지 않는다.
 *
 * 3. 결함 D-1 (BOSS_SKILL 미등록 보스의 페이즈 미발동) 은 여기서 구조적으로 수정했다.
 *    원본 `if(!sk) return;` → `bossSkillOf()` 폴백. 수치는 하나도 바꾸지 않았고,
 *    가브리엘·조물주는 월드보스 공통 페이즈를 그대로 쓴다 (전용 패턴은 위 TODO 참조).
 *
 * 4. 원본 보존한 이상 동작 (고치지 않음, 승인 대상):
 *    공포 도주 분기가 성 경계 보정과 bossTick 앞에서 return 한다 → 도주 중 잡몹이 성 안으로
 *    들어갈 수 있다. 원본 6180 그대로다.
 *
 * 5. 신규 발견 결함 (관찰) — 요건 문서에 아직 없다:
 *    리스폰이 보스 페이즈 상태를 초기화하지 않는다. `killMob`(원본 5206) 도, 리스폰 블록
 *    (원본 6155–6161) 도 `m.phase / m.cast / m.invuln` 을 건드리지 않는다.
 *    재현: 월드보스를 잡고 24초 뒤 부활시켜 다시 싸운다 → HP 70%·40% 를 지나도 무적 페이즈가
 *    한 번도 발동하지 않는다 (phase 가 2 로 남아 gate 가 0 이 된다).
 *    판단: 재전투 난이도가 첫 전투보다 크게 낮아진다. 위 리스폰 코드의 주석 참조.
 *    (수치 변경이 아니라 상태 초기화 문제이므로 D-1 과 별건으로 올린다.)
 */
