/**
 * 게임 패널 — 직업 선택 · 스킬 트리 · 무기 상점 · 설정 · 일시정지.
 *
 * 패널은 **표시와 의사 전달만** 한다. 실제 반영은 서버가 한다 —
 * "스킬을 배웠다" 는 서버 스냅샷이 돌아와야 확정된다.
 * 낙관적 갱신을 하지 않는 이유: 골드·SP 를 클라가 먼저 깎으면 거절당했을 때 화면이 거짓말을 한다.
 */

import {
  CLASSES,
  CLASS_IDS,
  SKILL_TREE,
  TIER_LABELS,
  WEAPONS,
  WEAPON_IDS,
} from '@bq/shared'
import type { ClassId, SkillNode, WeaponId } from '@bq/shared'
import { button, card, grid } from './panels'
import type { PanelSpec } from './panels'
import type { InputSettings } from '../input/state'

export interface PlayerView {
  readonly level: number
  readonly gold: number
  readonly sp: number
  readonly classId: ClassId | null
  readonly weaponId: string
  readonly owned: readonly string[]
  readonly skills: Readonly<Record<string, number>>
}

export interface PanelActions {
  respawn(): void
  pickClass(id: ClassId): void
  learnSkill(nodeId: string): void
  respec(): void
  buyWeapon(id: WeaponId): void
  equipWeapon(id: WeaponId): void
  toggleFullscreen(): void
  leaveRoom(): void
  copyRoomCode(): void
}

/* ────────────────────────── 직업 선택 ────────────────────────── */

/**
 * Lv 5 에 강제로 열린다 (FR-1.4). 그때는 `modal: true` 라 ESC 로 못 닫는다 —
 * 직업 선택이 곧 정체성 선언이라는 원작의 구조를 지킨다.
 */
export function classPanel(
  view: () => PlayerView,
  act: PanelActions,
  forced: boolean,
): PanelSpec {
  return {
    id: 'class',
    title: forced ? '직업을 고르자' : '직업 변경',
    ...(forced ? { modal: true as const } : {}),
    render(body, close) {
      const v = view()
      const cards = CLASS_IDS.map((id) => {
        const c = CLASSES[id]
        return card({
          title: `${c.icon} ${c.name}`,
          desc: c.desc,
          stats: c.stats,
          selected: v.classId === id,
          onClick: () => {
            act.pickClass(id)
            close()
          },
        })
      })
      body.appendChild(grid(cards))

      if (v.classId) {
        const note = document.createElement('p')
        note.style.cssText = 'margin-top:14px;font-size:12px;opacity:.7'
        note.textContent = '직업을 바꾸면 이전 직업 전용 스킬 포인트는 전액 돌려받는다.'
        body.appendChild(note)
      }
    },
  }
}

/* ────────────────────────── 스킬 트리 ────────────────────────── */

const NODE_W = 118
const NODE_H = 76
const COL_GAP = 26
const ROW_GAP = 46

export function skillPanel(view: () => PlayerView, act: PanelActions): PanelSpec {
  return {
    id: 'tree',
    title: '스킬 트리',
    render(body) {
      const draw = (): void => {
        const v = view()
        body.replaceChildren()

        const head = document.createElement('div')
        head.style.cssText = 'display:flex;gap:10px;align-items:center;margin-bottom:12px'
        const sp = document.createElement('span')
        sp.className = 'badge'
        sp.textContent = `남은 SP ${v.sp}`
        head.appendChild(sp)
        head.appendChild(
          button('전체 초기화', () => {
            act.respec()
            setTimeout(draw, 120)
          }),
        )
        body.appendChild(head)

        const visible = SKILL_TREE.filter(
          (n) => n.classId === null || n.classId === v.classId,
        )
        const byTier = TIER_LABELS.map((t) => visible.filter((n) => n.tier === t))

        const wrap = document.createElement('div')
        wrap.className = 'tree-wrap'
        const maxCols = Math.max(...byTier.map((r) => r.length), 1)
        wrap.style.width = `${maxCols * (NODE_W + COL_GAP)}px`
        wrap.style.height = `${TIER_LABELS.length * (NODE_H + ROW_GAP) + 20}px`

        const pos = new Map<string, { x: number; y: number }>()
        byTier.forEach((row, ti) => {
          row.forEach((node, ci) => {
            pos.set(node.id, {
              x: ci * (NODE_W + COL_GAP),
              y: ti * (NODE_H + ROW_GAP) + 20,
            })
          })
        })

        // 연결선 — 원본의 베지어 곡선을 유지한다.
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
        svg.setAttribute('width', String(wrap.style.width ? parseInt(wrap.style.width) : 0))
        svg.setAttribute('height', String(parseInt(wrap.style.height)))
        for (const node of visible) {
          if (!node.req) continue
          const from = pos.get(node.req[0])
          const to = pos.get(node.id)
          if (!from || !to) continue
          const x1 = from.x + NODE_W / 2
          const y1 = from.y + NODE_H
          const x2 = to.x + NODE_W / 2
          const y2 = to.y
          const path = document.createElementNS('http://www.w3.org/2000/svg', 'path')
          path.setAttribute(
            'd',
            `M${x1},${y1} C${x1},${(y1 + y2) / 2} ${x2},${(y1 + y2) / 2} ${x2},${y2}`,
          )
          const met = (v.skills[node.req[0]] ?? 0) >= node.req[1]
          path.setAttribute('stroke', met ? 'rgba(255,212,121,.6)' : 'rgba(150,200,255,.22)')
          path.setAttribute('stroke-width', '2')
          path.setAttribute('fill', 'none')
          svg.appendChild(path)
        }
        wrap.appendChild(svg)

        for (const node of visible) {
          const p = pos.get(node.id)
          if (!p) continue
          wrap.appendChild(nodeButton(node, v, p, act, draw))
        }

        TIER_LABELS.forEach((label, ti) => {
          const el = document.createElement('div')
          el.className = 'tier-label'
          el.style.cssText = `position:absolute;left:-2px;top:${ti * (NODE_H + ROW_GAP)}px`
          el.textContent = label
          wrap.appendChild(el)
        })

        body.appendChild(wrap)

        if (!v.classId) {
          const note = document.createElement('p')
          note.style.cssText = 'margin-top:16px;font-size:12px;opacity:.7'
          note.textContent = '직업을 고르면 전용 스킬 7개가 더 열린다.'
          body.appendChild(note)
        }
      }
      draw()
    },
  }
}

function nodeButton(
  node: SkillNode,
  v: PlayerView,
  p: { x: number; y: number },
  act: PanelActions,
  redraw: () => void,
): HTMLElement {
  const rank = v.skills[node.id] ?? 0
  const reqMet = !node.req || (v.skills[node.req[0]] ?? 0) >= node.req[1]
  const classMet = node.classId === null && !node.requiresAnyClass ? true : v.classId !== null
  const maxed = rank >= node.max
  const canBuy = reqMet && classMet && !maxed && v.sp > 0

  const el = document.createElement('button')
  el.className =
    'node' + (canBuy ? '' : ' locked') + (maxed ? ' maxed' : '') + (node.cap ? ' cap' : '')
  el.style.cssText = `left:${p.x}px;top:${p.y}px;position:absolute`
  el.type = 'button'
  el.title = node.desc

  const name = document.createElement('b')
  name.textContent = `${node.icon} ${node.name}`
  const rankEl = document.createElement('div')
  rankEl.className = 'rank'
  rankEl.textContent = `${rank} / ${node.max}`
  const desc = document.createElement('div')
  desc.className = 'desc'
  desc.textContent = describeEffect(node, Math.max(1, rank))

  el.append(name, rankEl, desc)
  if (canBuy) {
    el.addEventListener('click', () => {
      act.learnSkill(node.id)
      setTimeout(redraw, 120)
    })
  }
  return el
}

/**
 * 설명 문구를 **효과 데이터에서** 만든다.
 *
 * 원본의 `desc` 템플릿을 그대로 쓰지 않는 이유: 원본에서 설명과 실제 동작이 어긋난 노드가
 * 20개 있었다 (D-2). 표시를 효과에서 파생시키면 그 불일치가 구조적으로 불가능해진다.
 */
function describeEffect(node: SkillNode, rank: number): string {
  const e = node.effect
  const pct = (v: number): string => `${Math.round(v * rank * 1000) / 10}%`
  switch (e.kind) {
    case 'maxHpFlat':
      return `최대 HP +${e.perRank * rank}`
    case 'attackFlat':
      return `공격력 +${e.perRank * rank}`
    case 'attackPct':
    case 'allDamagePct':
      return `공격력 +${pct(e.perRank)}`
    case 'moveSpeedPct':
      return `이동속도 +${pct(e.perRank)}`
    case 'critChancePct':
      return `크리 확률 +${pct(e.perRank)}`
    case 'critDamagePct':
      return `크리 피해 +${pct(e.perRank)}`
    case 'attackSpeedPct':
      return `공격속도 +${pct(e.perRank)}`
    case 'goldGainPct':
      return `골드 +${pct(e.perRank)}`
    case 'xpGainPct':
      return `경험치 +${pct(e.perRank)}`
    case 'damageReductionPct':
      return `받는 피해 −${pct(e.perRank)}`
    case 'damageReductionBelowHpPct':
      return `HP ${Math.round(e.hpThreshold * 100)}% 이하일 때 피해 −${pct(e.perRank)}`
    case 'lifestealPct':
      return `준 피해의 ${pct(e.perRank)} 회복`
    case 'hpRegenPerSec':
      return `초당 HP +${Math.round(e.perRank * rank * 10) / 10}`
    case 'evadeChancePct':
      return `회피 +${pct(e.perRank)}`
    case 'allStatsPct':
      return `모든 능력치 +${pct(e.perRank)}`
    default:
      // 그 외는 원문 설명을 쓰되 템플릿 자리표시자만 랭크로 바꾼다.
      return node.desc.replace(/\$\{([^}]*)\}/g, (_, expr: string) =>
        evalRankExpr(expr, rank) ?? '?',
      )
  }
}

/**
 * 원본 설명 템플릿의 자리표시자를 푼다.
 *
 * `new Function` 을 쓰지 않는다 — 문자열을 코드로 실행하는 통로를 열어 둘 이유가 없고,
 * 엄격한 CSP 아래에서는 아예 동작하지 않는다.
 * 원본에 실제로 등장하는 형태는 아래 네 가지뿐이라 작은 파서로 충분하다:
 *   `r` · `12*r` · `(0.3*r).toFixed(1)` · `(1+0.5*r).toFixed(1)` · `(2+r).toFixed(0)`
 */
function evalRankExpr(expr: string, rank: number): string | null {
  const src = expr.trim()

  const toFixed = /^\((.+)\)\.toFixed\((\d+)\)$/.exec(src)
  if (toFixed) {
    const inner = evalArith(toFixed[1] ?? '', rank)
    const digits = Number(toFixed[2] ?? 0)
    return inner === null ? null : inner.toFixed(digits)
  }

  const v = evalArith(src, rank)
  return v === null ? null : String(v)
}

/** `a`, `r`, `a*r`, `a+r`, `a+b*r` 만 푼다. 그 밖의 형태는 null 이다. */
function evalArith(src: string, rank: number): number | null {
  const s = src.replace(/\s+/g, '')
  if (s === 'r') return rank

  const mul = /^(-?[\d.]+)\*r$/.exec(s)
  if (mul) return Number(mul[1]) * rank

  const addR = /^(-?[\d.]+)\+r$/.exec(s)
  if (addR) return Number(addR[1]) + rank

  const addMul = /^(-?[\d.]+)\+(-?[\d.]+)\*r$/.exec(s)
  if (addMul) return Number(addMul[1]) + Number(addMul[2]) * rank

  const num = Number(s)
  return Number.isFinite(num) ? num : null
}

/* ────────────────────────── 무기 상점 ────────────────────────── */

export function shopPanel(view: () => PlayerView, act: PanelActions): PanelSpec {
  return {
    id: 'shop',
    title: '🗡 무기점',
    render(body) {
      const draw = (): void => {
        const v = view()
        body.replaceChildren()

        const head = document.createElement('div')
        head.style.cssText = 'margin-bottom:12px'
        const g = document.createElement('span')
        g.className = 'badge badge-gold'
        g.textContent = `${v.gold.toLocaleString('ko-KR')} G`
        head.appendChild(g)
        body.appendChild(head)

        const cards = WEAPON_IDS.map((id) => {
          const w = WEAPONS[id]
          const owned = v.owned.includes(id)
          const equipped = v.weaponId === id
          const bossLocked = w.unlock.kind !== 'shop' && !owned
          const tooPoor = !owned && !bossLocked && v.gold < w.price

          return card({
            title: w.name,
            desc: w.desc,
            stats: weaponStats(id),
            price: bossLocked
              ? '보스 처치로 해금'
              : owned
                ? equipped
                  ? '장착 중'
                  : '보유 중 — 눌러서 장착'
                : `${w.price.toLocaleString('ko-KR')} G`,
            selected: equipped,
            disabled: bossLocked || tooPoor,
            onClick: () => {
              if (owned) act.equipWeapon(id)
              else act.buyWeapon(id)
              setTimeout(draw, 120)
            },
          })
        })
        body.appendChild(grid(cards))
      }
      draw()
    },
  }
}

function weaponStats(id: WeaponId): string {
  const w = WEAPONS[id]
  const parts: string[] = []
  if (w.dmg) parts.push(`공격 +${w.dmg}`)
  if (w.crit) parts.push(`크리 +${Math.round(w.crit * 100)}%`)
  // atkSpeed 는 쿨다운 **가산치**다. 음수가 빨라지는 쪽이라 표기 부호가 뒤집힌다.
  if (w.atkSpeed) {
    parts.push(`공속 ${w.atkSpeed < 0 ? '+' : '−'}${Math.abs(Math.round(w.atkSpeed * 100))}%`)
  }
  if (w.reach) parts.push(`사거리 +${w.reach}`)
  if (w.gold) parts.push(`골드 +${Math.round(w.gold * 100)}%`)
  if (w.flame) parts.push('화염')
  return parts.join(' · ')
}

/* ────────────────────────── 설정 ────────────────────────── */

export function settingsPanel(
  settings: InputSettings,
  audio: { bgmEnabled: boolean; volume: number },
  onChange: () => void,
  act: PanelActions,
): PanelSpec {
  return {
    id: 'settings',
    title: '⚙ 설정',
    render(body) {
      const rows: HTMLElement[] = [
        slider('카메라 감도', 30, 220, settings.sensitivity, (v) => {
          settings.sensitivity = v
          onChange()
        }),
        slider('카메라 거리', 6, 24, settings.cameraDistance, (v) => {
          settings.cameraDistance = v
          onChange()
        }),
        slider('조이스틱 데드존 (%)', 5, 30, Math.round(settings.deadzone * 100), (v) => {
          settings.deadzone = v / 100
          onChange()
        }),
        slider('UI 크기 (%)', 80, 130, Math.round(settings.uiScale * 100), (v) => {
          settings.uiScale = v / 100
          document.documentElement.style.setProperty('--ui-scale', String(settings.uiScale))
          onChange()
        }),
        slider('음량', 0, 100, audio.volume, (v) => {
          audio.volume = v
          onChange()
        }),
        toggle('세로 반전', settings.invertY, (v) => {
          settings.invertY = v
          onChange()
        }),
        toggle('자동 공격', settings.autoAttack, (v) => {
          settings.autoAttack = v
          onChange()
        }),
        toggle('왼손잡이 모드', settings.leftHanded, (v) => {
          settings.leftHanded = v
          document.body.classList.toggle('left-handed', v)
          onChange()
        }),
        toggle('진동', settings.haptics, (v) => {
          settings.haptics = v
          onChange()
        }),
        toggle('보스 음악', audio.bgmEnabled, (v) => {
          audio.bgmEnabled = v
          onChange()
        }),
      ]
      body.append(...rows)
    },
    footer(foot, close) {
      foot.appendChild(button('전체화면', () => act.toggleFullscreen()))
      foot.appendChild(button('닫기', close, 'primary'))
    },
  }
}

function row(label: string): HTMLElement {
  const el = document.createElement('label')
  el.style.cssText =
    'display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 4px;border-bottom:1px solid rgba(150,200,255,.12);min-height:44px'
  const t = document.createElement('span')
  t.textContent = label
  el.appendChild(t)
  return el
}

function slider(
  label: string,
  min: number,
  max: number,
  value: number,
  on: (v: number) => void,
): HTMLElement {
  const el = row(label)
  const wrap = document.createElement('span')
  wrap.style.cssText = 'display:flex;align-items:center;gap:10px'
  const input = document.createElement('input')
  input.type = 'range'
  input.min = String(min)
  input.max = String(max)
  input.value = String(value)
  input.style.width = '160px'
  const out = document.createElement('b')
  out.textContent = String(value)
  out.style.cssText = 'min-width:38px;text-align:right;font-variant-numeric:tabular-nums'
  input.addEventListener('input', () => {
    const v = Number(input.value)
    out.textContent = String(v)
    on(v)
  })
  wrap.append(input, out)
  el.appendChild(wrap)
  return el
}

function toggle(label: string, value: boolean, on: (v: boolean) => void): HTMLElement {
  const el = row(label)
  const input = document.createElement('input')
  input.type = 'checkbox'
  input.checked = value
  input.style.cssText = 'width:26px;height:26px'
  input.addEventListener('change', () => on(input.checked))
  el.appendChild(input)
  return el
}

/* ────────────────────────── 사망 (FR-2.6) ────────────────────────── */

/**
 * 쓰러졌을 때. 원본 492–496 의 문구를 그대로 쓴다.
 *
 * **`modal: true` 다** — ESC 로 닫을 수 없다. 닫아 봐야 시체로 누워 있을 뿐이고,
 * 실제로 그 상태였다: 죽으면 누운 채 아무것도 할 수 없었다.
 * 부활은 **서버가 한다** (HP 전회복 · 1.5초 무적 · 마을 0,6).
 */
export function deathPanel(lostGold: number, act: PanelActions): PanelSpec {
  return {
    id: 'dead',
    title: '쓰러졌다',
    modal: true,
    render(body) {
      const wrap = document.createElement('div')
      wrap.style.cssText =
        'display:flex;flex-direction:column;gap:10px;align-items:center;text-align:center;padding:24px 0'

      const line = document.createElement('p')
      line.style.cssText = 'margin:0;font-size:15px;color:var(--ink-dim)'
      line.textContent =
        lostGold > 0
          ? `골드 일부를 잃었습니다 (−${lostGold.toLocaleString('ko-KR')} G)`
          : '골드 일부를 잃었습니다'
      wrap.appendChild(line)

      body.appendChild(wrap)
    },
    footer(foot, close) {
      foot.appendChild(
        button(
          '마을에서 부활',
          () => {
            act.respawn()
            close()
          },
          'primary',
        ),
      )
    },
  }
}

/* ────────────────────────── 일시정지 (D-3) ────────────────────────── */

/**
 * 원본에는 일시정지가 아예 없었다. `P.paused` 는 패널이 열린 부수효과였을 뿐이다.
 * ESC 한 번이면 여기로 온다.
 */
export function pausePanel(
  roomCode: string,
  openSettings: () => void,
  act: PanelActions,
): PanelSpec {
  return {
    id: 'pause',
    title: '일시정지',
    render(body) {
      const info = document.createElement('div')
      info.style.cssText = 'display:flex;flex-direction:column;gap:12px;max-width:420px'

      const codeRow = document.createElement('div')
      codeRow.style.cssText =
        'padding:16px;border-radius:14px;background:rgba(18,28,46,.8);border:1px solid rgba(150,200,255,.22)'
      const label = document.createElement('div')
      label.style.cssText = 'font-size:12px;opacity:.7;margin-bottom:6px'
      label.textContent = '친구를 부르려면 이 코드를 알려주세요'
      const code = document.createElement('div')
      code.style.cssText = 'font-size:32px;font-weight:900;letter-spacing:.2em'
      code.textContent = roomCode
      codeRow.append(label, code)
      codeRow.appendChild(button('코드 복사', () => act.copyRoomCode()))
      info.appendChild(codeRow)

      body.appendChild(info)
    },
    footer(foot, close) {
      foot.appendChild(button('설정', openSettings))
      foot.appendChild(button('방 나가기', () => act.leaveRoom(), 'danger'))
      foot.appendChild(button('계속하기', close, 'primary'))
    },
  }
}
