/**
 * 천국 원반 + 다리 — 원본 `reference/blocky-rpg.html` 1287–1352.
 *
 * ## 결정론
 * 원본은 `Math.random()` 으로 구름·부유 섬·회랑을 뿌렸다. 여기서는 시드 RNG 를 받는다
 * (기본 시드는 원본 지형 생성기 `rnd()` 와 같은 1337). **난수 소비 순서는 원본 그대로다** —
 * 순서를 바꾸면 같은 시드에서도 배치가 달라진다.
 *
 * ## G5
 * 다리 슬래브는 물리 벽(-252) 앞 `BRIDGE_MESH_Z_START`(-250)에서 시작해 이음매를 가리고,
 * 난간은 통행 한계(`BRIDGE_HW` ±8.5) **바로 바깥**(`BRIDGE_RAIL_X` ±9.5)에 선다.
 * 보이는 난간 안쪽이 곧 걸어갈 수 있는 폭이다.
 */

import * as THREE from 'three'
import {
  HEAVEN,
  HEAVEN_WALK,
  HEAVEN_VISUAL_R,
  HEAVEN_PROPS,
  BRIDGE_MESH_Z_START,
  BRIDGE_MESH_Z_END,
  BRIDGE_MESH_SEGMENTS,
  BRIDGE_MESH_SLAB_W,
  BRIDGE_RAIL_X,
  BRIDGE_LAMP_EVERY,
  lcg,
} from '@bq/shared'
import type { Rng } from '@bq/shared'
import { rboxGeo, blob, TM, GLOW } from '../artkit'
import { TAU, LM, add, circle, cyl, sphere } from './kit'
import type { Collider } from './kit'

/** 천국 장식물 기본 시드. 원본 지형 생성기(`rnd()`)와 같은 1337 이다. */
export const HEAVEN_SEED = 1337

/**
 * 구름 대지 · 가장자리 구름 140 · 다리 · 부유 섬 16 · 대리석 회랑 28.
 *
 * ⚠️ 반환값에 `colliders` 가 있다. 회랑 기둥 28개는 장식이 아니라 **실제 충돌체**다 (원본 1349).
 */
export function buildHeavenAndBridge(rng: Rng = lcg(HEAVEN_SEED)): {
  group: THREE.Group
  colliders: Collider[]
} {
  const group = new THREE.Group()
  const colliders: Collider[] = []
  // 원본 CLOUD 는 map 없는 MeshStandardMaterial 이다. artkit 의 TM 은 metalness 0 을 0.02 로 올린다.
  const CLOUD = TM(0xf2f6ff, null, 0.95, 0)
  const MARBLE = TM(0xe8ecf4, 'rock', 0.42, 0.08)
  const GOLD = TM(0xe0bc5c, 'metal', 0.28, 0.88)
  const SKYG = GLOW(0xfff2c8, 1.1)

  /* 구름 대지 — 보행 반경(112)보다 6 넓다 */
  const floor = new THREE.Mesh(circle(HEAVEN_VISUAL_R, 72), LM(0xdfe7f5))
  floor.rotation.x = -Math.PI / 2
  floor.position.set(HEAVEN.x, 0.05, HEAVEN.z)
  add(group, floor, false, true)

  /* 가장자리 구름 뭉치 */
  const EC = HEAVEN_PROPS.edgeClouds
  for (let i = 0; i < EC.count; i++) {
    const a = rng() * TAU
    const rr = EC.rMin + rng() * EC.rSpan
    const c = blob(4 + rng() * 7, CLOUD, 0.5, 2.2, 12)
    c.scale.set(1.5, 0.55, 1.5)
    c.position.set(HEAVEN.x + Math.cos(a) * rr, -1 + rng() * 2.5, HEAVEN.z + Math.sin(a) * rr)
    group.add(c)
  }

  /* 다리 — 문 앞(-250)에서 천국 원반 아래(-308)까지 */
  const z0 = BRIDGE_MESH_Z_START
  const z1 = BRIDGE_MESH_Z_END
  const bn = BRIDGE_MESH_SEGMENTS
  const slabD = (z0 - z1) / bn + 1.2
  for (let i = 0; i <= bn; i++) {
    const z = z0 + (z1 - z0) * (i / bn)
    const sl = new THREE.Mesh(rboxGeo(BRIDGE_MESH_SLAB_W, 0.8, slabD, 0.3, 0), MARBLE)
    sl.position.set(0, 0.4, z)
    add(group, sl, false, true)
    /* 난간 — 통행 한계 바로 바깥 */
    for (const sd of [-1, 1] as const) {
      const rail = new THREE.Mesh(rboxGeo(1.0, 1.5, slabD, 0.2, 0), MARBLE)
      rail.position.set(sd * BRIDGE_RAIL_X, 1.2, z)
      add(group, rail, true)
    }
    /* 5칸마다 기둥 + 등불 */
    if (i % BRIDGE_LAMP_EVERY === 0) {
      for (const sd of [-1, 1] as const) {
        const post = new THREE.Mesh(cyl(0.55, 0.7, 5.2, 10), MARBLE)
        post.position.set(sd * BRIDGE_RAIL_X, 2.6, z)
        add(group, post, true)
        const lamp = new THREE.Mesh(sphere(0.78, 10, 8), SKYG)
        lamp.position.set(sd * BRIDGE_RAIL_X, 5.6, z)
        add(group, lamp)
        const lt = new THREE.PointLight(0xfff2c8, 0.7, 22)
        lt.position.set(sd * BRIDGE_RAIL_X, 6.0, z)
        group.add(lt)
      }
    }
  }

  /* 부유 섬 — 충돌체 없음 */
  const FI = HEAVEN_PROPS.floatingIslands
  for (let i = 0; i < FI.count; i++) {
    const a = rng() * TAU
    const rr = FI.rMin + rng() * FI.rSpan
    const x = HEAVEN.x + Math.cos(a) * rr
    const z = HEAVEN.z + Math.sin(a) * rr
    const y = FI.yMin + rng() * FI.ySpan
    const isl = blob(5 + rng() * 5, CLOUD, 0.6, 2.6, 14)
    isl.scale.set(1.3, 0.5, 1.3)
    isl.position.set(x, y, z)
    group.add(isl)
    const pil = new THREE.Mesh(cyl(0.9, 1.4, 7, 10), MARBLE)
    pil.position.set(x, y + 4, z)
    add(group, pil)
    const cap = new THREE.Mesh(sphere(1.3, 12, 10), SKYG)
    cap.position.set(x, y + 8.4, z)
    add(group, cap)
  }

  /* 대리석 기둥 회랑 — 각도는 결정론적, 높이만 난수 */
  const CO = HEAVEN_PROPS.colonnade
  for (let i = 0; i < CO.count; i++) {
    const a = (i / CO.count) * TAU
    const rr = HEAVEN_WALK * CO.rFactor
    const x = HEAVEN.x + Math.cos(a) * rr
    const z = HEAVEN.z + Math.sin(a) * rr
    const h = 16 + rng() * 8
    const col = new THREE.Mesh(cyl(1.5, 1.9, h, 14), MARBLE)
    col.position.set(x, h / 2, z)
    add(group, col, true)
    const cap = new THREE.Mesh(rboxGeo(4.6, 1.2, 4.6, 0.2, 0), GOLD)
    cap.position.set(x, h + 0.6, z)
    add(group, cap)
    colliders.push({ x, z, r: CO.colliderR })
  }

  return { group, colliders }
}
