/**
 * WebSocket 클라이언트.
 *
 * 싱글플레이도 이 경로를 탄다 — 서버가 인메모리 루프백으로 붙을 뿐이다.
 * **싱글 전용 분기를 만들지 않는다.** 코드 경로가 갈리면 멀티에서만 나는 버그가 생긴다.
 */

import type { ClientMsg, ServerMsg, GameEvent, InputFrame } from '@bq/shared'
import { PROTOCOL_VERSION } from '@bq/shared'

export type ConnectionState = 'connecting' | 'open' | 'closed' | 'rejected'

/** 재접속 대기 시작값. 서버 재시작 정도는 거의 티가 안 나게 짧다. */
const RETRY_MIN_MS = 600
/** 재접속 대기 상한. 오래 끊긴 뒤에도 5초에 한 번은 다시 시도한다. */
const RETRY_MAX_MS = 5_000

/** 서버 역할을 하는 것의 최소 계약. 실제 WS 와 루프백이 같이 구현한다. */
export interface Transport {
  send(msg: ClientMsg): void
  close(): void
  onMessage: ((msg: ServerMsg) => void) | null
  onStateChange: ((s: ConnectionState) => void) | null
}

export class WsTransport implements Transport {
  private ws: WebSocket | null = null
  /**
   * 소켓이 열리기 전에 보낸 메시지를 담아 둔다.
   *
   * `new WebSocket()` 직후의 상태는 CONNECTING 이라 그냥 보내면 **조용히 사라진다.**
   * 첫 메시지가 `join` 이므로, 이게 없으면 접속은 되는데 게임이 시작되지 않는다.
   */
  private outbox: ClientMsg[] = []
  /** 재접속 대기 타이머. 명시적으로 close() 하면 멈춘다. */
  private retryTimer: ReturnType<typeof setTimeout> | null = null
  private retryDelay = RETRY_MIN_MS
  private closedByUs = false
  onMessage: ((msg: ServerMsg) => void) | null = null
  onStateChange: ((s: ConnectionState) => void) | null = null
  /**
   * 재접속 직후 다시 보낼 메시지를 만든다.
   *
   * 재접속은 **새 세션**이므로 `join` 부터 다시 해야 한다. 룸 코드를 들고 있으면
   * 같은 방으로 돌아가고, 60초 유예 안이면 진행도 그대로다.
   */
  onReconnect: (() => ClientMsg | null) | null = null

  constructor(private readonly url: string) {}

  /** 현재 접속 주소. 룸별 엔드포인트를 쓰는 배포에서는 코드가 경로에 들어간다. */
  get endpoint(): string {
    return this.url
  }

  connect(): void {
    this.closedByUs = false
    this.onStateChange?.('connecting')
    const ws = new WebSocket(this.url)
    this.ws = ws
    ws.onopen = () => {
      this.retryDelay = RETRY_MIN_MS
      const rejoin = this.onReconnect?.()
      const queued = this.outbox
      this.outbox = []
      if (rejoin) ws.send(JSON.stringify(rejoin))
      for (const m of queued) ws.send(JSON.stringify(m))
      this.onStateChange?.('open')
    }
    ws.onclose = () => {
      this.onStateChange?.('closed')
      this.scheduleRetry()
    }
    ws.onerror = () => {
      this.onStateChange?.('closed')
      this.scheduleRetry()
    }
    ws.onmessage = (ev) => {
      // 파싱만 try 로 감싼다. 핸들러까지 감싸면 게임 코드의 예외가 조용히 사라져
      // "접속은 됐는데 아무 일도 안 일어남" 이 된다 — 실제로 한 번 겪었다.
      let msg: ServerMsg
      try {
        msg = JSON.parse(String(ev.data)) as ServerMsg
      } catch {
        return // 손상된 프레임은 버린다
      }
      this.onMessage?.(msg)
    }
  }

  send(msg: ClientMsg): void {
    const ws = this.ws
    if (ws?.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify(msg))
      return
    }
    // 아직 안 열렸으면 큐에 넣는다. 입력 프레임은 쌓아 봐야 낡은 값이라 버린다.
    if (msg.t !== 'input') this.outbox.push(msg)
  }

  close(): void {
    this.closedByUs = true
    if (this.retryTimer !== null) clearTimeout(this.retryTimer)
    this.retryTimer = null
    this.outbox.length = 0
    this.ws?.close()
    this.ws = null
  }

  /**
   * 지수 백오프로 다시 붙는다.
   *
   * 폰에서 화면을 껐다 켜거나 와이파이가 잠깐 끊기면 소켓이 죽는다.
   * 재접속이 없으면 게임은 계속 돌아가는데 서버와는 완전히 갈라져 **혼자만의 환상**이 된다
   * (실제로 예측 큐가 2,418개까지 쌓인 채 돌고 있었다).
   */
  private scheduleRetry(): void {
    if (this.closedByUs || this.retryTimer !== null) return
    const delay = this.retryDelay
    this.retryDelay = Math.min(RETRY_MAX_MS, Math.round(this.retryDelay * 1.8))
    this.retryTimer = setTimeout(() => {
      this.retryTimer = null
      if (!this.closedByUs) this.connect()
    }, delay)
  }
}

export interface NetHandlers {
  onHello?: (playerId: number, roomCode: string, worldSeed: number) => void
  onSnapshot?: (msg: Extract<ServerMsg, { t: 'snapshot' }>) => void
  onEvent?: (ev: GameEvent) => void
  onReject?: (reason: string) => void
  onState?: (s: ConnectionState) => void
}

export class NetClient {
  playerId = -1
  roomCode = ''
  worldSeed = 0
  state: ConnectionState = 'closed'
  /** 왕복 지연(ms). 보간 지연을 정하는 데 쓴다. */
  rtt = 0

  private seq = 0
  private joinName = '모험가'
  private joinRoom = ''
  private pingTimer: ReturnType<typeof setInterval> | null = null

  constructor(
    private readonly transport: Transport,
    private readonly handlers: NetHandlers = {},
  ) {
    transport.onMessage = (m) => this.handle(m)
    // 끊겼다가 다시 붙으면 새 세션이므로 join 부터 다시 한다.
    if ('onReconnect' in transport) {
      ;(transport as WsTransport).onReconnect = () => (this.joinName ? this.joinMessage() : null)
    }
    transport.onStateChange = (s) => {
      this.state = s
      this.handlers.onState?.(s)
      if (s === 'open') this.startPing()
      else this.stopPing()
    }
  }

  join(name: string, roomCode?: string): void {
    this.joinName = name
    if (roomCode) this.joinRoom = roomCode
    this.transport.send(this.joinMessage())
  }

  /**
   * 재접속용 join. 이미 방을 배정받았으면 **그 방으로** 돌아간다.
   *
   * 저장 데이터를 매번 새로 뽑는 이유: 서버가 재시작되면 룸이 사라지고
   * 재접속이 **새 방을 만든다**. 그때 처음 접속 시점의 낡은 저장을 보내면
   * 그 사이의 진행이 통째로 날아간다.
   */
  private joinMessage(): ClientMsg {
    const room = this.roomCode || this.joinRoom
    const save = this.saveProvider?.()
    const base = { t: 'join', protocol: PROTOCOL_VERSION, name: this.joinName } as const
    return {
      ...base,
      ...(room ? { roomCode: room } : {}),
      ...(save !== undefined && save !== null ? { save } : {}),
    }
  }

  /**
   * 저장 데이터 공급자. `join` 과 재접속이 이걸 불러 **그 순간의** 진행을 싣는다.
   *
   * ⚠️ 서버는 이 데이터를 **자기 방을 새로 만들 때만** 받아들인다
   * (`packages/shared/src/progress/save.ts` 의 절충). 남의 방에 들어가면 무시된다.
   */
  saveProvider: (() => unknown) | null = null

  /** 입력 프레임에 seq 를 붙여 보낸다. 예측 재조정이 이 seq 를 기준으로 돈다. */
  sendInput(frame: Omit<InputFrame, 'seq'>): number {
    const seq = ++this.seq
    this.transport.send({ t: 'input', frame: { ...frame, seq } })
    return seq
  }

  send(msg: ClientMsg): void {
    this.transport.send(msg)
  }

  close(): void {
    this.stopPing()
    this.transport.close()
  }

  private startPing(): void {
    this.stopPing()
    this.pingTimer = setInterval(() => {
      this.transport.send({ t: 'ping', clientTime: performance.now() })
    }, 2000)
  }

  private stopPing(): void {
    if (this.pingTimer !== null) {
      clearInterval(this.pingTimer)
      this.pingTimer = null
    }
  }

  private handle(m: ServerMsg): void {
    switch (m.t) {
      case 'hello':
        this.playerId = m.playerId
        this.roomCode = m.roomCode
        this.worldSeed = m.worldSeed
        this.handlers.onHello?.(m.playerId, m.roomCode, m.worldSeed)
        break
      case 'reject':
        this.state = 'rejected'
        this.handlers.onReject?.(m.reason)
        break
      case 'snapshot':
        this.handlers.onSnapshot?.(m)
        break
      case 'event':
        this.handlers.onEvent?.(m.ev)
        break
      case 'pong':
        this.rtt = performance.now() - m.clientTime
        break
    }
  }
}
