/**
 * 절차 텍스처 — 캔버스로 그려서 GPU 로 올린다. 외부 이미지 파일이 없다.
 *
 * 원본 `reference/blocky-rpg.html` 580–659 줄의 이관본이다.
 * 텍스처는 전부 **회색조**다 — 색은 재질의 `color` 가 곱해서 낸다.
 * 덕분에 천 1장으로 8직업 옷 색을 전부 만든다.
 *
 * 수치(색·개수·길이·굵기·각도·곡률·셀 크기·UV 반복)는 원본 그대로다.
 */

import * as THREE from 'three'
import { lcg, type Rng } from '@bq/shared'
import { noise3 } from './noise'

export type TexName =
  | 'cloth'
  | 'fur'
  | 'fuzz'
  | 'skin'
  | 'scale'
  | 'bone'
  | 'metal'
  | 'rock'
  | 'wood'

/** 원본에 있던 보조 텍스처 2종. `denim` 은 바지(1곳), `knit` 은 정의만 있고 미사용이었다. */
export type TexNameExt = TexName | 'denim' | 'knit'

/** 2D 캔버스 컨텍스트. 환경맵 생성기도 같이 쓴다. */
export function canvas2d(w: number, h = w): CanvasRenderingContext2D {
  const c = document.createElement('canvas')
  c.width = w
  c.height = h
  const g = c.getContext('2d')
  if (!g) throw new Error('2D 캔버스 컨텍스트를 만들 수 없다 — 절차 텍스처 생성 불가')
  return g
}

const pickCol = (rnd: Rng, cols: readonly string[]): string => cols[(rnd() * cols.length) | 0]!

/** 실오라기 — 9방향 랩어라운드로 타일 이음매를 지운다. */
function fibers(
  rnd: Rng,
  n: number,
  base: string,
  cols: readonly string[],
  count: number,
  len: number,
  lw: number,
  ang: number | undefined,
  curve: number,
): HTMLCanvasElement {
  const g = canvas2d(n)
  g.fillStyle = base
  g.fillRect(0, 0, n, n)
  g.lineCap = 'round'
  g.lineWidth = lw
  for (let i = 0; i < count; i++) {
    const x = rnd() * n
    const y = rnd() * n
    const a = ang === undefined ? rnd() * 6.283 : ang + (rnd() - 0.5) * 0.6
    const L = len * (0.45 + rnd())
    const bx2 = Math.cos(a + 1.57) * L * curve * (rnd() - 0.5)
    const by2 = Math.sin(a + 1.57) * L * curve * (rnd() - 0.5)
    g.strokeStyle = pickCol(rnd, cols)
    for (let dx = -1; dx <= 1; dx++)
      for (let dy = -1; dy <= 1; dy++) {
        const ox = x + dx * n
        const oy = y + dy * n
        g.beginPath()
        g.moveTo(ox, oy)
        g.quadraticCurveTo(
          ox + Math.cos(a) * L * 0.5 + bx2,
          oy + Math.sin(a) * L * 0.5 + by2,
          ox + Math.cos(a) * L,
          oy + Math.sin(a) * L,
        )
        g.stroke()
      }
  }
  return g.canvas
}

/** 반점 — 피부·뜨개·뼈·바위. */
function specks(
  rnd: Rng,
  n: number,
  base: string,
  cols: readonly string[],
  count: number,
  r: number,
): HTMLCanvasElement {
  const g = canvas2d(n)
  g.fillStyle = base
  g.fillRect(0, 0, n, n)
  for (let i = 0; i < count; i++) {
    const x = rnd() * n
    const y = rnd() * n
    const rr = r * (0.45 + rnd())
    g.fillStyle = pickCol(rnd, cols)
    for (let dx = -1; dx <= 1; dx++)
      for (let dy = -1; dy <= 1; dy++) {
        g.beginPath()
        g.arc(x + dx * n, y + dy * n, rr, 0, 6.283)
        g.fill()
      }
  }
  return g.canvas
}

/** 비늘 — 반원을 벽돌쌓기로 겹친다. */
function scalesTex(
  rnd: Rng,
  n: number,
  base: string,
  cols: readonly string[],
  cell: number,
): HTMLCanvasElement {
  const g = canvas2d(n)
  g.fillStyle = base
  g.fillRect(0, 0, n, n)
  g.lineWidth = Math.max(1, cell * 0.09)
  for (let row = 0; row * cell * 0.62 < n + cell; row++) {
    for (let col = -1; col * cell < n + cell; col++) {
      const x = col * cell + (row % 2 ? cell * 0.5 : 0)
      const y = row * cell * 0.62
      g.fillStyle = pickCol(rnd, cols)
      g.beginPath()
      g.arc(x, y, cell * 0.52, Math.PI, 0, false)
      g.fill()
      g.strokeStyle = 'rgba(0,0,0,.22)'
      g.stroke()
    }
  }
  return g.canvas
}

/** 나뭇결 — 노이즈로 나이테를 그린다. 픽셀 단위 계산이라 난수를 쓰지 않는다. */
function woodGrain(n: number): HTMLCanvasElement {
  const g = canvas2d(n)
  const img = g.createImageData(n, n)
  for (let y = 0; y < n; y++)
    for (let x = 0; x < n; x++) {
      const w = noise3(x * 0.019, y * 0.3, 0.5) * 0.5 + 0.5
      const ring = Math.sin(w * 24 + noise3(x * 0.055, y * 0.055, 2) * 4) * 0.5 + 0.5
      const v = 0.56 + ring * 0.44
      const i = (y * n + x) * 4
      img.data[i] = 178 * v
      img.data[i + 1] = 128 * v
      img.data[i + 2] = 80 * v
      img.data[i + 3] = 255
    }
  g.putImageData(img, 0, 0)
  return g.canvas
}

interface TexSpec {
  /** 캔버스를 그린다. `rnd` 는 이 텍스처 전용 난수 스트림이다. */
  readonly draw: (rnd: Rng) => HTMLCanvasElement
  /** UV 반복 횟수 */
  readonly repeat: number
  /** 전용 시드 — 텍스처끼리 같은 난수열을 밟지 않도록 어긋나게 둔다. */
  readonly seed: number
}

/**
 * 텍스처 정의 11종.
 *
 * ⚠️ 원본은 텍스처 11장을 **하나의 전역 rnd() 스트림**에서 순서대로 그렸다.
 *    lazy 생성으로 바뀌면 그리는 순서에 따라 스트림이 어긋나므로 텍스처마다 전용 시드를 준다.
 *    파라미터가 전부 원본과 같으니 결과물의 성격(밀도·색·굵기)은 동일하고,
 *    실오라기·반점이 찍히는 좌표만 달라진다. 디자인 값이 아니라 난수 배치라 무해하다.
 */
const TEX_SPEC: Readonly<Record<TexNameExt, TexSpec>> = {
  cloth: {
    seed: 1337,
    repeat: 2,
    draw: (r) => fibers(r, 256, '#8a8a8a', ['#a6a6a6', '#6e6e6e', '#9a9a9a'], 1500, 9, 1.6, 0, 0.2),
  },
  denim: {
    seed: 9257,
    repeat: 2,
    draw: (r) => fibers(r, 256, '#7e7e7e', ['#9e9e9e', '#5e5e5e'], 1600, 11, 1.4, 0.72, 0.1),
  },
  skin: {
    seed: 17177,
    repeat: 2,
    draw: (r) => specks(r, 256, '#9a9a9a', ['#a8a8a8', '#8e8e8e'], 1400, 1.5),
  },
  fuzz: {
    seed: 25097,
    repeat: 2,
    draw: (r) => fibers(r, 256, '#8a8a8a', ['#c0c0c0', '#5a5a5a'], 2000, 13, 1.5, undefined, 0.7),
  },
  knit: {
    seed: 33017,
    repeat: 3,
    draw: (r) => specks(r, 256, '#8a8a8a', ['#d8d8d8', '#4a4a4a', '#b0b0b0'], 2200, 3.4),
  },
  fur: {
    seed: 40937,
    repeat: 3,
    draw: (r) => fibers(r, 256, '#8a8a8a', ['#b8b8b8', '#5c5c5c'], 2600, 10, 1.3, undefined, 0.5),
  },
  scale: {
    seed: 48857,
    repeat: 2,
    draw: (r) => scalesTex(r, 256, '#8a8a8a', ['#a4a4a4', '#767676', '#9a9a9a'], 22),
  },
  bone: {
    seed: 56777,
    repeat: 2,
    draw: (r) => specks(r, 256, '#a2a2a2', ['#b6b6b6', '#8a8a8a', '#6e6e6e'], 900, 2.2),
  },
  metal: {
    seed: 64697,
    repeat: 1,
    draw: (r) => fibers(r, 256, '#9a9a9a', ['#b4b4b4', '#828282'], 1800, 26, 1.0, 0, 0),
  },
  wood: { seed: 72617, repeat: 1, draw: () => woodGrain(256) },
  rock: {
    seed: 80537,
    repeat: 2,
    draw: (r) => specks(r, 256, '#8e8e8e', ['#a8a8a8', '#6c6c6c', '#bcbcbc'], 1300, 3.0),
  },
}

const texCache = new Map<TexNameExt, THREE.Texture>()

/**
 * 절차 텍스처를 얻는다.
 * 처음 부를 때만 캔버스를 그리고 그 뒤로는 캐시를 돌려준다 — 몹 67마리가 한 장을 나눠 쓴다 (D-8).
 * 11장을 미리 다 그리면 부팅이 느려지고, 실제로 쓰이지 않는 것도 있어 lazy 로 둔다.
 */
export function tex(name: TexNameExt): THREE.Texture {
  const hit = texCache.get(name)
  if (hit) return hit
  const spec = TEX_SPEC[name]
  const t = new THREE.CanvasTexture(spec.draw(lcg(spec.seed)))
  t.wrapS = t.wrapT = THREE.RepeatWrapping
  t.repeat.set(spec.repeat, spec.repeat)
  t.anisotropy = 4
  t.colorSpace = THREE.SRGBColorSpace
  t.name = name
  texCache.set(name, t)
  return t
}

/** 캐시된 텍스처를 전부 해제한다. `disposeAll()` 이 부른다. */
export function disposeTextures(): void {
  for (const t of texCache.values()) t.dispose()
  texCache.clear()
}
