/**
 * 포인터 어댑터 — 마우스와 터치를 한 경로로 처리한다 (원본과 같은 설계).
 *
 * - 왼쪽 조이스틱 영역(하단 40%×70%)을 터치하면 그 자리에 플로팅 조이스틱이 생긴다.
 * - 나머지 영역 드래그는 카메라 회전, 짧은 탭(<12px, <320ms)은 공격.
 * - 마우스는 어디를 눌러도 카메라 회전이다 (원본 동작 유지).
 * - 멀티터치: 포인터 id 로 조이스틱과 카메라를 독립 추적한다.
 */

import type { InputHub } from './state'

const TAP_PX = 12
const TAP_MS = 320
const JOY_MAX = 44 // 노브 최대 편차
const PITCH_MIN = -0.1
const PITCH_MAX = 0.95

export interface PointerRefs {
  readonly joyZone: HTMLElement
  readonly joy: HTMLElement
  readonly knob: HTMLElement
  readonly surface: HTMLElement
}

export interface CameraCtl {
  yaw: number
  pitch: number
  distance: number
}

/**
 * ⚠️ **리스너를 어디에 다는지가 이 파일의 핵심이다.**
 *
 * `#joyZone` 은 캔버스의 **형제**이고 `pointer-events: auto` 라 왼쪽 영역의 터치를 삼킨다.
 * 그래서 모든 리스너를 캔버스에 달면 `joyZone.contains(e.target)` 이 **한 번도 참이 되지 않고**,
 * 왼쪽 40%×70% 가 통째로 죽은 영역이 된다 — 실제로 모바일에서 그랬다.
 *
 * 그래서 조이스틱은 `#joyZone` 자신에게, 카메라·탭공격은 캔버스에 단다.
 * 버튼(공격·점프·특수기)과 HUD 는 캔버스의 자식이 아니므로 카메라를 끌지 않는다 —
 * 리스너를 window 에 달면 그 구분이 사라진다.
 */
export function attachPointer(hub: InputHub, refs: PointerRefs, cam: CameraCtl): () => void {
  let joyId = -1
  let joyOx = 0
  let joyOz = 0
  let lookId = -1
  let lookX = 0
  let lookY = 0
  let lookStartX = 0
  let lookStartY = 0
  let lookStartT = 0
  let lookMoved = 0

  const isTouch = (e: PointerEvent): boolean => e.pointerType !== 'mouse'

  const startJoy = (e: PointerEvent): void => {
    joyId = e.pointerId
    joyOx = e.clientX
    joyOz = e.clientY
    refs.joy.style.left = `${joyOx}px`
    refs.joy.style.top = `${joyOz}px`
    refs.joy.classList.remove('hidden')
    refs.knob.style.transform = 'translate(0px, 0px)'
  }

  const moveJoy = (e: PointerEvent): void => {
    const dx = e.clientX - joyOx
    const dy = e.clientY - joyOz
    const d = Math.hypot(dx, dy)
    const k = d > JOY_MAX ? JOY_MAX / d : 1
    refs.knob.style.transform = `translate(${dx * k}px, ${dy * k}px)`
    hub.raw.joyMove.x = (dx * k) / JOY_MAX
    hub.raw.joyMove.z = (dy * k) / JOY_MAX
  }

  const endJoy = (): void => {
    joyId = -1
    hub.raw.joyMove.x = 0
    hub.raw.joyMove.z = 0
    refs.joy.classList.add('hidden')
  }

  /* ── 조이스틱: #joyZone 전용 ── */

  const onJoyDown = (e: PointerEvent): void => {
    hub.markDevice('touch')
    if (joyId >= 0) return
    e.preventDefault()
    startJoy(e)
    refs.joyZone.setPointerCapture(e.pointerId)
  }

  const onJoyMove = (e: PointerEvent): void => {
    if (e.pointerId !== joyId) return
    e.preventDefault()
    moveJoy(e)
  }

  const onJoyUp = (e: PointerEvent): void => {
    if (e.pointerId !== joyId) return
    endJoy()
  }

  /* ── 카메라 · 탭 공격: 캔버스 ── */

  const onDown = (e: PointerEvent): void => {
    hub.markDevice(isTouch(e) ? 'touch' : 'keyboard')
    if (lookId >= 0) return
    lookId = e.pointerId
    lookX = e.clientX
    lookY = e.clientY
    lookStartX = e.clientX
    lookStartY = e.clientY
    lookStartT = performance.now()
    lookMoved = 0
    refs.surface.setPointerCapture?.(e.pointerId)
  }

  const onMove = (e: PointerEvent): void => {
    if (e.pointerId !== lookId) return
    const dx = e.clientX - lookX
    const dy = e.clientY - lookY
    lookX = e.clientX
    lookY = e.clientY
    lookMoved = Math.max(lookMoved, Math.hypot(e.clientX - lookStartX, e.clientY - lookStartY))
    hub.raw.look.dx += dx
    hub.raw.look.dy += dy
  }

  const onUp = (e: PointerEvent): void => {
    if (e.pointerId !== lookId) return
    const dt = performance.now() - lookStartT
    // C8: 카메라를 살짝 돌리려는 의도와 탭-공격이 충돌하지 않도록 두 조건을 모두 요구한다.
    if (lookMoved < TAP_PX && dt < TAP_MS) {
      hub.raw.attackHeld = true
      // 탭 공격은 1프레임만 유지한다.
      setTimeout(() => {
        hub.raw.attackHeld = false
      }, 60)
    }
    lookId = -1
  }

  const onWheel = (e: WheelEvent): void => {
    e.preventDefault()
    hub.raw.zoom += Math.sign(e.deltaY)
  }

  const el = refs.surface
  el.addEventListener('pointerdown', onDown)
  el.addEventListener('pointermove', onMove)
  el.addEventListener('pointerup', onUp)
  el.addEventListener('pointercancel', onUp)
  el.addEventListener('wheel', onWheel, { passive: false })

  const zone = refs.joyZone
  zone.addEventListener('pointerdown', onJoyDown)
  zone.addEventListener('pointermove', onJoyMove)
  zone.addEventListener('pointerup', onJoyUp)
  zone.addEventListener('pointercancel', onJoyUp)

  return () => {
    el.removeEventListener('pointerdown', onDown)
    el.removeEventListener('pointermove', onMove)
    el.removeEventListener('pointerup', onUp)
    el.removeEventListener('pointercancel', onUp)
    el.removeEventListener('wheel', onWheel)
    zone.removeEventListener('pointerdown', onJoyDown)
    zone.removeEventListener('pointermove', onJoyMove)
    zone.removeEventListener('pointerup', onJoyUp)
    zone.removeEventListener('pointercancel', onJoyUp)
  }
}

/** 카메라 각도에 look 델타를 적용한다. pitch 는 원본과 같은 범위로 클램프한다. */
export function applyLook(cam: CameraCtl, dx: number, dy: number): void {
  // 원본 4685–4686 과 같은 계수. 감도 설정은 이미 InputHub 가 곱해 놓았다.
  cam.yaw -= dx * 0.0055
  cam.pitch = Math.max(PITCH_MIN, Math.min(PITCH_MAX, cam.pitch + dy * 0.0042))
}

export function applyZoom(cam: CameraCtl, dz: number): void {
  cam.distance = Math.max(6, Math.min(24, cam.distance + dz))
}

/** 액션 버튼(공격/점프/특수기)을 hub 에 연결한다. 누르고 있으면 연타되는 것은 공격뿐이다. */
export function attachActionButtons(
  hub: InputHub,
  btns: { attack: HTMLElement; jump: HTMLElement; special: HTMLElement },
): () => void {
  const hold = (el: HTMLElement, on: () => void, off?: () => void): (() => void) => {
    const d = (e: PointerEvent): void => {
      e.preventDefault()
      hub.markDevice('touch')
      on()
    }
    const u = (): void => off?.()
    el.addEventListener('pointerdown', d)
    el.addEventListener('pointerup', u)
    el.addEventListener('pointercancel', u)
    el.addEventListener('pointerleave', u)
    return () => {
      el.removeEventListener('pointerdown', d)
      el.removeEventListener('pointerup', u)
      el.removeEventListener('pointercancel', u)
      el.removeEventListener('pointerleave', u)
    }
  }

  const offs = [
    hold(
      btns.attack,
      () => {
        hub.raw.attackHeld = true
      },
      () => {
        hub.raw.attackHeld = false
      },
    ),
    hold(btns.jump, () => {
      hub.raw.jumpEdge = true
    }),
    hold(btns.special, () => {
      hub.raw.specialEdge = true
    }),
  ]

  return () => offs.forEach((f) => f())
}
