/**
 * 입력 추상화 레이어 (docs/04-CONTROLS.md §3.1).
 *
 * 게임 로직은 `InputState` 만 본다. 키보드 · 터치 · 게임패드는 이 구조체를 채우는 어댑터일 뿐이다.
 * 어댑터를 여러 개 동시에 켜도 된다 — 태블릿 + 블루투스 키보드 같은 조합이 실제로 존재한다.
 */

export interface InputState {
  /** 카메라 상대 이동. 각 축 −1..1 */
  readonly move: { x: number; z: number }
  /** 이번 프레임의 카메라 회전 델타(px 단위) */
  readonly look: { dx: number; dy: number }
  readonly attack: boolean
  readonly jump: boolean
  readonly special: boolean
  readonly run: boolean
  /** 이번 프레임에 눌린 UI 커맨드 (에지 트리거) */
  readonly ui: readonly UiCommand[]
  /** 카메라 거리 델타 (휠 / 트리거) */
  readonly zoom: number
}

export type UiCommand =
  | 'menu' // ESC / Start — 일시정지 또는 최상단 패널 닫기 (D-3)
  | 'tree'
  | 'shop'
  | 'map'
  | 'autoAttack'
  | 'cameraReset'

export interface InputSettings {
  /** 30 ~ 220 (%) */
  sensitivity: number
  /** 6 ~ 24 */
  cameraDistance: number
  invertY: boolean
  autoAttack: boolean
  /** 0.05 ~ 0.30 (C6 수정 — 원본은 0.12 하드코딩) */
  deadzone: number
  /** 왼손잡이 모드 — 조이스틱/버튼 좌우 미러 (C7) */
  leftHanded: boolean
  haptics: boolean
  uiScale: number
}

export const DEFAULT_SETTINGS: InputSettings = {
  sensitivity: 100,
  cameraDistance: 13,
  invertY: false,
  autoAttack: false,
  deadzone: 0.12,
  leftHanded: false,
  haptics: true,
  uiScale: 1,
}

/** 마지막으로 사용한 입력 장치. **화면 크기로 판별하지 않는다** (docs/04 §4). */
export type InputDevice = 'keyboard' | 'touch' | 'gamepad'

export class InputHub {
  readonly settings: InputSettings
  lastDevice: InputDevice = 'keyboard'

  /** 어댑터들이 직접 쓰는 누적 버퍼. 매 프레임 `consume()` 이 비운다. */
  readonly raw = {
    keyMove: { x: 0, z: 0 },
    padMove: { x: 0, z: 0 },
    joyMove: { x: 0, z: 0 },
    look: { dx: 0, dy: 0 },
    zoom: 0,
    attackHeld: false,
    jumpEdge: false,
    specialEdge: false,
    runHeld: false,
    ui: [] as UiCommand[],
  }

  constructor(settings: InputSettings = { ...DEFAULT_SETTINGS }) {
    this.settings = settings
  }

  markDevice(d: InputDevice): void {
    if (this.lastDevice !== d) {
      this.lastDevice = d
      this.onDeviceChange?.(d)
    }
  }

  onDeviceChange?: (d: InputDevice) => void

  pushUi(cmd: UiCommand): void {
    if (!this.raw.ui.includes(cmd)) this.raw.ui.push(cmd)
  }

  /**
   * 이번 프레임의 입력을 확정하고 에지 트리거를 소비한다.
   *
   * 이동은 **합산 후 클램프**한다 (원본 동작 유지): 키보드로 걸으면서 조이스틱을 밀 수 있다.
   */
  consume(): InputState {
    const r = this.raw
    const rawX = r.keyMove.x + r.joyMove.x + r.padMove.x
    const rawZ = r.keyMove.z + r.joyMove.z + r.padMove.z

    let x = clamp1(rawX)
    let z = clamp1(rawZ)

    // 데드존은 벡터 크기에 적용한다. 축별로 자르면 대각선이 어긋난다.
    const mag = Math.hypot(x, z)
    if (mag < this.settings.deadzone) {
      x = 0
      z = 0
    } else if (mag > 1) {
      x /= mag
      z /= mag
    }

    const sens = this.settings.sensitivity / 100
    const state: InputState = {
      move: { x, z },
      look: {
        dx: r.look.dx * sens,
        dy: r.look.dy * sens * (this.settings.invertY ? -1 : 1),
      },
      attack: r.attackHeld,
      jump: r.jumpEdge,
      special: r.specialEdge,
      run: r.runHeld,
      ui: r.ui.slice(),
      zoom: r.zoom,
    }

    // 에지 트리거와 델타만 비운다. 홀드 상태는 어댑터가 관리한다.
    r.look.dx = 0
    r.look.dy = 0
    r.zoom = 0
    r.jumpEdge = false
    r.specialEdge = false
    r.ui.length = 0

    return state
  }

  vibrate(ms: number): void {
    if (!this.settings.haptics) return
    navigator.vibrate?.(ms)
  }
}

function clamp1(v: number): number {
  return v < -1 ? -1 : v > 1 ? 1 : v
}

/** 햅틱 세기 (docs/04 §3.4) */
export const HAPTIC = {
  crit: 12,
  hurt: 25,
  bossPhase: 60,
} as const
