/**
 * 특수기 시전의 서버 적용.
 *
 * `shared/skills/specials.ts` 의 `buildSpecial()` 은 **효과 서술**만 만든다
 * (반경 얼마, 배수 얼마, 몇 초). 그 서술을 실제 상태 변화로 바꾸는 것이 이 파일이다.
 *
 * ## 여기서 살아나는 노드
 * · 🆕 `bossX`(종말) — 피해 2배 + "즉시 재사용" 1회 충전
 * · 🆕 `necroX`(사령왕) — 소환 상한의 "군단 +4" (상한 계산은 `skeletonCapOf` 안에 있다)
 * 나머지(whirl · volley · brine · tong · doom · dig · shift)는 원본에서도 연결돼 있던
 * 노드라 `buildSpecial()` 이 이미 서술에 반영해 놓았다.
 */

import { arrowPierce, buildSpecial } from '@bq/shared'
import type { MobState, SpecialCast, Vec3 } from '@bq/shared'

import { currentSpecialCooldown } from './player'
import type { PlayerState } from './player'
import type { Projectile } from './world-objects'

/** 시전이 룸에게 시키는 일들. */
export interface SpecialSink {
  readonly mobs: readonly MobState[]
  /** 원형 광역 피해. 무적 판정·기여도·처치는 룸이 처리한다 */
  aoeDamage(by: PlayerState, center: Vec3, radius: number, damage: number, color: number): void
  damageMob(m: MobState, base: number, by: PlayerState): void
  spawnProjectile(pr: Omit<Projectile, 'id'>): void
  summon(owner: PlayerState, at: { readonly x: number; readonly z: number }, count: number): void
  /** 장판을 깐다. 피해는 `room/fields.ts` 가 시간에 걸쳐 준다 */
  addField(owner: PlayerState, f: FieldPlacement): void
  /** 판정 범위를 클라에 보여준다. **판정과 같은 값만 넘긴다** */
  showArea(a: AreaShown): void
  toast(text: string): void
}

export interface FieldPlacement {
  readonly x: number
  readonly z: number
  readonly radius: number
  readonly damagePerTick: number
  readonly tickInterval: number
  readonly duration: number
}

export interface AreaShown {
  readonly x: number
  readonly z: number
  readonly radius: number
  readonly color: number
  readonly shape: 'burst' | 'field' | 'cone'
  readonly yaw?: number
  readonly halfAngle?: number
  readonly duration?: number
}

/**
 * 특수기 한 번을 적용한다. 쿨 · 충전 갱신까지 여기서 끝낸다.
 *
 * 원본은 쿨을 효과 적용 **전에** 건다 (4506). 시전이 헛나가도(파슬리 헛침) 쿨은 돈다 —
 * 그 순서를 그대로 지킨다.
 */
export function applySpecialCast(p: PlayerState, sink: SpecialSink): SpecialCast | null {
  if (!p.classId) return null
  const cast = buildSpecial(p.classId, p.skills)

  // 🆕 bossX(종말) — "즉시 재사용" 의 가장 보수적인 해석: **정상 시전 1회당 무료 시전 1회.**
  //    무료 시전은 충전을 소비하고 재충전하지 않는다. 재충전하면 버튼을 누르고 있는 동안
  //    무한 시전이 되어 "쿨타임" 이라는 개념 자체가 사라진다.
  const usedCharge = p.specialCd > 0 && p.specialCharged
  p.specialCd = currentSpecialCooldown(p)
  p.specialCharged = p.mods.specialCooldownReset && !usedCharge

  // 🆕 bossX — 특수기 피해 2배. `specialDamagePct`(합괄호)는 buildSpecial 이 이미 반영했으므로
  //    여기서는 **마지막에 한 번** 곱한다: dmg × (1 + pct) × mul.
  const mul = p.mods.specialDamageMul
  const here: Vec3 = { x: p.x, y: 0, z: p.z }

  for (const e of cast.effects) {
    switch (e.kind) {
      case 'invulnerable':
        p.invul = Math.max(p.invul, e.duration)
        break
      case 'heal':
        p.hp = Math.min(p.stats.maxHp, p.hp + p.stats.maxHp * e.fractionOfMax + e.flat)
        break
      case 'speed-buff':
        p.buffT = Math.max(p.buffT, e.duration)
        break
      case 'aoe':
        sink.aoeDamage(p, here, e.radius, p.stats.dmg * e.damageMul * mul, e.color)
        break
      case 'arrow-fan': {
        const half = (e.count - 1) / 2
        for (let i = -half; i <= half; i++) {
          const a = p.yaw + i * e.spreadStep
          sink.spawnProjectile({
            x: p.x,
            y: 1.2,
            z: p.z,
            dx: Math.sin(a),
            dz: Math.cos(a),
            speed: e.speed,
            life: e.life,
            damage: p.stats.dmg * e.damageMul * mul,
            burn: false,
            owner: p.id,
            pierceLeft: arrowPierce(p.skills),
            hit: new Set<string>(),
          })
        }
        break
      }
      case 'cone-pull': {
        // 판정에 쓰는 내적 하한을 **그대로 각도로 바꿔** 넘긴다. 보이는 부채꼴이 곧 맞는 부채꼴이다.
        sink.showArea({
          x: p.x,
          z: p.z,
          radius: e.range,
          color: 0x8fe06a,
          shape: 'cone',
          yaw: p.yaw,
          halfAngle: Math.acos(e.facingDotMin),
        })
        const forward = { x: Math.sin(p.yaw), z: Math.cos(p.yaw) }
        for (const m of sink.mobs) {
          if (m.dead) continue
          const dx = m.pos.x - p.x
          const dz = m.pos.z - p.z
          const d = Math.hypot(dx, dz)
          if (d > e.range || d === 0) continue
          // 파슬리의 혀는 부채꼴이 넓다 (±69°) — 전용 내적 하한을 쓴다.
          if (forward.x * (dx / d) + forward.z * (dz / d) < e.facingDotMin) continue
          sink.damageMob(m, p.stats.dmg * e.damageMul * mul, p)
        }
        break
      }
      case 'summon':
        // 🆕 necroX 의 "군단 +4" 는 상한 계산(`skeletonCapOf`) 안에 들어 있다.
        sink.summon(p, { x: p.x, z: p.z }, e.count)
        break
      case 'field': {
        // ⚠️ 원본 복원: 여기는 `break` 뿐이라 **장판이 피해를 전혀 주지 않았다**.
        //    수치는 buildSpecial 이 이미 정해 놓은 것을 그대로 쓴다 (`room/fields.ts` 주석 참조).
        const damagePerTick = p.stats.dmg * e.damageMulPerTick * mul
        sink.addField(p, {
          x: p.x,
          z: p.z,
          radius: e.radius,
          damagePerTick,
          tickInterval: e.tickInterval,
          duration: e.duration,
        })
        sink.showArea({
          x: p.x,
          z: p.z,
          radius: e.radius,
          color: e.color,
          shape: 'field',
          duration: e.duration,
        })
        break
      }
      // 모션은 연출 계층이 받는다. 여기서 상태가 바뀔 것은 없다.
      case 'swing':
        break
    }
  }

  if (cast.toast) sink.toast(cast.toast)
  return cast
}
