/**
 * 게임 루프 — 모든 조각이 만나는 곳.
 *
 * ## 프레임 순서 (이 순서를 지킨다)
 * ```
 * 입력 수집 → 예측 이동 → 서버로 입력 전송 → 스냅샷 재조정
 *   → 원격 엔티티 보간 → 카메라 → FX → 렌더
 * ```
 * 예측을 전송보다 **먼저** 하는 이유: 화면이 입력에 즉시 반응해야 조작이 단단하게 느껴진다.
 *
 * ## 싱글도 같은 경로를 탄다
 * 싱글 전용 분기를 만들지 않는다. 혼자 하면 서버가 만든 1인짜리 방에 들어갈 뿐이다.
 */

import * as THREE from 'three'
import {
  ACTION,
  ANIM,
  CLASSES,
  COMBO,
  MOVE,
  TICK_S,
  autoAttackRange,
  classModsOf,
  distXZ,
  mobDef,
  isMobId,
} from '@bq/shared'
import type { ClampGates, ClassId, GameEvent, GateSave, MobSnapshot, PlayerSnapshot, ServerMsg } from '@bq/shared'
import type { ConnectionState } from './net/client'

import { createSceneKit, resizeSceneKit, setMood } from './render/artkit'
import type { SceneKit } from './render/artkit'
import { buildWorld, WorldStateBinder } from './render/world'
import type { WorldBuild } from './render/world'
import { FxSystem } from './render/fx'
import { makeChar, poseRig, coopPalette, PLAYER_PALETTE, isTrailWindow } from './render/character'
import type { Rig } from './render/character'
import { buildWeapon } from './render/weapons'
import { buildCreature, poseCreature, disposeCreature } from './render/creatures'
import { EXTERNAL_BUILDERS } from './render/creatures-external'
import { BossBar, BOSS_THEME } from './ui/bossbar'
import { Minimap } from './ui/minimap'
import { Hud, hudModelFrom, objectiveFor } from './ui/hud'
import { PanelStack } from './ui/panels'
import { CutscenePlayer } from './ui/cutscene'
import { Audio, SFX } from './audio/sound'
import { InputHub, DEFAULT_SETTINGS } from './input/state'
import type { InputState } from './input/state'
import { attachKeyboard } from './input/keyboard'
import { attachPointer, attachActionButtons, applyLook, applyZoom } from './input/pointer'
import type { CameraCtl } from './input/pointer'
import { GamepadAdapter } from './input/gamepad'
import { cameraRelativeMove, facingFromMove } from './input/camera-move'
import { NetClient, WsTransport } from './net/client'
import { LoopbackTransport } from './net/loopback'
import { Predictor } from './net/prediction'
import { InterpSet } from './net/interp'
import type { Transform } from './net/interp'
import { rememberRoom, roomFromUrl } from './storage'

type MobTransform = Transform & { readonly snap: MobSnapshot }
type PlayerTransform = Transform & { readonly snap: PlayerSnapshot }

export interface GameRefs {
  readonly canvas: HTMLCanvasElement
  readonly overlay: HTMLElement
  readonly panels: HTMLElement
  readonly cutscene: HTMLElement
  readonly bossbar: HTMLElement
  readonly minimap: HTMLCanvasElement
  readonly touch: HTMLElement
  readonly joyZone: HTMLElement
  readonly joy: HTMLElement
  readonly knob: HTMLElement
  readonly btnAttack: HTMLElement
  readonly btnJump: HTMLElement
  readonly btnSpecial: HTMLElement
}

export type NetMode = 'online' | 'solo'

export interface GameOptions {
  /** 비어 있으면 처음부터 루프백(혼자 하기)으로 시작한다. */
  readonly serverUrl: string
  readonly name: string
  readonly roomCode?: string
  /** false 면 서버에 못 붙어도 혼자 하기로 넘어가지 않는다 (초대 링크로 들어온 경우). */
  readonly soloFallback?: boolean
  /**
   * 접속할 때 서버에 보낼 저장 데이터를 만든다.
   * 매번 호출되므로 **그 순간의 최신 진행**을 돌려주면 된다.
   */
  readonly saveProvider?: () => unknown
}

export class Game {
  readonly kit: SceneKit
  readonly fx: FxSystem
  readonly hud: Hud
  readonly panels: PanelStack
  readonly cutscene: CutscenePlayer
  readonly audio = new Audio()
  readonly input: InputHub
  net: NetClient
  readonly bossBar: BossBar
  readonly minimap: Minimap

  private readonly refs: GameRefs
  private readonly predictor = new Predictor()
  private readonly pad: GamepadAdapter
  private readonly detach: Array<() => void> = []

  private world: WorldBuild | null = null
  private binder: WorldStateBinder | null = null

  private readonly cam: CameraCtl = { yaw: 0, pitch: 0.34, distance: DEFAULT_SETTINGS.cameraDistance }
  private readonly camPos = new THREE.Vector3()
  private readonly camTarget = new THREE.Vector3()

  /** 내 아바타. 서버가 확정한 좌표 대신 **예측 좌표**로 그린다. */
  private myRig: Rig | null = null
  private myWeapon: THREE.Object3D | null = null
  private myWeaponId = ''
  private walkPhase = 0

  /*
   * ── 공격 스윙 (예측) ──
   *
   * 서버가 "맞았다" 고 알려줄 때까지 기다리면 왕복 지연만큼 늦고,
   * **허공을 휘두르면 아무 모션도 안 나온다.** 원본은 누르는 즉시 휘둘렀다.
   * 그래서 이동과 같은 방식으로 **입력 즉시 로컬에서 재생**하고 서버가 판정만 한다.
   * 콤보 규칙은 `@bq/shared` 의 COMBO 를 그대로 쓴다 — 서버와 같은 표를 본다.
   */
  /** 남은 스윙 시간(초). 0 이면 휘두르는 중이 아니다. */
  private swingT = 0
  /** 이번 스윙의 전체 길이. 마무리 타는 더 길다. */
  private swingDur = 0
  private swingStep: 0 | 1 | 2 = 0
  private comboT = 0
  private attackCd = 0
  private attackAnim = 0
  /** 전투 자세 0..1. 급격히 바뀌면 어깨가 튀므로 보간해서 올린다. */
  private stance = 0
  private hurtAnim = 0
  private deadT = 0

  private readonly remoteRigs = new Map<number, { rig: Rig; slot: number }>()
  private readonly mobObjects = new Map<number, THREE.Object3D>()
  private readonly plates = new Map<number, Nameplate>()
  private readonly projectVec = new THREE.Vector3()
  private readonly trailA = new THREE.Vector3()
  private readonly trailB = new THREE.Vector3()
  private readonly playerInterp = new InterpSet<PlayerTransform>()
  private readonly mobInterp = new InterpSet<MobTransform>()

  private lastSnapshot: Extract<ServerMsg, { t: 'snapshot' }> | null = null
  private gates: GateSave = { slain: [], hv: false, ig: false, cc: false }
  /** 예측용 게이트. 서버 스냅샷의 `hv`/`ig` 를 clampWorld 가 읽는 모양으로 바꾼 것이다. */
  private clampGates: ClampGates = { heavenOpen: false, innerOpen: false }
  private paused = false
  private running = false
  private lastFrame = 0
  private playTime = 0
  private bossVisible: string | null = null
  /** 이미 지은 월드의 시드. 재접속 시 같은 방이면 다시 짓지 않는다. */
  private builtSeed = -1
  private minimapTick = 0

  onSnapshot: ((s: Extract<ServerMsg, { t: 'snapshot' }>) => void) | null = null
  onEvent: ((ev: GameEvent) => void) | null = null
  onReady: (() => void) | null = null

  constructor(refs: GameRefs, opts: GameOptions) {
    this.refs = refs
    this.kit = createSceneKit(refs.canvas)
    this.fx = new FxSystem(this.kit, refs.overlay)
    this.hud = new Hud()
    this.panels = new PanelStack(refs.panels)
    this.cutscene = new CutscenePlayer(refs.cutscene)
    this.bossBar = new BossBar(refs.bossbar)
    this.minimap = new Minimap(refs.minimap)
    this.input = new InputHub({ ...DEFAULT_SETTINGS })
    this.pad = new GamepadAdapter(this.input)

    // 패널이 하나라도 열려 있으면 게임은 멈춘다 (D-3).
    this.panels.onChange = (open) => {
      this.paused = open
    }

    const handlers = {
      onHello: (_id: number, roomCode: string, seed: number) => this.onHello(roomCode, seed),
      onSnapshot: (s: Extract<ServerMsg, { t: 'snapshot' }>) => this.applySnapshot(s),
      onEvent: (ev: GameEvent) => this.handleEvent(ev),
      onState: (st: ConnectionState) => this.showNetState(st),
    }

    // 서버 주소가 없거나 초대 코드 없이 혼자 시작하면 루프백으로 간다.
    // 서버가 있으면 붙어 보고, 못 붙으면 아래 `fallbackToSolo` 가 받는다.
    const wantsOnline = opts.serverUrl !== '' 
    this.transport = wantsOnline ? new WsTransport(opts.serverUrl) : new LoopbackTransport()
    this.mode = wantsOnline ? 'online' : 'solo'
    this.net = new NetClient(this.transport, handlers)
    this.handlers = handlers
    this.joinName = opts.name
    this.joinRoom = opts.roomCode ?? roomFromUrl() ?? undefined
    this.allowSolo = opts.soloFallback !== false

    if (opts.saveProvider) this.net.saveProvider = opts.saveProvider

    this.attachInput()
    this.connectNow()
  }

  private readonly handlers: {
    onHello: (id: number, roomCode: string, seed: number) => void
    onSnapshot: (s: Extract<ServerMsg, { t: 'snapshot' }>) => void
    onEvent: (ev: GameEvent) => void
    onState: (st: ConnectionState) => void
  }
  private transport: WsTransport | LoopbackTransport
  private joinName: string
  private joinRoom: string | undefined
  /** 온라인이면 진짜 서버, 솔로면 브라우저 안 루프백. */
  mode: NetMode
  private soloFallbackTimer: ReturnType<typeof setTimeout> | null = null
  private allowSolo = true

  private connectNow(): void {
    this.transport.connect()
    this.net.join(this.joinName, this.joinRoom)

    // 서버가 살아 있지 않으면 기다리게 두지 않는다. 정적 호스팅에 서버 없이
    // 올라간 경우가 정확히 이 경로다 — 잠깐 시도하고 혼자 하기로 넘어간다.
    if (this.mode === 'online') {
      this.soloFallbackTimer = setTimeout(() => {
        if (this.world === null) this.fallbackToSolo()
      }, SOLO_FALLBACK_MS)
    }
  }

  /**
   * 서버에 못 붙었다. **같은 서버 코드를 브라우저에서 돌려** 혼자 하기로 넘어간다.
   *
   * 초대 코드를 들고 온 경우에는 넘어가지 않는다 — 친구 방에 가려던 사람을
   * 조용히 혼자 하기로 보내면 "왜 친구가 안 보이지" 가 된다.
   */
  private fallbackToSolo(): void {
    if (this.mode === 'solo') return
    if (!this.allowSolo) {
      this.hud.toast('친구 방에 연결할 수 없습니다 — 계속 시도합니다')
      return
    }
    this.mode = 'solo'
    this.net.close()
    this.transport = new LoopbackTransport()
    this.net = new NetClient(this.transport, this.handlers)
    this.connectNow()
    this.hud.toast('혼자 하기로 시작합니다')
  }

  private showNetState(st: ConnectionState): void {
    if (this.mode === 'solo') {
      this.hud.setNet('혼자 하기')
      return
    }
    this.hud.setNet(
      st === 'open' ? '접속됨' : st === 'connecting' ? '접속 중…' : '연결 끊김',
      this.net.roomCode || undefined,
    )
  }

  /* ────────────────────────── 초기화 ────────────────────────── */

  /**
   * 서버가 방을 배정했다. **재접속 시에도 다시 온다** — 월드를 두 번 짓지 않도록 막는다.
   * 같은 방으로 돌아왔으면 지형이 그대로이므로 재사용하고,
   * 다른 방이면(원래 방이 파기된 경우) 새로 짓는다.
   */
  private onHello(roomCode: string, seed: number): void {
    if (this.soloFallbackTimer !== null) {
      clearTimeout(this.soloFallbackTimer)
      this.soloFallbackTimer = null
    }
    rememberRoom(roomCode)
    if (this.world && this.builtSeed === seed) {
      this.hud.toast('다시 연결됐다')
      return
    }
    if (this.world) {
      this.kit.scene.remove(this.world.root)
      this.resetEntities()
    }
    this.world = buildWorld(this.kit, seed)
    this.builtSeed = seed
    this.binder = new WorldStateBinder(this.world)
    if (!this.myRig) {
      this.myRig = makeChar(PLAYER_PALETTE)
      this.kit.scene.add(this.myRig.root)
    }
    this.onReady?.()
    if (!this.running) this.start()
  }

  /** 방이 바뀌면 남의 아바타·몹·보간 버퍼를 전부 버린다. 안 그러면 유령이 남는다. */
  private resetEntities(): void {
    for (const [, entry] of this.remoteRigs) this.kit.scene.remove(entry.rig.root)
    this.remoteRigs.clear()
    for (const [, obj] of this.mobObjects) {
      this.kit.scene.remove(obj)
      disposeCreature(obj)
    }
    this.mobObjects.clear()
    for (const [, plate] of this.plates) plate.root.remove()
    this.plates.clear()
    this.playerInterp.clear()
    this.mobInterp.clear()
  }

  private attachInput(): void {
    this.detach.push(attachKeyboard(this.input))
    this.detach.push(
      attachPointer(
        this.input,
        {
          joyZone: this.refs.joyZone,
          joy: this.refs.joy,
          knob: this.refs.knob,
          surface: this.refs.canvas,
        },
        this.cam,
      ),
    )
    this.detach.push(
      attachActionButtons(this.input, {
        attack: this.refs.btnAttack,
        jump: this.refs.btnJump,
        special: this.refs.btnSpecial,
      }),
    )
    this.detach.push(this.pad.attach())

    // 터치 기기면 조작 UI 를 띄운다. **화면 크기가 아니라 입력 장치로 판별한다.**
    const touchable = 'ontouchstart' in window || navigator.maxTouchPoints > 0
    if (touchable) this.refs.touch.classList.remove('hidden')
    this.input.onDeviceChange = (d) => {
      this.refs.touch.classList.toggle('hidden', d === 'gamepad')
      this.hud.setHelp(helpFor(d))
    }
    this.hud.setHelp(helpFor(touchable ? 'touch' : 'keyboard'))

    const onResize = (): void => {
      resizeSceneKit(this.kit, window.innerWidth, window.innerHeight, window.devicePixelRatio)
    }
    window.addEventListener('resize', onResize)
    window.addEventListener('orientationchange', onResize)
    onResize()
    this.detach.push(() => {
      window.removeEventListener('resize', onResize)
      window.removeEventListener('orientationchange', onResize)
    })

    // 첫 입력에서 오디오를 깨운다 (브라우저 정책).
    const unlock = (): void => this.audio.unlock()
    window.addEventListener('pointerdown', unlock, { once: true })
    window.addEventListener('keydown', unlock, { once: true })
  }

  /* ────────────────────────── 루프 ────────────────────────── */

  start(): void {
    if (this.running) return
    this.running = true
    this.lastFrame = performance.now()
    requestAnimationFrame(this.frame)
  }

  stop(): void {
    this.running = false
    if (this.soloFallbackTimer !== null) clearTimeout(this.soloFallbackTimer)
    for (const off of this.detach) off()
    this.detach.length = 0
    this.net.close()
    this.fx.dispose()
  }

  private readonly frame = (now: number): void => {
    if (!this.running) return
    requestAnimationFrame(this.frame)

    const rawDt = Math.min(0.05, (now - this.lastFrame) / 1000)
    this.lastFrame = now

    // 컷신은 게임이 멈춰 있어도 진행한다.
    this.cutscene.update(rawDt)

    // 히트스톱이 적용된 dt. 타격 순간 시간이 늘어붙는 감각(V1)이 여기서 나온다.
    const dt = this.fx.update(rawDt)

    const input = this.input.consume()
    this.pad.poll()
    this.handleUiCommands(input)

    if (!this.paused && !this.cutscene.playing) {
      this.playTime += rawDt
      this.tickLocal(input, dt)
    }

    this.binder?.update(rawDt)
    this.updateRemote(now)
    this.updateCamera(dt)
    // 미니맵은 8프레임마다 그린다 (원본과 같다). 매 프레임 그리면 60fps 를 갉아먹는다.
    if ((this.minimapTick = (this.minimapTick + 1) % 8) === 0) this.drawMinimap()
    this.kit.renderer.render(this.kit.scene, this.kit.camera)
  }

  private handleUiCommands(input: InputState): void {
    for (const cmd of input.ui) {
      switch (cmd) {
        case 'menu':
          // ESC: 열린 패널이 있으면 최상단만 닫고, 없으면 일시정지 메뉴를 연다 (D-3).
          if (!this.panels.closeTop()) this.openPause?.()
          break
        case 'tree':
          this.openTree?.()
          break
        case 'shop':
          this.openShop?.()
          break
        case 'map':
          // FR-7.9 전체 지도. 미니맵이 지원하면 켠다.
          if ('toggleFull' in this.minimap) {
            ;(this.minimap as unknown as { toggleFull(): void }).toggleFull()
          }
          break
        case 'autoAttack':
          this.input.settings.autoAttack = !this.input.settings.autoAttack
          this.hud.toast(`자동 공격 ${this.input.settings.autoAttack ? '켬' : '끔'}`)
          break
        case 'cameraReset':
          this.cam.pitch = 0.34
          break
      }
    }
  }

  /** 패널 열기 콜백 — main.ts 가 채운다 (패널이 게임 상태를 알아야 하기 때문). */
  openPause: (() => void) | null = null
  openTree: (() => void) | null = null
  openShop: (() => void) | null = null

  private tickLocal(input: InputState, dt: number): void {
    applyLook(this.cam, input.look.dx, input.look.dy)
    if (input.zoom !== 0) applyZoom(this.cam, input.zoom)

    const me = this.me
    if (!me) return

    // 이동 입력은 **카메라 상대**다 — 화면 위쪽이 전진이다.
    // 변환은 순수 함수로 떼어 두었다 (부호를 잃어버리기 쉬운 곳이라 테스트가 붙어 있다).
    const move = cameraRelativeMove(input.move, this.cam.yaw)
    const mx = move.x
    const mz = move.z

    let actions = 0
    if (input.attack || this.shouldAutoAttack()) actions |= ACTION.ATTACK
    if (input.jump) actions |= ACTION.JUMP
    if (input.special) actions |= ACTION.SPECIAL
    if (input.run) actions |= ACTION.RUN

    const moving = Math.hypot(mx, mz) > MOVE.inputDeadzone
    const yaw = moving ? facingFromMove(move) : (this.myRig?.root.rotation.y ?? 0)

    const frame = { dt: TICK_S, moveX: mx, moveZ: mz, yaw, actions }
    const seq = this.net.sendInput(frame)

    // 서버가 쓸 것과 같은 속도로 로컬 예측을 돌린다.
    this.predictor.apply({ ...frame, seq }, this.currentSpeed(input), this.clampGates)

    // 애니메이션
    this.walkPhase += dt * 11 * (moving ? 1 : 0) * (input.run ? 1.65 : 1)
    if (this.attackCd > 0) this.attackCd -= dt
    if (this.comboT > 0) this.comboT -= dt
    if (this.swingT > 0) this.swingT -= dt

    // 전투 자세 — 원본은 적이 10칸 안에 있으면 자세를 잡았다 (6060).
    // 휘두르는 중에도 자세로 친다: 허공을 베더라도 몸은 이미 싸우는 자세다.
    const wantStance = this.swingT > 0 || this.enemyNear(STANCE_RANGE) ? 1 : 0
    this.stance += (wantStance - this.stance) * Math.min(1, dt * STANCE_RATE)
    if (this.attackAnim > 0) this.attackAnim -= dt
    if (this.hurtAnim > 0) this.hurtAnim -= dt

    // 누른 순간 휘두른다. 맞았는지는 서버가 정하지만, 휘두르는 것은 내 몸이다.
    if ((actions & ACTION.ATTACK) !== 0 && this.attackCd <= 0 && !(me.anim & ANIM.DEAD)) {
      this.startSwing()
    }
    this.deadT = me.hp <= 0 ? this.deadT + dt : 0

    const rig = this.myRig
    if (rig) {
      rig.root.position.set(this.predictor.state.x, me.y, this.predictor.state.z)
      rig.root.rotation.y = yaw
      poseRig(rig, {
        walkPhase: this.walkPhase,
        speed01: moving ? 1 : 0,
        airborne: (me.anim & (1 << 2)) !== 0,
        attackT: this.swingT > 0 ? 1 - this.swingT / this.swingDur : 0,
        comboStep: this.swingStep,
        hurtT: this.hurtAnim,
        dead: me.hp <= 0,
        run01: input.run ? 1 : 0,
        stance: this.stance,
        time: this.playTime,
        vy: 0,
        deadT: this.deadT,
      })
      this.syncWeapon(me.weaponId, me.classId)
      this.updateBladeTrail()
    }
  }

  /**
   * 스윙 하나를 시작한다. 서버 `playerAttack` 의 콤보 규칙을 그대로 따른다:
   * 0.9초 안에 이어치면 3타가 순환하고, 3타(마무리)는 더 길고 쿨도 길다.
   *
   * 쿨타임에 `cdB`(공격속도 스킬·무기)를 못 곱한다 — 파생 스탯은 스냅샷에 없다.
   * 연출 타이밍이 실제 쿨보다 조금 짧을 수 있지만, **피해 판정은 서버가 하므로**
   * 화면이 앞서 보일 뿐 유리해지지는 않는다.
   */
  private startSwing(): void {
    const finisher = this.comboT > 0 && this.swingStep === COMBO.FINISHER_INDEX
    this.swingStep = this.comboT > 0 ? (((this.swingStep + 1) % COMBO.LENGTH) as 0 | 1 | 2) : 0
    this.comboT = COMBO.WINDOW
    this.swingDur = finisher ? COMBO.SWING_FINISHER : COMBO.SWING_NORMAL
    this.swingT = this.swingDur
    this.attackCd = finisher ? COMBO.CD_FINISHER : COMBO.CD_NORMAL
    SFX.swing(this.audio)
  }

  /**
   * 칼날 궤적. 스윙의 가운데 구간(q 0.24~0.72)만 샘플링한다 —
   * 예비동작까지 그리면 뒤로 당기는 선이 남아 지저분해진다 (원본 6135).
   */
  private updateBladeTrail(): void {
    const rig = this.myRig
    if (!rig || this.swingT <= 0 || this.swingDur <= 0) return
    const q = 1 - this.swingT / this.swingDur
    if (!isTrailWindow(q)) return

    const slot = rig.weaponSlot
    slot.updateWorldMatrix(true, false)
    this.trailA.setFromMatrixPosition(slot.matrixWorld)
    // 무기는 손에서 로컬 +Y 로 뻗는다. 그 끝을 월드로 옮겨 두 점을 잡는다.
    this.trailB.set(0, BLADE_LENGTH, 0).applyMatrix4(slot.matrixWorld)
    this.fx.trail(this.trailA, this.trailB, TRAIL_COLOR)
  }

  /** 이 거리 안에 살아 있는 몹이 있는가. 전투 자세 판정에 쓴다. */
  private enemyNear(range: number): boolean {
    const snap = this.lastSnapshot
    const me = this.me
    if (!snap || !me) return false
    for (const m of snap.mobs) {
      if (distXZ({ x: me.x, y: 0, z: me.z }, { x: m.x, y: 0, z: m.z }) <= range) return true
    }
    return false
  }

  /** 지형·버프까지 반영한 현재 이동속도. **서버와 같은 값이어야 한다.** */
  private currentSpeed(input: InputState): number {
    const self = this.lastSnapshot?.self
    const me = this.me
    if (!me) return MOVE.baseSpeed
    const cls = me.classId && isClassId(me.classId) ? classModsOf(me.classId) : null
    let speed = MOVE.baseSpeed * (cls?.spdMul ?? 1)
    if (input.run) speed *= MOVE.sprintMul
    if ((self?.slowT ?? 0) > 0) speed *= 0.45
    return speed
  }

  private shouldAutoAttack(): boolean {
    if (!this.input.settings.autoAttack) return false
    const me = this.me
    if (!me || !this.lastSnapshot) return false
    const cls = me.classId && isClassId(me.classId) ? CLASSES[me.classId] : null
    for (const m of this.lastSnapshot.mobs) {
      const def = isMobId(m.type) ? mobDef(m.type) : null
      if (!def) continue
      const range = autoAttackRange(cls?.ranged === true, 0, def.scale)
      if (distXZ({ x: me.x, y: 0, z: me.z }, { x: m.x, y: 0, z: m.z }) <= range) return true
    }
    return false
  }

  private syncWeapon(weaponId: string, classId: string | null): void {
    const rig = this.myRig
    if (!rig || weaponId === this.myWeaponId) return
    this.myWeaponId = weaponId
    if (this.myWeapon) {
      rig.weaponSlot.remove(this.myWeapon)
      this.myWeapon = null
    }
    const show = classId ? CLASSES[classId as ClassId]?.showWeapon !== false : true
    if (!show) return
    const w = buildWeapon(weaponId as never, classId ? { classId } : {})
    rig.weaponSlot.add(w)
    this.myWeapon = w
  }

  /* ────────────────────────── 서버 반영 ────────────────────────── */

  private applySnapshot(s: Extract<ServerMsg, { t: 'snapshot' }>): void {
    this.lastSnapshot = s
    this.gates = s.gates
    this.clampGates = { heavenOpen: s.gates.hv, innerOpen: s.gates.ig }
    this.binder?.apply(s.gates)

    const me = s.players.find((p) => p.id === this.net.playerId)
    if (me) {
      this.predictor.reconcile(me.x, me.z, s.ackSeq, this.clampGates)
      this.hud.update(hudModelFrom(s.self, me))
      this.hud.setObjective(
        objectiveFor({
          lords: s.gates.slain.filter((x) => x !== 'gabriel' && x !== 'creator').length,
          heavenOpen: s.gates.hv,
          gabrielKilled: s.gates.slain.includes('gabriel'),
          creatorKilled: s.gates.cc,
          level: me.level,
          hasClass: me.classId !== null,
        }),
      )
      if (me.classId === 'boss') setMood(this.kit, 'boss')
    }

    const now = performance.now()
    const seen = new Set<number>()
    for (const p of s.players) {
      if (p.id === this.net.playerId) continue
      seen.add(p.id)
      this.playerInterp.push(p.id, { x: p.x, y: p.y, z: p.z, yaw: p.yaw, snap: p }, now)
      this.ensureRemoteRig(p)
    }
    this.playerInterp.retain(seen)
    for (const [id, entry] of this.remoteRigs) {
      if (seen.has(id)) continue
      this.kit.scene.remove(entry.rig.root)
      this.remoteRigs.delete(id)
    }

    const mobSeen = new Set<number>()
    for (const m of s.mobs) {
      mobSeen.add(m.id)
      this.mobInterp.push(m.id, { x: m.x, y: m.y, z: m.z, yaw: m.yaw, snap: m }, now)
    }
    this.mobInterp.retain(mobSeen)
    for (const [id, obj] of this.mobObjects) {
      if (mobSeen.has(id)) continue
      this.kit.scene.remove(obj)
      disposeCreature(obj)
      this.mobObjects.delete(id)
    }

    this.updateBossBar(s)
    this.onSnapshot?.(s)
  }

  private ensureRemoteRig(p: PlayerSnapshot): void {
    if (this.remoteRigs.has(p.id)) return
    const slot = this.remoteRigs.size + 1
    const rig = makeChar(coopPalette(slot))
    this.kit.scene.add(rig.root)
    this.remoteRigs.set(p.id, { rig, slot })
  }

  private updateRemote(now: number): void {
    this.updateMobs(now)
    for (const [id, entry] of this.remoteRigs) {
      const t = this.playerInterp.sample(id, now)
      if (!t) continue
      entry.rig.root.position.set(t.x, t.y, t.z)
      entry.rig.root.rotation.y = t.yaw
      const moving = (t.snap.anim & 1) !== 0
      poseRig(entry.rig, {
        walkPhase: now / 90,
        speed01: moving ? 1 : 0,
        airborne: (t.snap.anim & (1 << 2)) !== 0,
        attackT: (t.snap.anim & (1 << 3)) !== 0 ? 0.5 : 0,
        comboStep: 0,
        hurtT: 0,
        dead: (t.snap.anim & (1 << 5)) !== 0,
      })
    }
  }

  /**
   * 몹 메시를 스냅샷에 맞춘다.
   *
   * 서버가 보낸 좌표를 **보간해서** 그린다 (100 ms 뒤를 렌더한다).
   * 20 Hz 스냅샷을 그대로 찍으면 몹이 뚝뚝 끊긴다.
   */
  private updateMobs(now: number): void {
    const snap = this.lastSnapshot
    if (!snap) return

    for (const m of snap.mobs) {
      let obj = this.mobObjects.get(m.id)
      if (!obj) {
        // 사람형 몹과 천국 주민은 creatures.ts 소관이 아니라 빌더를 주입해야 한다.
        obj = buildCreature(m.type, { external: EXTERNAL_BUILDERS })
        this.kit.scene.add(obj)
        this.mobObjects.set(m.id, obj)
      }
      const t = this.mobInterp.sample(m.id, now)
      if (!t) continue
      obj.position.set(t.x, t.y, t.z)
      obj.rotation.y = t.yaw
      poseCreature(obj as THREE.Group, {
        walkPhase: now / 120,
        moving: true,
        attackT: 0,
        hurtT: 0,
        time: now / 1000,
      })
    }
    this.updateNameplates(snap)
  }

  /**
   * 몹 이름표 + HP 바. 원본과 같이 **거리 60 안**만 그리고 화면 밖은 숨긴다.
   * DOM 요소를 매 프레임 새로 만들지 않고 재사용한다.
   */
  private updateNameplates(snap: Extract<ServerMsg, { t: 'snapshot' }>): void {
    const me = snap.players.find((p) => p.id === this.net.playerId)
    if (!me) return
    const seen = new Set<number>()

    for (const m of snap.mobs) {
      const d = distXZ({ x: me.x, y: 0, z: me.z }, { x: m.x, y: 0, z: m.z })
      if (d > NAMEPLATE_RANGE) continue
      const def = isMobId(m.type) ? mobDef(m.type) : null
      if (!def) continue
      // 보스는 전용 체력바가 따로 있으니 이름표를 겹치지 않는다.
      if (def.boss) continue

      seen.add(m.id)
      let plate = this.plates.get(m.id)
      if (!plate) {
        plate = makePlate()
        this.refs.overlay.appendChild(plate.root)
        this.plates.set(m.id, plate)
      }
      const p = this.projectPoint(m.x, m.y + def.scale * 2.6, m.z)
      if (!p) {
        plate.root.style.display = 'none'
        continue
      }
      plate.root.style.display = ''
      plate.root.style.transform = `translate(${p.x}px, ${p.y}px) translate(-50%, -100%)`
      if (plate.name !== def.name) {
        plate.label.textContent = `${def.name} Lv${def.lv}`
        plate.name = def.name
      }
      plate.fill.style.transform = `scaleX(${Math.max(0, m.hp / m.maxHp)})`
    }

    for (const [id, plate] of this.plates) {
      if (seen.has(id)) continue
      plate.root.remove()
      this.plates.delete(id)
    }
  }

  private drawMinimap(): void {
    const snap = this.lastSnapshot
    const me = this.me
    if (!snap || !me) return
    this.minimap.render({
      self: { x: this.predictor.state.x, z: this.predictor.state.z, yaw: this.cam.yaw },
      others: snap.players.filter((p) => p.id !== me.id).map((p) => ({ x: p.x, z: p.z })),
      mobs: snap.mobs.map((m) => {
        const def = isMobId(m.type) ? mobDef(m.type) : null
        return {
          x: m.x,
          z: m.z,
          boss: def?.boss === true,
          world: def?.world === true,
        }
      }),
      gates: { heavenOpen: snap.gates.hv },
    })
  }

  /** 월드 좌표를 화면 좌표로. 카메라 뒤면 null. */
  private projectPoint(x: number, y: number, z: number): { x: number; y: number } | null {
    this.projectVec.set(x, y, z).project(this.kit.camera)
    if (this.projectVec.z > 1) return null
    return {
      x: (this.projectVec.x * 0.5 + 0.5) * window.innerWidth,
      y: (-this.projectVec.y * 0.5 + 0.5) * window.innerHeight,
    }
  }

  private updateBossBar(s: Extract<ServerMsg, { t: 'snapshot' }>): void {
    const me = s.players.find((p) => p.id === this.net.playerId)
    if (!me) return
    let nearest: MobSnapshot | null = null
    let bestD = 60
    for (const m of s.mobs) {
      if (!isMobId(m.type) || !mobDef(m.type).boss) continue
      const d = distXZ({ x: me.x, y: 0, z: me.z }, { x: m.x, y: 0, z: m.z })
      if (d < bestD) {
        bestD = d
        nearest = m
      }
    }
    if (!nearest) {
      if (this.bossVisible) {
        this.bossBar.hide()
        this.audio.stopBgm()
        this.bossVisible = null
      }
      return
    }
    if (this.bossVisible !== nearest.type) {
      this.bossVisible = nearest.type
      const def = isMobId(nearest.type) ? mobDef(nearest.type) : null
      this.bossBar.show(def?.name ?? '보스', BOSS_THEME[nearest.type] ?? 'dark')
      void this.audio.playBgm(nearest.type === 'creator' ? 'creator' : 'boss')
    }
    this.bossBar.setHp(nearest.hp, nearest.maxHp)
    this.bossBar.setInvulnerable(nearest.invuln)
  }

  private handleEvent(ev: GameEvent): void {
    switch (ev.k) {
      case 'damage':
        if (ev.isMob) {
          // 스윙은 이미 로컬에서 돌고 있다. 여기서는 **맞았을 때만 나는 것**을 얹는다.
          this.fx.hitstop(ev.crit ? 0.085 : 0.05)
          this.fx.shake(ev.crit ? 0.3 : 0.16)
          ev.crit ? SFX.crit(this.audio) : SFX.hit(this.audio)
          if (ev.crit) this.input.vibrate(12)
        } else if (ev.targetId === this.net.playerId) {
          this.hurtAnim = 0.3
          this.fx.shake(0.24)
          SFX.hurt(this.audio)
          this.input.vibrate(25)
        }
        break
      case 'levelUp':
        if (ev.playerId === this.net.playerId) {
          SFX.levelUp(this.audio)
          this.hud.toast(`Lv ${ev.level}`)
        }
        break
      case 'runeLit':
        this.hud.toast(`자물쇠 ${ev.count} / 3`)
        SFX.gate(this.audio)
        break
      case 'cutsceneStart':
        void this.cutscene.play('gate')
        break
      case 'gateOpened':
        this.hud.toast('문이 열렸다')
        break
      case 'sealBroken':
        void this.cutscene.play('seal')
        break
      case 'bossKilled':
        if (ev.bossId === 'creator') void this.cutscene.play('ending', { force: true })
        break
      case 'loot':
        if (ev.to.includes(this.net.playerId)) this.hud.toast('새 무기를 얻었다')
        break
      case 'toast':
        this.hud.toast(ev.text)
        break
      case 'chat':
        this.hud.toast(`${ev.name}: ${ev.text}`, 3500)
        break
      case 'joined':
        if (ev.playerId !== this.net.playerId) this.hud.toast(`${ev.name} 님이 들어왔다`)
        break
      case 'left':
        this.hud.toast('한 명이 나갔다')
        break
      case 'aoe':
        // 서버가 준 값을 손대지 않고 그대로 넘긴다. 여기서 보정하면 보이는 범위와 맞는 범위가 갈린다.
        this.fx.areaHit({
          x: ev.x,
          z: ev.z,
          radius: ev.radius,
          color: ev.color,
          shape: ev.shape,
          yaw: ev.yaw,
          halfAngle: ev.halfAngle,
          duration: ev.duration,
        })
        break
      case 'shockwave':
        this.fx.ring(new THREE.Vector3(ev.x, 0.2, ev.z), ev.radius, 0x7fc6ff)
        break
      default:
        break
    }
    this.onEvent?.(ev)
  }

  /* ────────────────────────── 카메라 ────────────────────────── */

  private updateCamera(dt: number): void {
    const me = this.me
    const x = this.predictor.state.x
    const z = this.predictor.state.z
    const y = me?.y ?? 0

    // 원본 6424–6428 과 **같은 식**이다. 캐릭터 리그가 4.5유닛이라 시선 높이 2.6 이
    // 눈높이에 해당한다 — 1.6 으로 낮추면 캐릭터가 화면을 가득 채운다.
    this.camTarget.set(x, y + CAM_TARGET_Y, z)
    // 세로 화면은 가로 시야가 좁아 캐릭터가 화면을 가득 채운다.
    // 종횡비에 맞춰 거리를 늘려 준다 (docs/04 §3.4 — 세로 전용 레이아웃).
    const d = this.input.settings.cameraDistance * portraitZoomOut(this.kit.camera.aspect)
    this.cam.distance += (d - this.cam.distance) * Math.min(1, dt * 6)

    const cp = Math.cos(this.cam.pitch)
    this.camPos.set(
      this.camTarget.x - Math.sin(this.cam.yaw) * cp * this.cam.distance,
      Math.max(CAM_MIN_Y, this.camTarget.y + Math.sin(this.cam.pitch) * this.cam.distance),
      this.camTarget.z - Math.cos(this.cam.yaw) * cp * this.cam.distance,
    )
    this.kit.camera.position.lerp(this.camPos, Math.min(1, dt * 11))
    this.kit.camera.lookAt(this.camTarget)

    // 태양이 플레이어를 따라간다 — 그림자 맵 범위를 좁게 유지하려는 원본의 수법이다.
    this.kit.sun.position.set(x + 30, 55, z + 20)
    this.kit.sun.target.position.set(x, 0, z)
    this.kit.sun.target.updateMatrixWorld()
  }

  get me(): PlayerSnapshot | undefined {
    return this.lastSnapshot?.players.find((p) => p.id === this.net.playerId)
  }

  get selfState(): Extract<ServerMsg, { t: 'snapshot' }>['self'] | undefined {
    return this.lastSnapshot?.self
  }

  get elapsed(): number {
    return this.playTime
  }

  get gateState(): GateSave {
    return this.gates
  }
}

/**
 * 세로 화면 보정 배수.
 *
 * 가로(16:9 ≈ 1.78)에서는 1 — 원본 그대로다.
 * 세로(9:19.5 ≈ 0.46)에서는 약 1.6배 멀어져 원본과 **같은 가로 시야**를 유지한다.
 * 거리 대신 FOV 를 건드리면 FOV 펀치(타격감 V1)와 싸우게 되므로 거리로 푼다.
 */
function portraitZoomOut(aspect: number): number {
  if (aspect >= 1.5) return 1
  return Math.min(1.75, 1.5 / Math.max(0.4, aspect))
}

/** 이 시간 안에 서버가 응답하지 않으면 혼자 하기로 넘어간다. */
const SOLO_FALLBACK_MS = 2500

/** 이 거리 안에 적이 있으면 전투 자세를 잡는다. 원본 6060. */
const STANCE_RANGE = 10
/** 자세가 붙고 풀리는 속도. 즉시 바뀌면 어깨가 튄다. */
const STANCE_RATE = 6

/** 손에서 칼끝까지의 거리. 궤적 두 점을 잡는 데만 쓴다. */
const BLADE_LENGTH = 1.7
/** 궤적 색. 흰빛이 어느 무기에나 어울린다. */
const TRAIL_COLOR = 0xdfe8f4

/** 카메라가 바라보는 지점의 높이. 원본 6424 `player.position.y + 2.6`. */
const CAM_TARGET_Y = 2.6
/** 카메라가 지면 아래로 내려가지 않게 하는 하한. 원본 6428 `Math.max(1.4, cy)`. */
const CAM_MIN_Y = 1.4

function isClassId(v: string): v is ClassId {
  return v in CLASSES
}

function helpFor(device: 'keyboard' | 'touch' | 'gamepad'): readonly string[] {
  switch (device) {
    case 'touch':
      return [
        '왼쪽 아래를 누른 채 움직여서 이동',
        '오른쪽을 끌면 카메라 · 톡 치면 공격',
        '공격 · 점프 · 특수기 버튼은 오른쪽 아래',
      ]
    case 'gamepad':
      return ['왼쪽 스틱 이동 · 오른쪽 스틱 카메라', 'X 공격 · A 점프 · B 특수기 · Y 스킬', 'Start 메뉴']
    default:
      return [
        'WASD 이동 · Shift 달리기 · Space 점프',
        '클릭 또는 F 공격 · Q 특수기 · T 스킬',
        'E 상점 · M 지도 · Tab 자동공격 · ESC 메뉴',
      ]
  }
}

/** 이름표를 그리는 거리 상한. 원본과 같은 값이다. */
const NAMEPLATE_RANGE = 60

interface Nameplate {
  readonly root: HTMLElement
  readonly label: HTMLElement
  readonly fill: HTMLElement
  name: string
}

function makePlate(): Nameplate {
  const root = document.createElement('div')
  root.className = 'nameplate'
  const label = document.createElement('div')
  const bar = document.createElement('div')
  bar.className = 'mobbar'
  const fill = document.createElement('i')
  bar.appendChild(fill)
  root.append(label, bar)
  return { root, label, fill, name: '' }
}
