/**
 * 일반 몹 전용 모델 8종 — 슬라임 · 박쥐 · 늑대 · 거미 · 원혼 · 용암 정령 · 해파리 · 얼음 정령.
 *
 * 원본 SSOT: `reference/blocky-rpg.html` 2481–2749.
 * 보스 4종은 `./creatures-boss`, 등록·후처리·포즈는 `./creatures` 가 맡는다.
 * 파일을 셋으로 나눈 것은 **800줄 상한** 때문이며 공용 캐시는 `./creature-kit` 하나뿐이다.
 *
 * ## 모든 빌더가 지키는 규약 (결함 D-8)
 * - **배율 1 로 조립한다.** 몹의 `scale` 은 `buildCreature()` 가 `Object3D.scale` 로 준다.
 *   원본 `t.make(t.scale)` 은 배율마다 새 지오메트리를 만들어 늑대 모델이 두 벌 존재했다.
 * - 지오메트리·재질은 반드시 `creature-kit` 헬퍼를 거친다. 직접 `new THREE.*Geometry` 금지 —
 *   캐시를 우회하면 몹이 늘어날 때마다 GPU 리소스가 늘어난다.
 * - 리그(`userData`)는 `CreatureRig` 로 채운다. 없는 관절은 `emptyPivot()` 이다 (원본 `EMPTY()`).
 *
 * 색·치수·비율은 원본 그대로다. 임의 조정 금지 (`CLAUDE.md` 작업 규칙).
 */

import * as THREE from 'three'
import {
  SIDES,
  blobMesh,
  castMesh,
  cone,
  coneGeo,
  dodecGeo,
  domeGeo,
  emptyPivot,
  glowMat,
  mesh,
  modelRng,
  octaGeo,
  put,
  rbox,
  rboxCast,
  rboxSolid,
  shapeGeo,
  sphere,
  stdMat,
  tmat,
} from './creature-kit'
import type { CreatureRig, OrbitChunk } from './creature-kit'
/* ══════════════════════════════════════════════════════════════════
   §1. 슬라임 — 원본 2481–2503
   ══════════════════════════════════════════════════════════════════ */

export function buildSlime(): THREE.Group {
  const g = new THREE.Group()
  const rnd = modelRng('slime')
  // 반투명 젤리 — 껍질과 물방울이 같은 재질을 쓴다.
  const skin = stdMat({
    color: 0x62c94a,
    roughness: 0.12,
    metalness: 0.05,
    opacity: 0.82,
    envMapIntensity: 2.0,
  })

  const body = blobMesh(1.5, skin, 0.16, 2.4, 22)
  body.scale.set(1, 0.78, 1)
  body.position.y = 1.2
  g.add(body)

  const core = blobMesh(0.55, tmat(0x2f7a24, null, 0.5, 0, 0x0f2a08), 0.1, 4, 12)
  core.position.y = 1.0
  g.add(core)

  for (const sd of SIDES) {
    put(g, sphere(0.24, tmat(0xf6f8fa, null, 0.2), 12, 9), sd * 0.42, 1.55, 1.12)
    put(g, sphere(0.12, tmat(0x121814, null, 0.15, 0.1), 10, 8), sd * 0.45, 1.53, 1.28)
  }
  // 몸에 붙어 떠다니는 물방울 4개
  for (let i = 0; i < 4; i++) {
    const d = sphere(0.1 + rnd() * 0.1, skin, 8, 6)
    const a = rnd() * 6.28
    put(g, d, Math.cos(a) * 1.2, 0.4 + rnd() * 1.4, Math.sin(a) * 1.2)
  }

  const rig: CreatureRig = {
    kind: 'slime',
    armL: emptyPivot(),
    armR: emptyPivot(),
    legL: emptyPivot(),
    legR: emptyPivot(),
    body,
    baseScale: 1,
    bob: 0,
  }
  g.userData = rig
  g.add(rig.armR)
  return g
}

/* ══════════════════════════════════════════════════════════════════
   §2. 핏빛 박쥐 — 원본 2505–2540
   ══════════════════════════════════════════════════════════════════ */

export function buildBat(): THREE.Group {
  const g = new THREE.Group()
  const C = 0x4a3358
  const C2 = 0x30203f
  const FUR = tmat(C, 'fur', 0.95)

  const body = blobMesh(0.52, FUR, 0.05, 6, 16)
  body.scale.set(1, 1.1, 1.25)
  body.position.y = 2.3
  g.add(body)
  put(g, blobMesh(0.38, FUR, 0.04, 8, 14), 0, 2.85, 0.3)

  const fang = cone(0.07, 0.24, 4, 0xffffff)
  fang.rotation.x = Math.PI
  put(g, fang, 0, 2.6, 0.58)

  const wingL = new THREE.Group()
  const wingR = new THREE.Group()
  const wingMat = stdMat({ color: C2, roughness: 0.72, opacity: 0.94, doubleSide: true })
  const RIB = tmat(C, null, 0.8)
  const wings: ReadonlyArray<readonly [THREE.Group, number]> = [
    [wingL, -1],
    [wingR, 1],
  ]
  for (const [w, sd] of wings) {
    put(g, w, sd * 0.4, 2.45, 0)
    const m1 = castMesh(
      shapeGeo(
        'batWing',
        () => {
          const sh = new THREE.Shape()
          sh.moveTo(0, 0)
          sh.bezierCurveTo(0.9, 0.7, 2.0, 0.5, 2.5, -0.1)
          sh.bezierCurveTo(1.9, -0.35, 1.6, -0.75, 1.2, -0.5)
          sh.bezierCurveTo(0.9, -0.9, 0.5, -0.6, 0, 0)
          return sh
        },
        12,
      ),
      wingMat,
    )
    m1.rotation.set(-Math.PI / 2, 0, sd < 0 ? Math.PI : 0)
    w.add(m1)
    for (let i = 0; i < 3; i++) {
      const rib = rbox(2.2, 0.06, 0.06, 0.02, RIB)
      rib.position.set(sd * 1.1, 0, -0.35 + i * 0.35)
      rib.rotation.y = sd * (0.1 - i * 0.16)
      w.add(rib)
    }
  }

  for (const sd of SIDES) {
    put(g, cone(0.15, 0.55, 5, C2), sd * 0.21, 3.24, 0.24)
    put(g, sphere(0.09, glowMat(0xe04b3a, 2.6), 10, 8), sd * 0.16, 2.9, 0.6)
    // ⚠️ 발만 rboxGeo 의 품질 인자를 생략해 고품질(seg 1)로 만든다 — 원본 2534 그대로.
    put(g, rbox(0.1, 0.4, 0.1, 0.04, tmat(C2, null, 0.85), 1), sd * 0.2, 1.75, -0.1)
  }

  const rig: CreatureRig = {
    kind: 'bat',
    armL: emptyPivot(),
    armR: emptyPivot(),
    legL: emptyPivot(),
    legR: emptyPivot(),
    wingL,
    wingR,
    baseScale: 1,
    bob: 0,
  }
  g.userData = rig
  g.add(rig.armR)
  return g
}

/* ══════════════════════════════════════════════════════════════════
   §3. 늑대 (서리 늑대 · 마그마 하운드) — 원본 2542–2569
   ══════════════════════════════════════════════════════════════════ */

export function buildWolf(): THREE.Group {
  const g = new THREE.Group()
  const C = 0x6a707c
  const C2 = 0x474d58
  const WT = 0xd8e2ea
  const FUR = tmat(C, 'fur', 0.97)
  const FUR2 = tmat(C2, 'fur', 0.97)
  const FURW = tmat(WT, 'fur', 0.97)
  const PAW = tmat(0x2a2e36, null, 0.8)
  /** 원본 내부 헬퍼 `BX` — 모서리 반지름은 가장 짧은 변의 30% 다. */
  const BX = (w: number, h: number, d: number, mat: THREE.Material) =>
    rboxSolid(w, h, d, Math.min(w, h, d) * 0.3, mat)

  const torso = blobMesh(1.0, FUR, 0.07, 4.5, 18)
  torso.scale.set(1.02, 1.0, 2.3)
  put(g, torso, 0, 1.55, -0.1)
  put(g, BX(0.9, 0.5, 2.0, FURW), 0, 1.14, -0.1)
  put(g, BX(0.85, 0.85, 0.8, FUR), 0, 1.95, 1.25)

  const head = blobMesh(0.5, FUR2, 0.05, 7, 14)
  head.scale.set(1, 0.92, 1.15)
  put(g, head, 0, 2.1, 1.85)
  put(g, BX(0.5, 0.44, 0.78, FUR), 0, 1.9, 2.45)
  put(g, sphere(0.14, tmat(0x14181e, null, 0.2, 0.1), 10, 8), 0, 1.98, 2.9)

  const tail = blobMesh(0.3, FUR2, 0.05, 8, 12)
  tail.scale.set(1, 1, 3.4)
  put(g, tail, 0, 1.85, -1.7).rotation.x = -0.55

  for (const sd of SIDES) {
    put(g, cone(0.22, 0.55, 5, C2), sd * 0.3, 2.68, 1.7)
    put(g, sphere(0.1, glowMat(0x8fe0ff, 2.4), 10, 8), sd * 0.28, 2.22, 2.3)
    // 등줄기 갈기 — 3개가 거의 같은 높이에 겹쳐 선다
    for (let i = 0; i < 3; i++) {
      put(g, cone(0.1, 0.3, 4, WT), sd * 0.1, 2.2 + i * 0.02, 0.6 - i * 0.6)
    }
  }

  const leg = (x: number, z: number): THREE.Group => {
    const q = new THREE.Group()
    q.position.set(x, 1.35, z)
    g.add(q)
    const l = BX(0.32, 1.3, 0.36, FUR2)
    l.position.y = -0.66
    q.add(l)
    const f = BX(0.38, 0.22, 0.52, PAW)
    f.position.set(0, -1.35, 0.1)
    q.add(f)
    return q
  }
  const fl = leg(-0.44, 0.95)
  const fr = leg(0.44, 0.95)
  const bl = leg(-0.44, -1.0)
  const br = leg(0.44, -1.0)

  // ⚠️ 원본 2567 은 `head` 를 리그에 넣지 않는다. animMob 의 `if(u.head)` 가 거짓이라
  //    늑대 머리는 공격 예고에 반응하지 않는다 — 원본 동작 그대로 둔다.
  const rig: CreatureRig = {
    kind: 'quad',
    armL: fl,
    armR: fr,
    legL: bl,
    legR: br,
    fl,
    fr,
    bl,
    br,
    baseScale: 1,
    bob: 0,
  }
  g.userData = rig
  return g
}

/* ══════════════════════════════════════════════════════════════════
   §4. 거대 거미 — 원본 2571–2599
   ══════════════════════════════════════════════════════════════════ */

export function buildSpider(): THREE.Group {
  const g = new THREE.Group()
  const SK = tmat(0x2e2636, 'fur', 0.9)
  const SK2 = tmat(0x191320, 'fur', 0.9)

  const abd = blobMesh(1.0, SK, 0.09, 3.6, 18)
  abd.scale.set(1, 0.85, 1.2)
  put(g, abd, 0, 1.5, -1.0)
  put(g, rbox(0.5, 0.1, 1.0, 0.04, tmat(0xc0442e, null, 0.6)), 0, 2.26, -1.0)
  put(g, blobMesh(0.62, SK2, 0.06, 6, 14), 0, 1.45, 0.35)

  // 눈 4개 — 좌우 2개씩, 안쪽이 위
  const EYE = glowMat(0xe04b3a, 2.8)
  for (let i = 0; i < 4; i++) {
    const sd = i < 2 ? -1 : 1
    put(g, sphere(0.1, EYE, 8, 6), sd * (0.16 + (i % 2) * 0.22), 1.68 - (i % 2) * 0.16, 0.82)
  }
  for (const sd of SIDES) {
    const f = cone(0.1, 0.45, 5, 0xd8d2c0)
    f.rotation.x = Math.PI * 0.85
    put(g, f, sd * 0.2, 1.05, 0.78)
  }

  const legs: THREE.Group[] = []
  for (let i = 0; i < 8; i++) {
    const sd = i < 4 ? -1 : 1
    const k = i % 4
    const q = new THREE.Group()
    q.position.set(sd * 0.45, 1.5, 0.7 - k * 0.42)
    q.rotation.y = sd * (0.5 - k * 0.32)
    g.add(q)
    const up = rboxCast(1.15, 0.14, 0.14, 0.06, SK)
    up.position.set(sd * 0.55, 0.3, 0)
    up.rotation.z = -sd * 0.5
    q.add(up)
    const dn = rbox(1.25, 0.11, 0.11, 0.05, SK2)
    dn.position.set(sd * 1.5, -0.35, 0)
    dn.rotation.z = sd * 0.85
    q.add(dn)
    legs.push(q)
  }

  const rig: CreatureRig = {
    kind: 'spider',
    armL: emptyPivot(),
    armR: emptyPivot(),
    legL: emptyPivot(),
    legR: emptyPivot(),
    legs,
    baseScale: 1,
    bob: 0,
  }
  g.userData = rig
  g.add(rig.armR)
  return g
}

/* ══════════════════════════════════════════════════════════════════
   §5. 원혼 (원혼 · 눈보라 망령) — 원본 2601–2623
   ══════════════════════════════════════════════════════════════════ */

export function buildGhost(): THREE.Group {
  const g = new THREE.Group()
  // `depthWrite:false` — 반투명끼리 겹칠 때 앞뒤가 튀지 않게 한다.
  const M = stdMat({
    color: 0xbfd8e8,
    roughness: 0.1,
    opacity: 0.5,
    emissive: 0x1c3040,
    envMapIntensity: 2.2,
    depthWrite: false,
  })
  const FACE = tmat(0x0c1016, null, 0.3)

  const body = blobMesh(0.92, M, 0.08, 3.2, 18)
  body.scale.set(1, 1.2, 1)
  body.position.y = 2.5
  g.add(body)

  // 아래로 늘어진 꼬리 5가닥
  for (let i = 0; i < 5; i++) {
    const tl = mesh(coneGeo(0.3, 1.1, 8), M)
    tl.rotation.x = Math.PI
    put(g, tl, (i - 2) * 0.38, 1.35, 0)
  }
  for (const sd of SIDES) {
    put(g, rbox(0.24, 0.34, 0.1, 0.06, FACE), sd * 0.3, 2.7, 0.8)
  }
  put(g, rbox(0.3, 0.4, 0.1, 0.08, FACE), 0, 2.2, 0.82)

  const armL = new THREE.Group()
  const armR = new THREE.Group()
  const arms: ReadonlyArray<readonly [THREE.Group, number]> = [
    [armL, -1],
    [armR, 1],
  ]
  for (const [arm, sd] of arms) {
    put(g, arm, sd * 0.86, 2.6, 0)
    const m = sphere(0.24, M, 10, 8)
    m.scale.set(1, 2.4, 1)
    m.position.y = -0.55
    arm.add(m)
  }

  const rig: CreatureRig = {
    kind: 'ghost',
    armL,
    armR,
    legL: emptyPivot(),
    legR: emptyPivot(),
    baseScale: 1,
    bob: 0,
  }
  g.userData = rig
  return g
}

/* ══════════════════════════════════════════════════════════════════
   §6. 용암 정령 (용암 정령 · 재의 정령) — 원본 2625–2642
   ══════════════════════════════════════════════════════════════════ */

export function buildLava(): THREE.Group {
  const g = new THREE.Group()
  const rnd = modelRng('lava')
  const core = blobMesh(0.75, tmat(0xff8a3a, null, 0.35, 0.1, 0xff4a00), 0.09, 4, 16)
  core.position.y = 2.3
  g.add(core)

  const ROCK = tmat(0x3a2018, 'rock', 0.96)
  const chunks: OrbitChunk[] = []
  for (let i = 0; i < 11; i++) {
    const w = 0.4 + rnd() * 0.55
    const c = castMesh(dodecGeo(w * 0.7), ROCK)
    const a = (i / 11) * Math.PI * 2
    const r = 1.0 + rnd() * 0.45
    const y = 1.1 + rnd() * 2.4
    put(g, c, Math.cos(a) * r, y, Math.sin(a) * r)
    chunks.push({ m: c, a, r, y })
  }
  for (const sd of SIDES) {
    put(g, sphere(0.15, glowMat(0xffd24a, 3.0), 10, 8), sd * 0.26, 2.7, 0.62)
  }

  const rig: CreatureRig = {
    kind: 'lava',
    armL: emptyPivot(),
    armR: emptyPivot(),
    legL: emptyPivot(),
    legR: emptyPivot(),
    chunks,
    core,
    baseScale: 1,
    bob: 0,
  }
  g.userData = rig
  g.add(rig.armR)
  return g
}

/* ══════════════════════════════════════════════════════════════════
   §7. 가시 해파리 — 원본 2705–2726
   ══════════════════════════════════════════════════════════════════ */

export function buildJelly(): THREE.Group {
  const g = new THREE.Group()
  const JEL = stdMat({
    color: 0x8fd8f0,
    roughness: 0.1,
    opacity: 0.5,
    emissive: 0x1a4a66,
    envMapIntensity: 2.2,
    depthWrite: false,
  })

  const dome = castMesh(domeGeo(1.15, 18, 12, Math.PI * 0.62), JEL)
  dome.scale.set(1, 0.95, 1)
  dome.position.y = 2.9
  g.add(dome)
  put(g, blobMesh(0.55, glowMat(0xff7ad0, 1.6), 0.06, 5, 12), 0, 2.7, 0)

  const tent: THREE.Group[] = []
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * 6.283
    const q = new THREE.Group()
    q.position.set(Math.cos(a) * 0.85, 2.75, Math.sin(a) * 0.85)
    g.add(q)
    const t1 = rbox(0.11, 1.5, 0.11, 0.05, JEL)
    t1.position.y = -0.75
    q.add(t1)
    const t2 = rbox(0.08, 1.2, 0.08, 0.035, JEL)
    t2.position.y = -2.0
    q.add(t2)
    tent.push(q)
  }

  const rig: CreatureRig = {
    kind: 'jelly',
    armL: emptyPivot(),
    armR: emptyPivot(),
    legL: emptyPivot(),
    legR: emptyPivot(),
    tent,
    dome,
    baseScale: 1,
    bob: 0,
  }
  g.userData = rig
  g.add(rig.armR)
  return g
}

/* ══════════════════════════════════════════════════════════════════
   §8. 얼음 정령 — 원본 2728–2749
   ══════════════════════════════════════════════════════════════════ */

export function buildIceElem(): THREE.Group {
  const g = new THREE.Group()
  const rnd = modelRng('iceElem')
  const ICE = stdMat({
    color: 0xa8dcf0,
    roughness: 0.1,
    metalness: 0.06,
    opacity: 0.82,
    envMapIntensity: 2.0,
  })

  const core = blobMesh(0.7, glowMat(0x9fe8ff, 2.0), 0.08, 4, 14)
  core.position.y = 2.3
  g.add(core)

  const chunks: OrbitChunk[] = []
  for (let i = 0; i < 10; i++) {
    const w = 0.45 + rnd() * 0.6
    const c = castMesh(octaGeo(w * 0.8), ICE)
    const a = (i / 10) * 6.283
    const r = 1.0 + rnd() * 0.5
    const y = 1.1 + rnd() * 2.4
    put(g, c, Math.cos(a) * r, y, Math.sin(a) * r)
    chunks.push({ m: c, a, r, y })
  }
  for (const sd of SIDES) {
    put(g, sphere(0.14, glowMat(0xdff4ff, 3.0), 10, 8), sd * 0.26, 2.66, 0.6)
  }

  // ⚠️ 원본 2746 도 `kind:'lava'` 다 — 얼음 정령은 용암 정령의 궤도 애니메이션을 그대로 쓴다.
  const rig: CreatureRig = {
    kind: 'lava',
    armL: emptyPivot(),
    armR: emptyPivot(),
    legL: emptyPivot(),
    legR: emptyPivot(),
    chunks,
    core,
    baseScale: 1,
    bob: 0,
  }
  g.userData = rig
  g.add(rig.armR)
  return g
}

