/**
 * 북쪽 성벽 — 원본 `reference/blocky-rpg.html` 1221–1284.
 *
 * 문 좌우로 맵 끝(`±252`)까지 이어진다. 문과 **같은 z**(`RAMPART_MESH_Z = GATE_MESH.z`)에 서므로
 * 성벽 메시도 물리 벽보다 4 뒤에 있다 — 플레이어는 벽에 닿기 전에 `WALL_PHYSICS_Z` 에서 멈춘다 (G5).
 */

import * as THREE from 'three'
import {
  RAMPART_MESH_Z,
  RAMPART_GAP,
  RAMPART_END,
  RAMPART_H,
  RAMPART_SEG,
  RAMPART_COLLIDER_R,
  RAMPART_TOWER_START,
  RAMPART_TOWER_STEP,
  RAMPART_TOWER_COLLIDER_R,
  RAMPART_SHOULDER_X,
  RAMPART_SHOULDER_COLLIDER_R,
} from '@bq/shared'
import { rboxGeo, TM, GLOW } from '../artkit'
import { TAU, add, cone, cyl, sphere } from './kit'
import type { Collider } from './kit'

/** 구획 폭 여유 / 중심 보정. 이음매를 겹쳐 틈이 보이지 않게 하는 값이다 (원본 1235–1236). */
const SEG_OVERLAP = 0.6
const SEG_SHIFT = 0.3

/** 벽체 · 망루 · 어깨벽. */
export function buildRampart(): { group: THREE.Group; colliders: Collider[] } {
  const group = new THREE.Group()
  const colliders: Collider[] = []
  const STONE = TM(0x6e6659, 'rock', 0.93)
  const STONE2 = TM(0x554e43, 'rock', 0.95)
  const TRIM = TM(0x8a8172, 'rock', 0.86)
  const GOLD = TM(0xd9b04a, 'metal', 0.32, 0.85)
  const LAMP = GLOW(0xffc76a, 2.0)
  const Z = RAMPART_MESH_Z
  const H = RAMPART_H

  for (const side of [-1, 1] as const) {
    /* 벽체 구획 */
    for (let x = RAMPART_GAP; x < RAMPART_END; x += RAMPART_SEG) {
      const w = Math.min(RAMPART_SEG, RAMPART_END - x) + SEG_OVERLAP
      const cx = side * (x + w / 2 - SEG_SHIFT)

      const wall = new THREE.Mesh(rboxGeo(w, H, 5.0, 0.3, 0), STONE)
      wall.position.set(cx, H / 2, Z)
      add(group, wall, true, true)

      const base = new THREE.Mesh(rboxGeo(w + 1.4, 2.6, 6.6, 0.3, 0), STONE2)
      base.position.set(cx, 1.3, Z)
      add(group, base, false, true)

      /* 총안 — 한 칸 걸러 하나 */
      if (Math.round(x / RAMPART_SEG) % 2 === 0) {
        const cr = new THREE.Mesh(rboxGeo(w * 0.52, 2.6, 5.4, 0.2, 0), TRIM)
        cr.position.set(cx, H + 1.3, Z)
        add(group, cr, true)
      }
      /* 안쪽 통로 난간 */
      const walk = new THREE.Mesh(rboxGeo(w, 0.6, 2.2, 0.2, 0), TRIM)
      walk.position.set(cx, H + 0.3, Z + 3.2)
      add(group, walk)

      /* 구획마다 충돌체 2개를 겹친다 — 1개만 두면 사이로 빠져나간다 (원본 주석) */
      colliders.push({ x: cx - w * 0.25, z: Z, r: RAMPART_COLLIDER_R })
      colliders.push({ x: cx + w * 0.25, z: Z, r: RAMPART_COLLIDER_R })
    }

    /* 망루 — 60칸마다. 상한 `END - SEG` 도 원본(`END - 8`) 그대로다 */
    for (let x = RAMPART_TOWER_START; x < RAMPART_END - RAMPART_SEG; x += RAMPART_TOWER_STEP) {
      const tx = side * x
      const tw = new THREE.Mesh(cyl(4.6, 5.6, H + 9, 16), STONE2)
      tw.position.set(tx, (H + 9) / 2, Z)
      add(group, tw, true, true)
      const rim = new THREE.Mesh(cyl(5.6, 5.0, 1.8, 16), TRIM)
      rim.position.set(tx, H + 9.6, Z)
      add(group, rim, true)
      for (let k = 0; k < 9; k++) {
        const a = (k / 9) * TAU
        const mr = new THREE.Mesh(rboxGeo(1.7, 2.1, 1.3, 0.15, 0), TRIM)
        mr.position.set(tx + Math.cos(a) * 5.0, H + 11.4, Z + Math.sin(a) * 5.0)
        mr.rotation.y = -a
        add(group, mr)
      }
      const roof = new THREE.Mesh(cone(5.9, 8.5, 16), STONE)
      roof.position.set(tx, H + 16.6, Z)
      add(group, roof, true)
      const fin = new THREE.Mesh(sphere(0.8, 12, 10), LAMP)
      fin.position.set(tx, H + 21.4, Z)
      add(group, fin)
      // r155 부터 PointLight 밝기가 물리 단위다. 원본 수치를 그대로 둔다 —
      // 톤 보정은 createSceneKit 의 노출값과 함께 한 곳에서 결정할 문제다.
      const lt = new THREE.PointLight(0xffc76a, 0.9, 30)
      lt.position.set(tx, H + 21, Z)
      group.add(lt)
      colliders.push({ x: tx, z: Z, r: RAMPART_TOWER_COLLIDER_R })
    }

    /* 어깨벽 — 문기둥과 성벽을 잇는다 */
    const sx = side * RAMPART_SHOULDER_X
    const sh = new THREE.Mesh(rboxGeo(12, H + 7, 6.2, 0.4, 0), STONE2)
    sh.position.set(sx, (H + 7) / 2, Z)
    add(group, sh, true)
    const shc = new THREE.Mesh(rboxGeo(13.4, 2.2, 7.4, 0.3, 0), GOLD)
    shc.position.set(sx, H + 8.2, Z)
    add(group, shc)
    colliders.push({ x: sx, z: Z, r: RAMPART_SHOULDER_COLLIDER_R })
  }

  return { group, colliders }
}
